/* ===== style-3 ===== */

@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+TC:wght@400;700&family=Montserrat:wght@300;500;700&display=swap');
:root {
  --mono-app-vh: 1vh;
  --mono-keyboard-offset: 0px;
  --mono-chat-page-h: 100%;
}
body {
  font-family: 'Montserrat', 'Noto Serif TC', serif;
  background: #ffffff;
  color: #1a1a1a;
  min-height: calc(var(--mono-app-vh, 1vh) * 100);
  height: calc(var(--mono-app-vh, 1vh) * 100);
  overflow: hidden;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.phone-container {
  position: relative;
  width: 100%;
  max-width: 390px;
  height: calc((var(--mono-app-vh, 1vh) * 100) - 40px);
  max-height: 844px;
  margin: 20px auto;
  border: 14px solid #1a1a1a;
  border-radius: 48px;
  background: #fff;
  overflow: hidden;
  box-shadow: 0 15px 40px rgba(0,0,0,0.3);
  aspect-ratio: 390/844;
}
.phone-header {
  height: 44px;
  background: transparent;
  border-radius: 34px 34px 0 0;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  z-index: 90;
  pointer-events: none;
}
.phone-notch {
  width: 160px;
  height: 22px;
  background: #1a1a1a;
  border-radius: 0 0 18px 18px;
  pointer-events: auto;
}
.contacts-drawer {
  position: absolute;
  top: 44px;
  left: 0;
  width: 85%;
  max-width: 300px;
  height: calc(100% - 104px);
  background: #fff;
  border-right: 1px solid #1a1a1a;
  z-index: 80;
  transform: translateX(-100%);
  transition: transform 0.3s ease;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.contacts-drawer.open { transform: translateX(0); }
.phone-nav {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60px;
  background: #fff;
  border-top: 1px solid #1a1a1a;
  display: flex;
  justify-content: space-around;
  align-items: center;
  z-index: 90;
}
.nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 14.28%;
  height: 100%;
  cursor: pointer;
  transition: all 0.2s;
}
.nav-item.active { background: #1a1a1a; color: #fff; }
.nav-icon { font-size: calc(16px * var(--fs, 1)); margin-bottom: 3px; }
.nav-text { font-size: calc(7px * var(--fs, 1)); text-transform: uppercase; letter-spacing: 0.5px; font-weight: 500; }
.msg-row { display: flex; width: 100%; margin-bottom: 1rem; align-items: flex-end; gap: 8px; position: relative; }
.msg-row.user { justify-content: flex-end; }
.msg-row.ai { justify-content: flex-start; }
.msg-meta { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.msg-avatar { width: 32px; height: 32px; border-radius: 50%; border: 1px solid #1a1a1a; object-fit: cover; flex-shrink: 0; }
.msg-name { font-size: calc(9px * var(--fs, 1)); text-transform: uppercase; letter-spacing: 0.5px; color: var(--chat-meta-name-color, #999); white-space: nowrap; }
/* Chat meta text color overrides via CSS vars (set by JS) */
.msg-time-read { color: var(--chat-meta-time-color, #bbb) !important; }
.msg-time-read span { color: inherit !important; }
.msg-row.user .msg-content { align-items: flex-end; }
.msg-row.ai .msg-content { align-items: flex-start; }
.bubble { padding: 12px 16px; font-size: calc(14px * var(--fs, 1)); line-height: 1.6; letter-spacing: 0.02em; cursor: pointer; user-select: none; }
.bubble-ai { background: #fff; color: #1a1a1a; border-radius: 18px; border-bottom-left-radius: 4px; box-shadow: 0 1px 4px rgba(0,0,0,0.07); }
.bubble-user { background: #2a2a2a; color: #fff; border-radius: 18px; border-bottom-right-radius: 4px; }
.wechat-style .bubble-ai { background: #fff; color: #1a1a1a; border-radius: 18px; border-bottom-left-radius: 4px; box-shadow: 0 1px 4px rgba(0,0,0,0.07); }
.wechat-style .bubble-user { background: #2a2a2a; color: #fff; border-radius: 18px; border-bottom-right-radius: 4px; }
