/* ══════════════════════════════════════════════
   BUBBLE PRESET: 推し发光文字 Oshi Glow
   ══════════════════════════════════════════════ */
/* 全局变量，定义原图中的发光颜色 */
.bubble-preset-oshiglow {
    --glow-blue: #cfd3d8;  /* 主体的浅灰喷枪发光 */
    --glow-pink: #e5e5e5;  /* 部分爱心符号的浅灰发光 */
}

/* 文本块基础样式 */
.bubble-preset-oshiglow .bubble-ai,
.bubble-preset-oshiglow .bubble-user {
    width: fit-content !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
    line-height: 1.72 !important;
    /* 默认是手写风；如果用户设置了全局美化字体，最后加载的全局字体会覆盖这里 */
    font-family: 'Zen Maru Gothic', 'Rounded Mplus 1c', 'Comic Sans MS', sans-serif;
    font-weight: 700 !important;
    font-size: 13.5px !important;
    color: #ffffff !important; /* 文字本体是纯白色 */
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    padding: 2px 4px !important;
    position: relative !important;
    isolation: isolate !important;
    overflow: visible !important;
    white-space: normal !important;
    word-break: break-word !important;
    overflow-wrap: anywhere !important;
    /* 核心魔法：利用多层紧密且模糊的阴影，制造出喷枪边缘发光效果 */
    text-shadow: 
        -1px -1px 2px var(--glow-blue),
         1px -1px 2px var(--glow-blue),
        -1px  1px 2px var(--glow-blue),
         1px  1px 2px var(--glow-blue), /* 内层紧密轮廓 */
         0 0 6px var(--glow-blue),      /* 中层柔和发光 */
         0 0 13px var(--glow-blue),
         0 0 20px var(--glow-blue);     /* 外层弥散喷枪感 */
}

.bubble-preset-oshiglow .bubble-ai::before,
.bubble-preset-oshiglow .bubble-user::before {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    border-radius: 18px !important;
    background: rgba(255,255,255,0.03) !important;
    backdrop-filter: blur(10px) saturate(1.12) !important;
    -webkit-backdrop-filter: blur(10px) saturate(1.12) !important;
    z-index: -1 !important;
    pointer-events: none !important;
}
.bubble-preset-oshiglow .bubble-ai::after,
.bubble-preset-oshiglow .bubble-user::after { display: none !important; }
.bubble-preset-oshiglow .msg-content { overflow: visible !important; }
.bubble-preset-oshiglow .oshi-kaomoji {
    display: block !important;
    margin: 0 0 1px 1px !important;
    font-family: inherit !important;
    font-size: 0.75em !important;
    line-height: 1 !important;
    color: #000000 !important;
    text-shadow: none !important;
    filter: none !important;
    letter-spacing: 0 !important;
}
.bubble-preset-oshiglow .bubble-user .oshi-kaomoji {
    text-align: right !important;
    margin: 0 1px 1px 0 !important;
}
.bubble-preset-oshiglow .oshi-heart-deco {
    display: inline-block !important;
    margin-left: 0.35em !important;
    color: #ffffff !important;
    text-shadow: 
        -1px -1px 2px var(--glow-pink),
         1px -1px 2px var(--glow-pink),
        -1px  1px 2px var(--glow-pink),
         1px  1px 2px var(--glow-pink),
         0 0 6px var(--glow-pink),
         0 0 13px var(--glow-pink),
         0 0 20px var(--glow-pink) !important;
    filter: none !important;
}
/* 针对特殊粉色爱心的发光覆盖 */
.bubble-preset-oshiglow .pink-heart {
    text-shadow: 
        -1px -1px 2px var(--glow-pink),
         1px -1px 2px var(--glow-pink),
        -1px  1px 2px var(--glow-pink),
         1px  1px 2px var(--glow-pink),
         0 0 6px var(--glow-pink),
         0 0 13px var(--glow-pink),
         0 0 20px var(--glow-pink);
}

/* 字体大小微调，还原原图的错落感 */
