/* 布局排版控制 */
.bubble-preset-oshiglow .align-left { align-self: flex-start; margin-left: 20px; }
.bubble-preset-oshiglow .align-right { align-self: flex-end; margin-right: 20px; }
.bubble-preset-oshiglow .align-center { align-self: center; }

/* 微调倾斜和边距模拟随意摆放的感觉 */
.bubble-preset-oshiglow .tilt-1 { transform: rotate(-2deg); }
.bubble-preset-oshiglow .tilt-2 { transform: rotate(1deg); margin-left: 60px; }
/* ════════════════════════════════════
   BUBBLE PRESET: 复古手账风 Vintage Journal
   ════════════════════════════════════ */
.bubble-preset-journal {
    --yuna-base: #e6ece8;
    --yuna-border: #7c9987;
    --yuna-text: #48524a;
    --do-base: #5f4b43;
    --do-border: #d0c4b6;
    --do-text: #fdf9ef;
    --noise: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.7' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.08'/%3E%3C/svg%3E");
}
/* 背景与字体 */
.bubble-preset-journal #chatBox,
.bubble-preset-journal .gc-messages {
    background-color: transparent !important;
}
.bubble-preset-journal .chat-header,
.bubble-preset-journal .gc-header {
    background: rgba(230,236,232,0.95) !important;
    border-bottom: 0.5px solid #7c9987 !important;
}
.bubble-preset-journal .input-row,
.bubble-preset-journal #inputBar,
.bubble-preset-journal .chat-input-area {
    background: rgba(230,236,232,0.95) !important;
    border-top: 0.5px solid #7c9987 !important;
}
/* 隐藏原始气泡，由 JS 注入新 HTML 结构 */
.bubble-preset-journal .bubble-ai,
.bubble-preset-journal .bubble-user {
    background: transparent !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 0 !important;
    border: none !important;
    color: inherit !important;
}
.bubble-preset-journal .bubble-ai::before,
.bubble-preset-journal .bubble-ai::after,
.bubble-preset-journal .bubble-user::before,
.bubble-preset-journal .bubble-user::after { display: none !important; }

/* ── 尤娜气泡结构（AI） ── */
.bubble-preset-journal .yuna-outer {
    background: var(--yuna-border);
    padding: 1.5px;
    clip-path: polygon(8px 0, calc(100% - 8px) 0, calc(100% - 8px) 8px, 100% 8px, 100% calc(100% - 8px), calc(100% - 8px) calc(100% - 8px), calc(100% - 8px) 100%, 8px 100%, 8px calc(100% - 8px), 0 calc(100% - 8px), 0 8px, 8px 8px);
    filter: drop-shadow(1px 2px 3px rgba(0,0,0,0.08));
}
.bubble-preset-journal .yuna-inner {
    background-color: var(--yuna-base);
    background-image: var(--noise);
    color: var(--yuna-text); font-size: 14.5px; line-height: 1.6;
    padding: 10px 18px; position: relative;
    clip-path: polygon(7.5px 0, calc(100% - 7.5px) 0, calc(100% - 7.5px) 7.5px, 100% 7.5px, 100% calc(100% - 7.5px), calc(100% - 7.5px) calc(100% - 7.5px), calc(100% - 7.5px) 100%, 7.5px 100%, 7.5px calc(100% - 7.5px), 0 calc(100% - 7.5px), 0 7.5px, 7.5px 7.5px);
}
.bubble-preset-journal .yuna-inner::before {
    content: ''; position: absolute; top: 3px; left: 3px; right: 3px; bottom: 3px;
    border: 1.2px dashed var(--yuna-border);
    clip-path: polygon(6px 0, calc(100% - 6px) 0, calc(100% - 6px) 6px, 100% 6px, 100% calc(100% - 6px), calc(100% - 6px) calc(100% - 6px), calc(100% - 6px) 100%, 6px 100%, 6px calc(100% - 6px), 0 calc(100% - 6px), 0 6px, 6px 6px);
    pointer-events: none;
}
/* ── 道贤气泡结构（用户） ── */
.bubble-preset-journal .do-outer {
    background: var(--do-border); padding: 1.5px;
    clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 8px, 100% calc(100% - 8px), calc(100% - 8px) 100%, 8px 100%, 0 calc(100% - 8px), 0 8px);
    filter: drop-shadow(2px 3px 4px rgba(0,0,0,0.15));
}
.bubble-preset-journal .do-inner {
    background-color: var(--do-base); background-image: var(--noise);
    color: var(--do-text); font-size: 14.5px; line-height: 1.6;
    padding: 10px 18px 10px 24px; position: relative;
    clip-path: polygon(7.5px 0, calc(100% - 7.5px) 0, 100% 7.5px, 100% calc(100% - 7.5px), calc(100% - 7.5px) 100%, 7.5px 100%, 0 calc(100% - 7.5px), 0 7.5px);
}
.bubble-preset-journal .do-inner::before {
    content: ''; position: absolute; inset: 4px; border: 1px solid rgba(255,255,255,0.25);
    clip-path: polygon(6px 0, calc(100% - 6px) 0, 100% 6px, 100% calc(100% - 6px), calc(100% - 6px) 100%, 6px 100%, 0 calc(100% - 6px), 0 6px);
    pointer-events: none;
}
/* 活页打孔线 */
.bubble-preset-journal .do-holes {
    position: absolute; top: 12px; bottom: 12px; left: 6px; width: 6px;
    background: radial-gradient(circle at 3px 4px, var(--do-base) 2px, transparent 2px),
                radial-gradient(circle at 3px 4px, var(--do-border) 3px, transparent 3px);
    background-size: 100% 8px; z-index: 2; opacity: 0.9; pointer-events: none;
}

/* ── 手账贴纸层系统 ── */
.bubble-preset-journal .j-sc {
    position: relative; /* 贴纸定位锚点 */
    display: inline-block; /* 包裹内容自适应宽度 */
    max-width: 100%;
}
.bubble-preset-journal .j-sl {
    position: absolute;
    z-index: 20;
    pointer-events: none;
    /* 默认尺寸由 JS 动态写入 */
}
/* die-cut 白边模切效果 */
.bubble-preset-journal .j-dc {
    filter:
        drop-shadow(1px  0px 0 #fff) drop-shadow(-1px  0px 0 #fff)
        drop-shadow(0px  1px 0 #fff) drop-shadow( 0px -1px 0 #fff)
        drop-shadow(1px  1px 0 #fff) drop-shadow(-1px -1px 0 #fff)
        drop-shadow(2px 3px 4px rgba(0,0,0,0.22));
}
/* 纸质标签 */
.bubble-preset-journal .j-lbl {
    font-size: 12px; line-height: 1.2;
    box-shadow: 2px 3px 5px rgba(0,0,0,0.15);
    border-radius: 2px; padding: 1px 8px;
    white-space: nowrap;
}
.bubble-preset-journal .j-lbl-lovely {
    background: #e2e8e4; color: #7c9987;
    border: 1px solid #cbd7ce; font-weight: bold;
}
.bubble-preset-journal .j-lbl-vibes {
    background: #a38c78; color: #fdf9ef;
    border: 1px solid #d0c4b6; text-align: center;
    white-space: normal;
}
.bubble-preset-journal .j-lbl-special {
    background: #a38c78; color: #fdf9ef;
    border-radius: 10px; padding: 1px 10px;
    border: 1px dashed #d0c4b6;
    box-shadow: 0 0 0 1.5px #a38c78, 2px 3px 5px rgba(0,0,0,0.2);
}
.bubble-preset-journal .j-bookmark {
    width: 12px; background: #5f4b43;
    border: 1px solid #d0c4b6; border-bottom: none;
    clip-path: polygon(0 0,100% 0,100% 100%,50% 82%,0 100%);
    display: flex; justify-content: center; align-items: flex-start;
    box-shadow: inset 0 0 3px rgba(0,0,0,0.4);
}
.bubble-preset-journal .j-bookmark::after {
    content: '★'; color: #d0c4b6; font-size: 6px; margin-top: 10px;
}
/* 让气泡不裁掉外溢的贴纸 */
.bubble-preset-journal .bubble-ai,
.bubble-preset-journal .bubble-user,
.bubble-preset-journal .msg-content,
.bubble-preset-journal .msg-row { overflow: visible !important; }
