#chatPage.chat-theme-frosted {
    --theme-frosted-text: rgba(255,255,255,0.96);
    --theme-frosted-subtext: rgba(255,255,255,0.74);
    --theme-frosted-border: rgba(255,255,255,0.28);
    --theme-frosted-border-soft: rgba(255,255,255,0.18);
    --theme-frosted-glass: rgba(255,255,255,0.16);
    --theme-frosted-glass-strong: rgba(255,255,255,0.22);
    --theme-frosted-shadow: 0 10px 28px rgba(10,20,28,0.16);
    --theme-frosted-name-color: #ffffff;
    position: relative;
    isolation: isolate;
    display: grid !important;
    grid-template-rows: auto auto minmax(0,1fr) auto auto auto auto;
    align-items: stretch;
    height: var(--mono-chat-page-h, 100%) !important;
    max-height: var(--mono-chat-page-h, 100%) !important;
    min-height: 0 !important;
    overflow: hidden !important;
    box-sizing: border-box;
    background: linear-gradient(180deg, rgba(168,197,205,0.74) 0%, rgba(152,180,190,0.62) 100%) !important;
}
#chatPage.chat-theme-frosted::before,
#chatPage.chat-theme-frosted::after {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
}
#chatPage.chat-theme-frosted::before {
    background-image: var(--mono-chat-bg-image, none);
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    z-index: 0;
}
#chatPage.chat-theme-frosted::after {
    background: linear-gradient(180deg, rgba(20,34,42,0.18) 0%, rgba(20,34,42,0.06) 20%, rgba(20,34,42,0.10) 55%, rgba(20,34,42,0.18) 100%);
    z-index: 0;
