/* ════════════════════════════════════
   角色间聊天室样式 CC = CharChat
   ════════════════════════════════════ */
@keyframes ccPulse {
  0%,100% { opacity:0.3; transform:scale(0.8); }
  50% { opacity:1; transform:scale(1.1); }
}
@keyframes tdFadeIn {
  from { opacity:0; }
  to   { opacity:1; }
}
@keyframes ccFadeSlideIn {
  from { opacity:0; transform:translateY(10px); }
  to   { opacity:1; transform:translateY(0); }
}
.cc-msg-appear {
  animation: ccFadeSlideIn 0.28s ease both;
}
.cc-typing-bubble {
  display:inline-flex; align-items:center; gap:4px;
  background:#fff; border-radius:2px 12px 12px 2px;
  padding:10px 14px; box-shadow:0 1px 2px rgba(0,0,0,0.08);
}
.cc-typing-bubble span {
  width:5px; height:5px; border-radius:50%; background:#aaa;
  animation:ccPulse 0.9s infinite;
}
.cc-typing-bubble span:nth-child(2) { animation-delay:0.15s; }
.cc-typing-bubble span:nth-child(3) { animation-delay:0.3s; }
/* 今日轮数徽章 */
.cc-turns-badge {
  font-size:10px; background:rgba(255,255,255,0.18);
  border-radius:10px; padding:1px 7px; margin-left:5px;
  color:#555; display:inline-block; vertical-align:middle;
}
/* CC聊天室消息行 */
.cc-msg-row { display:flex; align-items:flex-end; gap:8px; margin:4px 10px; }
.cc-msg-row.cc-right { flex-direction:row-reverse; }
.cc-avatar { width:38px; height:38px; border-radius:6px; object-fit:cover; flex-shrink:0; }
.cc-avatar-placeholder { width:38px; height:38px; border-radius:6px; background:#bbb; display:flex; align-items:center; justify-content:center; font-size:15px; font-weight:700; color:#fff; flex-shrink:0; }
.cc-msg-body { display:flex; flex-direction:column; max-width:68%; }
.cc-msg-row.cc-right .cc-msg-body { align-items:flex-end; }
.cc-sender-name { font-size:10px; color:#888; margin-bottom:3px; margin-left:2px; }
.cc-msg-row.cc-right .cc-sender-name { margin-left:0; margin-right:2px; }
.cc-bubble { padding:10px 13px; font-size:14px; line-height:1.6; border-radius:2px; word-break:break-word; position:relative; }
.cc-bubble-left { background:#fff; color:#1a1a1a; border-radius:2px 12px 12px 2px; box-shadow:0 1px 2px rgba(0,0,0,0.08); }
.cc-bubble-left::before { content:''; position:absolute; left:-6px; top:10px; border:6px solid transparent; border-right-color:#fff; border-left:0; }
.cc-bubble-right { background:#9eea6a; color:#1a1a1a; border-radius:12px 2px 2px 12px; }
.cc-bubble-right::after { content:''; position:absolute; right:-6px; top:10px; border:6px solid transparent; border-left-color:#9eea6a; border-right:0; }
.cc-time-divider { text-align:center; font-size:10px; color:#aaa; margin:10px 0; }
.cc-msg-meta {
  font-size: 9px;
  color: #9a9a9a;
  margin-top: 4px;
  display: flex;
  gap: 4px;
  align-items: center;
}
.cc-msg-row.cc-right .cc-msg-meta { justify-content: flex-end; }
.cc-msg-row:not(.cc-right) .cc-msg-meta { justify-content: flex-start; }
.cc-chat-empty-tip {
  text-align: center;
  padding: 40px 20px;
  color: #bbb;
}
.cc-rich-media-wrap {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-width: 220px;
}
.cc-rich-media-wrap .bubble-image {
  max-width: 220px;
}
.cc-rich-media-wrap .bubble-voice {
  margin: 0;
}
.cc-msg-row .bubble-voice {
  max-width: 220px;
}
.cc-msg-row .bubble-user.bubble-voice {
  background: #9eea6a;
  color: #1a1a1a;
}
.cc-msg-row .bubble-ai.bubble-voice {
  background: #fff;
  color: #1a1a1a;
}
