.heart-voice-notif {
  width: 100%;
  position: relative;
  border-radius: 18px;
  padding: 8px 10px 9px;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.84) 0%, rgba(243,244,249,0.78) 100%);
  border: 1px solid rgba(255,255,255,0.82);
  box-shadow:
    0 14px 30px rgba(22,27,45,0.18),
    0 2px 8px rgba(22,27,45,0.08),
    inset 0 1px 0 rgba(255,255,255,0.75);
