  animation: heartVoiceNotifIn 0.42s cubic-bezier(.2,.85,.2,1);
  transition: margin-top 0.28s ease, transform 0.28s ease, box-shadow 0.28s ease;
  cursor: pointer;
  pointer-events: auto;
