body.ios-fullscreen .phone-header { border-radius: 0; height: env(safe-area-inset-top, 44px); min-height: 44px; }
body.ios-fullscreen .phone-notch { display: none; }
body.ios-fullscreen .page { top: env(safe-area-inset-top, 44px); bottom: calc(60px + env(safe-area-inset-bottom, 0px)); }
body.ios-fullscreen .phone-nav { bottom: env(safe-area-inset-bottom, 0px); padding-bottom: env(safe-area-inset-bottom, 0px); height: calc(60px + env(safe-area-inset-bottom, 0px)); }
body.ios-fullscreen .chat-header { margin-top: 0; }
body.ios-fullscreen .contacts-drawer { top: env(safe-area-inset-top, 44px); height: calc(100% - env(safe-area-inset-top, 44px) - 60px - env(safe-area-inset-bottom, 0px)); }
