/* ===== HOME SCREEN ===== */
/* ===== HOME SCREEN PAGES (swipeable) ===== */
.home-screen {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: #ffffff;
  z-index: 85;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 0;
  /* Global guard: prevents browser selection UI appearing during long-press drag */
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  user-select: none;
}
.home-screen::-webkit-scrollbar { display: none; }
/* Pages container — horizontal scroll, stops above the dock */
.home-pages-wrapper {
  display: flex;
  flex-direction: row;
  width: 300%;
  flex: 1;
  min-height: 0;
  transition: transform 0.38s cubic-bezier(.4,0,.2,1);
  will-change: transform;
}
.home-page {
  width: 33.333333%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  flex-shrink: 0;
}
.home-page::-webkit-scrollbar { display: none; }
/* ── FLIP PAGE MODE ── */
/* When flip mode is active the wrapper turns into a perspective stage */
/* ── flip-mode: no special layout override needed;
   goToHomePageMulti handles translation via transform.
   We only mark the screen so JS knows the mode is active. ── */
.home-screen.flip-mode .home-pages-wrapper {
  /* keep standard translateX scroll behaviour */
}
/* In flip mode, each page must scroll vertically so hidden content is reachable */
.home-screen.flip-mode .home-page {
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
/* Tap-zone overlay – narrow edge strips (44px) so center content stays fully clickable */
#flipTapLeft, #flipTapRight {
  display: none;
  position: absolute;
  top: 0;
  bottom: 0;
  width: 44px;
  z-index: 90;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
#flipTapLeft  { left: 0; }
#flipTapRight { right: 0; }
/* Show tap zones only when flip-mode is active */
.home-screen.flip-mode #flipTapLeft,
.home-screen.flip-mode #flipTapRight {
  display: block;
}
/* Flip-mode side nav arrow buttons */
.flip-side-btn {
  display: none;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 95;
  width: 22px;
  height: 54px;
  background: rgba(26,26,26,0.13);
  border: none;
  border-radius: 0 10px 10px 0;
  cursor: pointer;
  align-items: center;
  justify-content: center;
  color: rgba(26,26,26,0.55);
  font-size: 13px;
  padding: 0;
  transition: background 0.18s, color 0.18s;
  -webkit-tap-highlight-color: transparent;
  backdrop-filter: blur(4px);
  pointer-events: auto;
}
#flipSideBtnLeft  { left: 0; border-radius: 0 10px 10px 0; }
#flipSideBtnRight { right: 0; border-radius: 10px 0 0 10px; }
#flipSideBtnLeft:active, #flipSideBtnRight:active { background: rgba(26,26,26,0.28); color: #1a1a1a; }
/* Show side buttons only in flip-mode */
.home-screen.flip-mode .flip-side-btn {
  display: flex;
}
/* Visual ripple feedback on tap */
@keyframes flipTapRipple {
  0%   { opacity: 0.18; transform: scale(0.7); }
  60%  { opacity: 0.10; transform: scale(1.15); }
  100% { opacity: 0;    transform: scale(1.4); }
}
.flip-tap-ripple {
  position: absolute;
  top: 50%;
  width: 80px;
  height: 80px;
  margin-top: -40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.55);
  pointer-events: none;
  animation: flipTapRipple 0.38s ease-out forwards;
}
#flipTapLeft  .flip-tap-ripple { left:  calc(50% - 40px); }
#flipTapRight .flip-tap-ripple { right: calc(50% - 40px); }
/* ── NON-FULLSCREEN: force home-pages-wrapper to be a position context
   so each home-page can be absolutely sized and scroll independently ──
   NOTE: excluded from flip-mode to prevent CSS specificity conflict     ── */
body:not(.ios-fullscreen) .home-pages-wrapper:not(.flip-mode-wrapper) {
  overflow: hidden;
  position: relative;
}
body:not(.ios-fullscreen) .home-screen:not(.flip-mode) .home-pages-wrapper {
  overflow: hidden;
  position: relative;
  clip-path: none;
}
body:not(.ios-fullscreen) .home-screen:not(.flip-mode) .home-page {
  position: relative;
  top: unset;
  bottom: unset;
  width: 33.333333%;
  height: 100%;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  flex-shrink: 0;
}
body:not(.ios-fullscreen) .home-screen:not(.flip-mode) .home-page#homePage1 {
  left: unset;
}
body:not(.ios-fullscreen) .home-screen:not(.flip-mode) .home-page#homePage2 {
  left: unset;
