}
.ig-stories-row::-webkit-scrollbar { display: none; }
/* Each story circle item (user or char) */
.ig-story-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
  user-select: none;
}
.ig-story-item.ig-char-item { cursor: pointer; }
.ig-story-item.ig-user-item { cursor: default; }
/* Gradient ring wrapper — Instagram barbie-pink → orange for unread */
.ig-story-ring {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  /* IG-style gradient: pink → red-pink → purple-pink */
  background: linear-gradient(45deg, #f09433 0%, #e6683c 25%, #dc2743 50%, #cc2366 75%, #bc1888 100%);
  padding: 2.5px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.18s;
}
.ig-char-item .ig-story-ring:active { transform: scale(0.91); }
/* Seen / already read → flat grey */
.ig-story-ring.seen {
  background: #c8c8c8;
}
/* User's own circle — plain grey, not a story */
.ig-user-ring {
  background: #d0d0d0;
}
/* Inner avatar circle with white border gap */
.ig-story-inner {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 2.5px solid #fff;
