  background: #efefef;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
}
.ig-story-inner img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
/* Name label under circle */
.ig-story-name {
  font-size: calc(9px * var(--fs, 1));
  font-weight: 600;
  color: #444;
  max-width: 58px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: center;
}
.ig-user-item .ig-story-name {
  color: #888;
}
/* No chars placeholder (shown inline in the row) */
.ig-no-chars {
  color: #bbb;
