.loc-trace-place { font-size: calc(11px * var(--fs, 1)); color: #333; line-height: 1.4; flex: 1; }
.loc-trace-activity { font-size: calc(10px * var(--fs, 1)); color: #888; line-height: 1.4; margin-top: 2px; flex: 1; }
