.family-widget-baby-icon { font-size: 14px; }
.family-widget-baby-name {
  font-size: 9px;
  font-weight: 700;
  color: rgba(255,255,255,0.9);
  letter-spacing: 0.8px;
  text-align: center;
  font-family: 'Montserrat', sans-serif;
