}
.dating-msg-time { font-size: 9px; color: var(--chat-meta-time-color, #bbb); align-self: flex-end; margin-bottom: 2px; flex-shrink: 0; }
/* ── Dating: LINE preset overrides ── */
#datingChatPage.bubble-preset-line .dating-chat-bg { background: #8aafd4 !important; }
#datingChatPage.bubble-preset-line .dating-msg-row.char .dating-msg-bubble { background: #ffffff !important; color: #000000 !important; border-radius: 18px !important; overflow: visible !important; position: relative !important; }
