#datingChatPage.bubble-preset-line .dating-msg-row.user .dating-msg-bubble { background: #4cd964 !important; color: #000000 !important; border-radius: 18px !important; overflow: visible !important; position: relative !important; }
#datingChatPage.bubble-preset-line .dating-msg-row.user .dating-msg-bubble::after { content: '' !important; position: absolute !important; bottom: 8px !important; right: -9px !important; width: 14px !important; height: 16px !important; background: #4cd964 !important; clip-path: polygon(0% 0%, 0% 100%, 100% 50%) !important; box-shadow: none !important; border-style: none !important; border-width: 0 !important; border-radius: 0 !important; }
/* ── Dating: WeChat preset overrides ── */
#datingChatPage.bubble-preset-wechat .dating-chat-bg { background: #ededed !important; }
#datingChatPage.bubble-preset-wechat .dating-msg-row.char .dating-msg-bubble { background: #ffffff !important; color: #000000 !important; border-radius: 4px !important; }
#datingChatPage.bubble-preset-wechat .dating-msg-row.user .dating-msg-bubble { background: #95ec69 !important; color: #000000 !important; border-radius: 4px !important; }
/* ── Dating: iMessage preset overrides ── */
#datingChatPage.bubble-preset-imessage .dating-chat-bg { background: #ffffff !important; }
#datingChatPage.bubble-preset-imessage .dating-msg-row.char .dating-msg-bubble { background: #e5e5ea !important; color: #000000 !important; border-radius: 18px 18px 18px 5px !important; }
#datingChatPage.bubble-preset-imessage .dating-msg-row.user .dating-msg-bubble { background: #007aff !important; color: #ffffff !important; border-radius: 18px 18px 5px 18px !important; }
/* ── Dating: user avatar ── */
.dating-msg-row.user .dating-user-avatar {
  width: 32px; height: 32px; border-radius: 50%; background: #e0d5da;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; color: #888; overflow: hidden; flex-shrink: 0; align-self: flex-end;
}
.dating-msg-row.user .dating-user-avatar img { width: 100%; height: 100%; object-fit: cover; }
/* ── Dating Plus Panel ── */
#datingPlusPanel {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0; right: 0;
  background: #fff;
  border-top: 1.5px solid #e8dde2;
  border-bottom: none;
  padding: 12px 12px 10px;
  gap: 10px;
  flex-wrap: wrap;
  z-index: 200;
  box-shadow: 0 -4px 16px rgba(0,0,0,0.08);
  animation: panelSlideUp 0.18s ease;
}
#datingPlusPanel.show { display: flex; }
.dating-plus-btn {
  display: flex; flex-direction: column; align-items: center; gap: 5px;
  padding: 10px 14px; border: 1px solid #e8dde2; background: #fff9fb;
  cursor: pointer; border-radius: 10px; transition: all 0.15s; min-width: 58px;
}
.dating-plus-btn:hover, .dating-plus-btn:active { background: #e8557a; color: #fff; border-color: #e8557a; }
.dating-plus-btn i { font-size: 17px; color: inherit; }
.dating-plus-btn span { font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: inherit; white-space: nowrap; }
/* ── Dating Gift Bubble ── */
.dating-gift-bubble {
  background: linear-gradient(135deg, #fff0f5 0%, #ffe4ef 100%);
  border: 1.5px solid #f4b8cf; border-radius: 16px; padding: 14px 16px;
  max-width: 230px; font-size: 12px; line-height: 1.6;
  box-shadow: 0 4px 16px rgba(232,85,122,0.13);
}
.dating-gift-header {
  font-size: 10px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 1.2px; color: #e8557a; margin-bottom: 7px;
  display: flex; align-items: center; gap: 5px;
}
.dating-gift-name { font-size: 14px; font-weight: 700; color: #1a1a1a; margin-bottom: 3px; }
.dating-gift-shop { font-size: 10px; color: #aaa; margin-bottom: 6px; }
.dating-gift-price { font-size: 16px; font-weight: 800; color: #e8557a; margin-bottom: 8px; }
.dating-gift-note {
  font-size: 12px; color: #888; font-style: italic;
  border-top: 1px solid #f4b8cf; padding-top: 7px; margin-top: 4px; line-height: 1.5;
}
/* ── Dating Order / Transfer Bubble ── */
.dating-order-bubble {
  background: #f8f8f8; border: 1px solid #e0e0e0; border-radius: 12px;
  padding: 12px 14px; max-width: 220px; font-size: 12px;
}
.dating-order-header { font-size: 10px; font-weight: 700; color: #888; margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.5px; }
.dating-order-name { font-size: 13px; font-weight: 600; color: #1a1a1a; margin-bottom: 4px; }
.dating-order-price { font-size: 15px; font-weight: 700; color: #1a1a1a; margin-bottom: 4px; }
.dating-order-note { font-size: 10px; color: #aaa; margin-top: 4px; }
.dating-order-status { font-size: 10px; margin-top: 6px; font-style: italic; }
.dating-order-status.paid { color: #4caf50; }
.dating-order-status.pending { color: #ff9800; }
.dating-transfer-bubble {
  background: #1a1a1a; color: #fff; border-radius: 12px;
  padding: 12px 14px; max-width: 200px;
}
.dating-transfer-title { font-size: 9px; font-weight: 700; opacity: 0.5; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 5px; }
.dating-transfer-amount { font-size: 20px; font-weight: 700; margin-bottom: 4px; }
.dating-transfer-note { font-size: 11px; opacity: 0.6; margin-bottom: 6px; }
.dating-transfer-status { font-size: 10px; opacity: 0.5; }
.dating-typing-dots { display: flex; gap: 4px; align-items: center; padding: 4px 6px; }
.dating-typing-dots span { width: 6px; height: 6px; border-radius: 50%; background: #c0aab5; animation: datingDot 1.2s infinite; }
.dating-typing-dots span:nth-child(2) { animation-delay: 0.2s; }
.dating-typing-dots span:nth-child(3) { animation-delay: 0.4s; }
@keyframes datingDot { 0%,80%,100%{transform:scale(0.6);opacity:0.5} 40%{transform:scale(1);opacity:1} }
.dating-chat-input-bar {
  background: #fff; border-top: 0.5px solid #e8e0e4;
  padding: 8px 12px; display: flex; align-items: flex-end; gap: 8px;
  flex-shrink: 0; padding-bottom: calc(8px + env(safe-area-inset-bottom, 0));
}
.dating-chat-input {
  flex: 1; background: #f7f0f3; border: none; border-radius: 20px;
  padding: 9px 14px; font-size: 14px; color: #1a1a1a; resize: none;
  max-height: 100px; outline: none; font-family: inherit;
}
.dating-chat-send {
  background: #1a1a1a; border: none; border-radius: 50%;
  width: 36px; height: 36px; display: flex; align-items: center; justify-content: center;
  cursor: pointer; color: #fff; font-size: 14px; flex-shrink: 0;
  transition: transform 0.2s;
}
.dating-chat-send:active { transform: scale(0.9); }
.dating-chat-send:disabled { background: #ccc; }
/* 回复 button — separate from send */
.dating-chat-reply-btn {
  background: none;
  border: 1.5px solid #2a2a2a;
  border-radius: 50%;
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; color: #1a1a1a; font-size: 13px; flex-shrink: 0;
  transition: transform 0.2s, background 0.15s;
}
.dating-chat-reply-btn:active { transform: scale(0.9); background: #f5f0f2; }
.dating-chat-reply-btn:disabled { border-color: #ccc; color: #ccc; cursor: not-allowed; }
.dating-chat-reply-btn.loading { border-color: #ccc; color: #ccc; animation: dating回复Pulse 1s infinite; }
/* ── Dating context menu ── */
#datingQuotePreview {
  display: none;
  background: #f5f0f2;
  border-left: 3px solid #e8557a;
  padding: 6px 12px;
  font-size: 12px;
  color: #555;
  align-items: center;
  gap: 8px;
}
#datingQuotePreview.show { display: flex; }
#datingQuotePreviewText { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#datingQuoteCancelBtn { cursor: pointer; font-size: 14px; color: #999; flex-shrink: 0; }
#datingMultiDeleteBar {
  display: none;
  background: #fff;
  border-top: 1px solid #eee;
  padding: 8px 16px;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
#datingMultiDeleteBar.show { display: flex; }
#datingMultiDeleteCount { font-size: 12px; color: #666; }
#datingMultiDeleteConfirm {
  background: #ff4444; color: #fff; border: none;
  padding: 6px 16px; border-radius: 20px;
  font-size: 12px; cursor: pointer; font-family: inherit;
}
#datingMultiDeleteCancel {
  background: #f0f0f0; color: #333; border: none;
  padding: 6px 16px; border-radius: 20px;
  font-size: 12px; cursor: pointer; font-family: inherit;
}
#datingEditMsgModal {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  z-index: 300;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
#datingEditMsgModal.show { display: flex; }
#datingEditMsgBox {
  background: #fff;
  border-radius: 12px;
  padding: 16px;
  width: 100%;
  max-width: 320px;
}
.dating-msg-row.dating-selected .dating-msg-bubble {
  outline: 2px solid #e8557a;
  outline-offset: 2px;
}
.dating-msg-row.dating-selectable { cursor: pointer; }
.dating-ctx-menu {
  position: fixed;
  background: #1a1a1a;
  border-radius: 12px;
  padding: 6px 4px;
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
  z-index: 10000;
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
  animation: menuPop 0.15s ease;
  max-width: calc(100vw - 24px);
}
.dating-ctx-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 8px 10px;
  color: #fff;
  cursor: pointer;
  border-radius: 8px;
  transition: background 0.15s;
  min-width: 48px;
}
.dating-ctx-btn:hover { background: rgba(255,255,255,0.15); }
.dating-ctx-btn i { font-size: 14px; }
.dating-ctx-btn span { font-size: 9px; white-space: nowrap; }
.dating-ctx-btn.danger i, .dating-ctx-btn.danger span { color: #ff6b6b; }
@keyframes dating回复Pulse { 0%,100%{opacity:1} 50%{opacity:0.4} }
/* ---- Date App: Discover/Generate Page ---- */
.dating-discover-scroll { flex: 1; overflow-y: auto; padding: 16px; }
.dating-discover-scroll::-webkit-scrollbar { display: none; }
.dating-discover-header {
  font-size: 16px; font-weight: 800; color: #1a1a1a; margin-bottom: 4px;
}
.dating-discover-sub { font-size: 12px; color: #aaa; margin-bottom: 16px; }
.dating-gen-btn {
  width: 100%; padding: 14px; background: #1a1a1a; color: #fff;
  border: none; border-radius: 14px; font-size: 14px; font-weight: 700;
  cursor: pointer; margin-bottom: 16px; letter-spacing: 0.5px;
  transition: transform 0.15s;
}
.dating-gen-btn:active { transform: scale(0.98); }
.dating-gen-btn:disabled { background: #aaa; }
.dating-match-card {
  background: #fff; border-radius: 16px; padding: 16px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.06); margin-bottom: 12px;
  border: 1px solid #f0e8ec; cursor: pointer; transition: transform 0.15s;
}
.dating-match-card:active { transform: scale(0.98); }
.dating-match-card-top { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
.dating-match-card-avatar {
  width: 54px; height: 54px; border-radius: 50%; background: #e8dde2;
  display: flex; align-items: center; justify-content: center;
