}
.dating-match-card-avatar img { width: 100%; height: 100%; object-fit: cover; }
.dating-match-card-info { flex: 1; }
.dating-match-name { font-size: 15px; font-weight: 800; color: #1a1a1a; }
.dating-match-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 5px; }
.dating-match-tag {
