}
.dating-match-skip-btn {
  padding: 10px 16px; background: #f5f0f2; color: #888;
  border: none; border-radius: 10px; font-size: 13px; cursor: pointer;
}
/* ---- Date App: Preferences Page ---- */
.dating-prefs-scroll { flex: 1; overflow-y: auto; padding: 16px 16px 32px; }
.dating-prefs-scroll::-webkit-scrollbar { display: none; }
.dating-prefs-section { margin-bottom: 20px; }
.dating-prefs-section-title {
  font-size: 11px; font-weight: 700; color: #999; letter-spacing: 1px;
  text-transform: uppercase; margin-bottom: 10px; padding-left: 2px;
}
.dating-prefs-card { background: #fff; border-radius: 14px; overflow: hidden; border: 1px solid #f0e8ec; }
.dating-prefs-row {
  display: flex; align-items: center; padding: 13px 16px;
  border-bottom: 0.5px solid #f5f0f2; gap: 12px; cursor: pointer;
}
.dating-prefs-row:last-child { border-bottom: none; }
.dating-prefs-label { flex: 1; font-size: 13px; color: #1a1a1a; }
.dating-prefs-value { font-size: 12px; color: #aaa; max-width: 150px; text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dating-prefs-chevron { color: #ccc; font-size: 11px; flex-shrink: 0; }
.dating-prefs-textarea {
  width: 100%; box-sizing: border-box; background: #fff;
  border: none; border-radius: 14px; padding: 14px 16px;
  font-size: 13px; color: #1a1a1a; resize: none; min-height: 80px;
  outline: none; font-family: inherit; border: 1px solid #f0e8ec;
}
.dating-chip-row { display: flex; flex-wrap: wrap; gap: 6px; }
.dating-chip {
  padding: 6px 12px; border-radius: 20px; font-size: 12px; cursor: pointer;
  border: 1.5px solid #e0d5da; background: #fff; color: #555; transition: all 0.15s;
}
.dating-chip.selected { background: #1a1a1a; color: #fff; border-color: #1a1a1a; }
/* ---- Dating: Profile/Settings Page ---- */
.dating-settings-scroll { flex: 1; overflow-y: auto; padding: 16px 16px 32px; }
.dating-settings-scroll::-webkit-scrollbar { display: none; }
/* Dating user profile card */
.dating-user-profile-card {
  background: #fff; border-radius: 18px; border: 1px solid #f0e8ec;
  overflow: hidden; margin-bottom: 0;
}
.dating-user-profile-header {
  background: linear-gradient(135deg, #1a1a1a 0%, #3a1a2a 100%);
  padding: 20px 18px 16px; display: flex; align-items: center; gap: 14px;
}
.dating-user-profile-avatar {
  width: 54px; height: 54px; border-radius: 50%; background: rgba(255,255,255,0.15);
  display: flex; align-items: center; justify-content: center;
  font-size: 22px; font-weight: 700; color: #fff; flex-shrink: 0;
  overflow: hidden;
}
.dating-user-profile-header-info { flex: 1; min-width: 0; }
.dating-user-profile-name {
  font-size: 17px; font-weight: 700; color: #fff;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.dating-user-profile-meta { font-size: 12px; color: rgba(255,255,255,0.6); margin-top: 3px; }
.dating-user-profile-edit-btn {
  background: rgba(255,255,255,0.15); border: none; color: #fff;
  font-size: 11px; padding: 5px 10px; border-radius: 20px; cursor: pointer;
  flex-shrink: 0;
}
.dating-user-profile-bio-preview {
  padding: 12px 16px 14px; font-size: 12px; color: #888; line-height: 1.6;
  min-height: 36px;
}
/* Inline edit form */
.dating-profile-form { padding: 14px 16px 18px; }
.dating-profile-form-row {
  display: flex; align-items: center; padding: 10px 0;
  border-bottom: 0.5px solid #f5f0f2; gap: 10px;
}
.dating-profile-form-row:last-child { border-bottom: none; }
.dating-profile-form-label { font-size: 13px; color: #555; width: 52px; flex-shrink: 0; }
.dating-profile-form-input {
  flex: 1; border: none; outline: none; font-size: 13px; color: #1a1a1a;
  background: transparent; font-family: inherit; text-align: right;
}
.dating-profile-form-input::placeholder { color: #ccc; }
.dating-profile-form-select {
  flex: 1; border: none; outline: none; font-size: 13px; color: #1a1a1a;
