  font-size: 14px; font-weight: 600; cursor: pointer; font-family: inherit;
}
.dating-profile-save-btn:active { opacity: 0.8; }
.dating-profile-notice {
  margin-top: 10px; padding: 10px 14px; background: #fff8e1;
  border-radius: 10px; font-size: 11px; color: #7a5c00; line-height: 1.7;
  border-left: 3px solid #f0ad4e;
}
/* ---- Dating Modal Overlay ---- */
.dating-modal-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.45); z-index: 1300; display: none;
  align-items: flex-end; justify-content: center;
}
.dating-modal-overlay.active { display: flex; }
.dating-modal-sheet {
  background: #fff; border-radius: 20px 20px 0 0;
