  align-items: center; justify-content: space-between;
}
.dating-option-item:active { background: #faf5f7; }
.dating-option-item.selected { color: #1a1a1a; font-weight: 700; }
.dating-option-item.danger { color: #e74c3c; }
/* Generating spinner overlay */
.dating-gen-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(255,255,255,0.85); z-index: 1400;
  display: none; flex-direction: column; align-items: center; justify-content: center; gap: 14px;
}
.dating-gen-overlay.active { display: flex; }
/* 局部 loading：只覆盖直播现场 panel */
.dating-show-live-overlay {
