/* ── 嘉宾身份弹窗 · 韩系黑白灰 ── */
.cast-id-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 12px;
  font-weight: 800;
  color: #111;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-decoration: none;
  line-height: 1.3;
}
.cast-id-btn .cast-id-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  border-radius: 3px;
  background: rgba(0,0,0,0.08);
  color: rgba(0,0,0,0.4);
  font-size: 7.5px;
  font-weight: 900;
  flex-shrink: 0;
  transition: background 0.12s;
  letter-spacing: 0;
}
.cast-id-btn:active .cast-id-badge { background: rgba(0,0,0,0.18); }

/* overlay */
#castIdOverlay {
  display: none;
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.72);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 9000;
  align-items: flex-end;
  justify-content: center;
}
#castIdOverlay.open {
  display: flex;
  animation: castOverlayFadeIn 0.25s ease both;
}
@keyframes castOverlayFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* modal box */
#castIdBox {
  background: #0d0d0d;
  width: 100%;
  max-width: 480px;
  border-radius: 24px 24px 0 0;
  padding: 0 0 44px;
  max-height: 88vh;
  overflow-y: auto;
  position: relative;
  animation: castBoxSlideUp 0.36s cubic-bezier(0.22,1,0.36,1) both;
  border-top: 1px solid rgba(255,255,255,0.08);
}
#castIdBox::-webkit-scrollbar { display: none; }
@keyframes castBoxSlideUp {
  from { transform: translateY(100%); opacity: 0.3; }
  to   { transform: translateY(0);   opacity: 1; }
}

/* drag handle */
#castIdBox::before {
  content: '';
  display: block;
  width: 32px;
  height: 3px;
  background: rgba(255,255,255,0.12);
  border-radius: 2px;
  margin: 14px auto 22px;
}

/* header */
.cast-id-modal-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 22px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  margin-bottom: 0;
  animation: castFadeUp 0.4s 0.05s both;
}
.cast-id-modal-avatar {
  width: 60px;
  height: 60px;
  border-radius: 14px;
  overflow: hidden;
  background: #1c1c1c;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.2);
  font-size: 20px;
  flex-shrink: 0;
  border: 1px solid rgba(255,255,255,0.06);
}
.cast-id-modal-avatar img { width: 100%; height: 100%; object-fit: cover; }
.cast-id-modal-name {
  font-size: 22px;
  font-weight: 900;
  color: #f2f2f2;
  line-height: 1.2;
  letter-spacing: -0.4px;
}
.cast-id-modal-role {
  font-size: 9.5px;
  color: rgba(255,255,255,0.3);
  margin-top: 5px;
  letter-spacing: 1.2px;
  text-transform: uppercase;
}

/* tags */
.cast-id-modal-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 16px 22px 0;
  animation: castFadeUp 0.4s 0.08s both;
}
.cast-id-modal-tag {
  font-size: 9.5px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
  background: rgba(255,255,255,0.06);
  color: rgba(255,255,255,0.45);
  letter-spacing: 0.4px;
}
.cast-id-modal-tag.crush {
  background: rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.72);
}
.cast-id-modal-tag.mood {
  background: rgba(255,255,255,0.05);
  color: rgba(255,255,255,0.45);
}
.cast-id-modal-tag.gender {
  background: transparent;
  color: rgba(255,255,255,0.35);
  border: 1px solid rgba(255,255,255,0.1);
}

/* bio */
.cast-id-modal-bio {
  font-size: 12px;
  line-height: 1.85;
  color: rgba(255,255,255,0.42);
  background: rgba(255,255,255,0.04);
  border-radius: 10px;
  padding: 13px 15px;
  margin: 14px 22px 0;
  animation: castFadeUp 0.4s 0.11s both;
}

/* stats */
.cast-id-stat-row {
  display: flex;
  flex-direction: column;
  gap: 11px;
  padding: 16px 22px 0;
  animation: castFadeUp 0.4s 0.14s both;
}
.cast-id-stat-item {}
.cast-id-stat-head {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  font-weight: 700;
  color: rgba(255,255,255,0.3);
  margin-bottom: 7px;
  letter-spacing: 1px;
  text-transform: uppercase;
}
.cast-id-stat-bar {
  height: 2px;
  border-radius: 99px;
  background: rgba(255,255,255,0.07);
  overflow: hidden;
}
.cast-id-stat-fill {
  height: 100%;
  border-radius: 99px;
  background: rgba(255,255,255,0.75);
  transition: width 0.9s cubic-bezier(0.22,1,0.36,1);
}

/* inner voice */
.cast-id-inner-voice {
  font-size: 11.5px;
  line-height: 1.9;
  color: rgba(255,255,255,0.35);
  font-style: italic;
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
  padding: 14px 22px;
  margin-top: 16px;
  animation: castFadeUp 0.4s 0.17s both;
}

/* rel section (old version compat) */
.cast-id-rel-section { margin-bottom: 10px; }
.cast-id-rel-title {
  font-size: 8.5px;
  font-weight: 800;
  color: rgba(255,255,255,0.25);
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 8px;
  padding: 18px 22px 0;
}
.cast-id-rel-card {
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.07);
  padding: 11px 14px;
  background: rgba(255,255,255,0.04);
  margin: 0 22px 8px;
}
.cast-id-rel-pair { font-size: 12px; font-weight: 700; color: #e8e8e8; margin-bottom: 3px; }
.cast-id-rel-status { font-size: 10px; color: rgba(255,255,255,0.35); margin-bottom: 3px; }
.cast-id-rel-summary { font-size: 11px; color: rgba(255,255,255,0.4); line-height: 1.55; }

/* close button */
.cast-id-close-btn {
  display: block;
  width: calc(100% - 44px);
  margin: 8px 22px 0;
  padding: 14px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.09);
  background: rgba(255,255,255,0.04);
  font-size: 11px;
  font-weight: 700;
  color: rgba(255,255,255,0.3);
  cursor: pointer;
  font-family: inherit;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  transition: all 0.18s;
}
.cast-id-close-btn:active { background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.5); }

/* animations */
