  box-shadow: 0 10px 22px rgba(0,0,0,0.05);
}
.dating-show-persona-top {
  display: grid;
  grid-template-columns: auto 44px 1fr;
  gap: 10px;
  align-items: center;
}
.dating-show-check {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1.5px solid rgba(0,0,0,0.15);
