}
.dating-show-persona-avatar img { width: 100%; height: 100%; object-fit: cover; }
.dating-show-persona-name {
  font-size: 13px;
  font-weight: 800;
  color: #151515;
}
.dating-show-persona-desc {
  font-size: 10px;
  color: rgba(24,24,24,0.58);
  margin-top: 4px;
  line-height: 1.65;
}
.dating-show-persona-controls {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 10px;
}
.dating-show-sheet-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 18px;
}
.dating-show-overlay-card {
  width: min(86vw, 320px);
  border-radius: 28px;
  padding: 24px 22px;
  background: linear-gradient(180deg, rgba(255,255,255,0.97), rgba(233,233,233,0.95));
  box-shadow: 0 20px 50px rgba(0,0,0,0.12);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.dating-show-overlay-spinner {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 3px solid rgba(0,0,0,0.08);
  border-top-color: #161616;
  animation: datingSpinner 0.8s linear infinite;
}
.dating-show-overlay-title {
  font-size: 15px;
  font-weight: 800;
  color: #161616;
}
.dating-show-overlay-sub {
  text-align: center;
  font-size: 11px;
  line-height: 1.8;
  color: rgba(24,24,24,0.6);
}
@media (max-width: 420px) {
  .dating-show-participants,
  .dating-show-rel-grid,
  .dating-show-actions,
  .dating-show-live-actions,
  .dating-show-persona-controls,
  .dating-show-sheet-actions {
    grid-template-columns: 1fr;
  }
  .dating-show-title { font-size: 22px; }
}
/* Music app icon (same size as location & blackbox icon) */
.ig-music-icon-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  cursor: pointer;
}
.ig-music-icon-box {
  width: 72px;
  height: 72px;
  border-radius: 16px;
  background: rgba(240,240,240,0.6);
  border: 1px solid rgba(210,210,210,0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(24px * var(--fs, 1));
  color: #555;
