/* ===== HOME PAGE 2 — APPS + MEMO LAYOUT ===== */
/* ===== MEMO WIDGET ===== */
.memo-widget {
  width: 100%;
  flex-shrink: 0;
  height: calc(78px + 16px + 78px + 16px + 8px);
  border-radius: 20px;
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(0,0,0,0.10);
  box-shadow: 0 2px 16px rgba(0,0,0,0.08);
}
/* bg layer — holds user photo (blurred) or plain white */
.memo-widget-bg {
  position: absolute;
  inset: -12px;
  background-color: #ffffff;
  background-size: cover;
  background-position: center;
  filter: blur(18px) brightness(1.1) saturate(0.9);
  z-index: 0;
}
/* frosted white glass over the bg */
.memo-widget-glass {
  position: absolute;
  inset: 0;
  background: rgba(255,255,255,0.78);
  z-index: 1;
}
.memo-widget-inner {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 10px 10px 7px;
  box-sizing: border-box;
}
.memo-widget-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 7px;
  flex-shrink: 0;
}
.memo-widget-title {
  font-size: calc(9px * var(--fs, 1));
  font-weight: 800;
  color: rgba(0,0,0,0.7);
  text-transform: uppercase;
  letter-spacing: 2px;
}
.memo-widget-bg-btn {
  background: rgba(0,0,0,0.06);
  border: 1px solid rgba(0,0,0,0.12);
  color: rgba(0,0,0,0.45);
  border-radius: 7px;
  width: 20px; height: 20px;
  display: flex; align-items: center; justify-content: center;
  font-size: calc(8px * var(--fs, 1));
  cursor: pointer;
  transition: all 0.2s;
  flex-shrink: 0;
}
.memo-widget-bg-btn:active { opacity: 0.6; transform: scale(0.9); }
/* scrollable list */
.memo-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 0;
}
.memo-item {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(0,0,0,0.05);
  border: 1px solid rgba(0,0,0,0.08);
  border-radius: 8px;
  padding: 5px 7px;
  cursor: pointer;
  transition: background 0.15s;
  flex-shrink: 0;
}
.memo-item:active { background: rgba(0,0,0,0.10); }
.memo-item-check {
  width: 12px; height: 12px;
  border: 1.5px solid rgba(0,0,0,0.3);
  border-radius: 3px;
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  transition: all 0.2s;
  cursor: pointer;
}
.memo-item-check.done {
  background: #1a1a1a;
  border-color: #1a1a1a;
}
.memo-item-check.done::after {
  content: '';
  width: 7px; height: 4px;
  border-left: 1.5px solid #fff;
  border-bottom: 1.5px solid #fff;
  transform: rotate(-45deg) translateY(-1px);
  display: block;
}
.memo-item-text {
  flex: 1;
  font-size: calc(9px * var(--fs, 1));
  font-weight: 500;
  color: rgba(0,0,0,0.82);
  line-height: 1.3;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  letter-spacing: 0.1px;
}
.memo-item-text.done {
  text-decoration: line-through;
  color: rgba(0,0,0,0.3);
}
.memo-add-btn {
  flex-shrink: 0;
  margin-top: 5px;
  width: 100%;
  height: 20px;
  border-radius: 7px;
  border: 1px dashed rgba(0,0,0,0.18);
  background: rgba(0,0,0,0.03);
  color: rgba(0,0,0,0.35);
  font-size: calc(10px * var(--fs, 1));
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: all 0.2s;
}
.memo-add-btn:active { background: rgba(0,0,0,0.08); }
/* Memo add/edit modal */
.memo-modal-overlay {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.55);
  z-index: 99999;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.memo-modal-overlay.open { display: flex; }
.memo-modal-box {
  background: #1e1e1e;
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 16px;
  padding: 18px 16px 14px;
  width: 100%;
  max-width: 280px;
}
.memo-modal-title {
  font-size: calc(11px * var(--fs, 1));
  font-weight: 800;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 12px;
}
.memo-modal-input {
  width: 100%;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 10px;
  color: #fff;
  font-family: 'Montserrat', sans-serif;
  font-size: calc(12px * var(--fs, 1));
  padding: 9px 11px;
  outline: none;
  box-sizing: border-box;
  margin-bottom: 12px;
}
.memo-modal-input::placeholder { color: rgba(255,255,255,0.35); }
.memo-modal-input:focus { border-color: rgba(255,255,255,0.4); }
.memo-modal-btns {
  display: flex;
  gap: 8px;
}
.memo-modal-cancel {
  flex: 1; padding: 8px; border-radius: 9px;
  border: 1px solid rgba(255,255,255,0.18);
  background: transparent; color: rgba(255,255,255,0.6);
  font-family: 'Montserrat', sans-serif;
  font-size: calc(10px * var(--fs, 1)); font-weight: 700;
  text-transform: uppercase; letter-spacing: 1px; cursor: pointer;
}
.memo-modal-save {
  flex: 1; padding: 8px; border-radius: 9px;
  border: none;
  background: rgba(255,255,255,0.92); color: #1a1a1a;
  font-family: 'Montserrat', sans-serif;
  font-size: calc(10px * var(--fs, 1)); font-weight: 800;
  text-transform: uppercase; letter-spacing: 1px; cursor: pointer;
}
.memo-modal-save:active { background: rgba(255,255,255,0.75); }
/* ===================== MUSIC APP - Korean Monochrome Style ===================== */
#musicPage {
  position: fixed; inset: 0; z-index: 9999;
  background: #f5f5f5;
  display: none; flex-direction: column;
  font-family: 'Montserrat', 'Noto Sans SC', sans-serif;
  color: #1a1a1a;
  overflow: hidden;
}
#musicPage.active { display: flex; }
/* Mini Player Bar (shown when leaving music app) */
#musicMiniBar {
  position: fixed;
  bottom: 60px;
  left: 0; right: 0;
  height: 52px;
  background: rgba(245,245,245,0.96);
  backdrop-filter: blur(12px);
  border-top: 1px solid #e0e0e0;
  display: none;
  align-items: center;
  padding: 0 14px;
  gap: 10px;
  z-index: 8888;
  cursor: grab;
  border-radius: 0;
  transition: border-radius 0.2s, box-shadow 0.2s;
}
#musicMiniBar.dragging {
  cursor: grabbing;
  border-radius: 16px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.18);
  border: none;
  left: auto !important;
  right: auto !important;
}
#musicMiniBar.floating {
  border-radius: 16px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.12);
  border: 1px solid #e0e0e0;
  left: auto !important;
  right: auto !important;
  width: auto;
  min-width: 260px;
  max-width: 92vw;
}
#musicMiniBar.visible { display: flex; }
.music-mini-restore-pill {
  position: fixed;
  right: 14px;
  bottom: 66px;
  z-index: 8889;
  display: none;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 999px;
  border: 1px solid #d8d8d8;
  background: rgba(255,255,255,0.96);
  backdrop-filter: blur(12px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.08);
  color: #1a1a1a;
  font-size: calc(11px * var(--fs, 1));
  font-weight: 700;
  cursor: pointer;
}
.music-mini-restore-pill.visible { display: inline-flex; }
.mini-bar-cover {
  width: 36px; height: 36px; border-radius: 8px;
  background: #ddd; flex-shrink: 0; overflow: hidden;
}
.mini-bar-cover img { width: 100%; height: 100%; object-fit: cover; }
.mini-bar-info { flex: 1; min-width: 0; }
.mini-bar-title { font-size: calc(11px * var(--fs, 1)); font-weight: 700; color: #1a1a1a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mini-bar-artist { font-size: calc(9px * var(--fs, 1)); color: #888; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mini-bar-progress {
  width: 100%; height: 2px; background: #e0e0e0; border-radius: 2px; margin-top: 3px;
}
.mini-bar-progress-fill { height: 100%; background: #555; border-radius: 2px; width: 0%; transition: width 0.5s linear; }
.mini-bar-controls { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.mini-bar-btn { background: none; border: none; color: #333; font-size: calc(14px * var(--fs, 1)); cursor: pointer; padding: 4px; }
.mini-bar-btn:active { opacity: 0.5; }
.mini-bar-stop { font-size: calc(11px * var(--fs, 1)); color: #999; background: none; border: none; cursor: pointer; font-family: inherit; }
/* Music App Back Bar */
.music-back-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 16px 10px; flex-shrink: 0;
  border-bottom: 1px solid #e0e0e0;
  background: #fff;
}
.music-back-btn {
  background: none; border: none; color: #1a1a1a; font-size: calc(13px * var(--fs, 1));
  cursor: pointer; font-family: inherit; font-weight: 600;
  display: flex; align-items: center; gap: 6px;
  transition: opacity 0.2s;
}
.music-back-btn:hover { opacity: 0.6; }
.music-page-title {
  font-size: calc(13px * var(--fs, 1)); font-weight: 800; letter-spacing: 2px;
  color: #1a1a1a; text-transform: uppercase;
}
.music-header-right { display: flex; gap: 8px; align-items: center; }
/* Music Tabs */
.music-tabs {
  display: flex; border-bottom: 1px solid #e0e0e0;
  flex-shrink: 0; background: #fff;
}
.music-tab {
  flex: 1; padding: 10px 0; text-align: center;
  font-size: calc(10px * var(--fs, 1)); font-weight: 700; letter-spacing: 1px;
  text-transform: uppercase; color: #aaa; cursor: pointer;
  border-bottom: 2px solid transparent; transition: all 0.2s;
}
.music-tab.active { color: #1a1a1a; border-bottom-color: #1a1a1a; }
/* Music Search */
.music-search-bar {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 14px; background: #fff;
  border-bottom: 1px solid #f0f0f0; flex-shrink: 0;
}
.music-search-input {
  flex: 1; border: 1px solid #e0e0e0; border-radius: 20px;
  padding: 8px 14px; font-size: calc(12px * var(--fs, 1)); font-family: inherit;
  background: #f8f8f8; color: #1a1a1a; outline: none;
}
.music-search-input:focus { border-color: #888; background: #fff; }
.music-search-btn {
  background: #1a1a1a; color: #fff; border: none; border-radius: 20px;
  padding: 8px 14px; font-size: calc(11px * var(--fs, 1)); font-weight: 700;
  cursor: pointer; font-family: inherit; letter-spacing: 0.5px;
  transition: opacity 0.2s;
}
.music-search-btn:active { opacity: 0.7; }
/* Music Content Area */
.music-content { flex: 1; overflow-y: auto; background: #f5f5f5; }
.music-content::-webkit-scrollbar { display: none; }
/* Track List */
.music-track-item {
  display: flex; align-items: center; gap: 12px;
  padding: 10px 14px; background: #fff; border-bottom: 1px solid #f0f0f0;
  cursor: pointer; transition: background 0.15s;
}
.music-track-item:active { background: #f5f5f5; }
.music-track-item.playing { background: #f0f0f0; }
.music-track-cover {
  width: 44px; height: 44px; border-radius: 8px; flex-shrink: 0;
  background: #ddd; overflow: hidden; position: relative;
}
.music-track-cover img { width: 100%; height: 100%; object-fit: cover; }
.music-track-cover-placeholder {
  width: 100%; height: 100%; display: flex; align-items: center;
  justify-content: center; color: #aaa; font-size: calc(18px * var(--fs, 1));
}
.music-track-info { flex: 1; min-width: 0; }
.music-track-name { font-size: calc(13px * var(--fs, 1)); font-weight: 700; color: #1a1a1a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.music-track-artist { font-size: calc(11px * var(--fs, 1)); color: #888; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.music-track-actions { display: flex; gap: 8px; flex-shrink: 0; }
.music-track-btn { background: none; border: none; color: #aaa; font-size: calc(14px * var(--fs, 1)); cursor: pointer; padding: 4px; }
.music-track-btn:active { color: #333; }
.music-track-btn.saved { color: #555; }
/* Music Player */
.music-player-overlay {
  position: absolute; inset: 0; z-index: 10;
  background: #f5f5f5;
  display: none; flex-direction: column; align-items: center;
  overflow: hidden;
}
.music-player-overlay.open { display: flex; }
.music-player-topbar {
  width: 100%; display: flex; align-items: center; justify-content: space-between;
  padding: 14px 16px 8px; flex-shrink: 0;
}
.music-player-close {
  background: none; border: none; color: #555; font-size: calc(16px * var(--fs, 1)); cursor: pointer;
}
.music-player-title-small { font-size: calc(10px * var(--fs, 1)); font-weight: 700; letter-spacing: 2px; color: #888; text-transform: uppercase; }
.music-player-more { background: none; border: none; color: #555; font-size: calc(16px * var(--fs, 1)); cursor: pointer; }
.music-player-artwork {
  width: 200px; height: 200px; border-radius: 20px; margin: 12px auto 16px;
  background: #ddd; overflow: hidden; flex-shrink: 0;
  box-shadow: 0 8px 24px rgba(0,0,0,0.15);
}
.music-player-artwork img { width: 100%; height: 100%; object-fit: cover; }
.music-player-artwork-placeholder {
  width: 100%; height: 100%; display: flex; align-items: center;
  justify-content: center; font-size: calc(56px * var(--fs, 1)); color: #bbb;
}
.music-player-meta { width: 100%; padding: 0 24px; text-align: center; flex-shrink: 0; }
.music-player-song-name { font-size: calc(17px * var(--fs, 1)); font-weight: 800; color: #1a1a1a; letter-spacing: 0.5px; margin-bottom: 4px; }
.music-player-artist-name { font-size: calc(12px * var(--fs, 1)); color: #888; font-weight: 500; }
.music-player-actions { display: flex; gap: 14px; justify-content: center; margin: 8px 0; flex-shrink: 0; }
.music-player-action-btn {
  background: none; border: none; color: #888; font-size: calc(12px * var(--fs, 1)); cursor: pointer;
