}
.music-player-action-btn i { font-size: calc(16px * var(--fs, 1)); }
.music-player-action-btn span { font-size: calc(8px * var(--fs, 1)); letter-spacing: 0.5px; }
.music-player-action-btn.active { color: #333; }
/* Progress bar */
.music-progress-wrap { width: 100%; padding: 0 20px; flex-shrink: 0; }
.music-progress-bar-bg {
