}
.music-progress-bar-fill { height: 100%; background: #555; border-radius: 3px; width: 0%; transition: width 0.5s linear; }
.music-progress-times { display: flex; justify-content: space-between; margin-top: 4px; font-size: calc(9px * var(--fs, 1)); color: #aaa; }
/* Controls */
.music-controls { display: flex; align-items: center; justify-content: space-around; width: 100%; padding: 8px 20px; flex-shrink: 0; }
.music-ctrl-btn { background: none; border: none; color: #555; cursor: pointer; padding: 8px; font-size: calc(20px * var(--fs, 1)); transition: opacity 0.2s; }
.music-ctrl-btn:active { opacity: 0.5; }
.music-ctrl-play { font-size: calc(44px * var(--fs, 1)); color: #1a1a1a; }
/* Lyrics panel */
.music-lyrics-panel {
  flex: 1; overflow-y: auto; padding: 8px 24px 16px;
  width: 100%;
}
.music-lyrics-panel::-webkit-scrollbar { display: none; }
.music-lyric-line {
