.bb-secret-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 14px;
  background: #fafafa;
  border-bottom: 1px solid #f0f0f0;
}
.bb-secret-age {
  font-size: calc(10px * var(--fs, 1)); font-weight: 700; color: #1a1a1a;
  letter-spacing: 0.8px; text-transform: uppercase;
}
.bb-secret-delete {
  background: none; border: none; color: #ccc; font-size: calc(11px * var(--fs, 1));
  cursor: pointer; padding: 4px 8px; border-radius: 6px;
  transition: 0.2s;
}
.bb-secret-delete:hover { color: #c0392b; background: #fee2e2; }
.bb-secret-body {
  padding: 14px 16px; font-size: calc(12px * var(--fs, 1)); line-height: 1.8;
  color: #444;
}
.bb-secret-body .bb-secret-title {
