}
.bb-secret-meta-type {
  font-size: calc(9px * var(--fs, 1)); font-weight: 700; color: #666;
  background: #f0f0f0; padding: 2px 8px;
  border-radius: 4px; letter-spacing: 0.5px;
  border: 1px solid #e0e0e0;
}
/* Secret item content wrapper */
.bb-secret-item-content {
  flex: 1; min-width: 0;
}
.bb-loading-indicator {
  text-align: center; padding: 24px; color: #aaa; font-size: calc(11px * var(--fs, 1));
  letter-spacing: 0.5px;
}
.bb-loading-indicator i { margin-right: 6px; }
.ig-location-icon-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  cursor: pointer;
}
.ig-location-icon-box {
  width: 72px;
  height: 72px;
  border-radius: 16px;
  background: rgba(240,240,240,0.6);
  border: 1px solid rgba(210,210,210,0.5);
  display: flex;
  align-items: center;
  justify-content: center;
