}
.ig-location-icon-box:active { transform: scale(0.92); }
.ig-location-icon-box img.custom-icon { width: 100%; height: 100%; object-fit: cover; border-radius: 16px; }
.ig-location-icon-label {
  font-size: calc(9px * var(--fs, 1));
