  gap: 6px;
  padding: 8px 16px;
  border-bottom: 1px solid #f0f0f0;
  flex-shrink: 0;
  align-items: center;
}
.loc-region-label {
  font-size: calc(9px * var(--fs, 1));
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #888;
  flex-shrink: 0;
}
.loc-region-select {
  flex: 1;
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  padding: 4px 8px;
  font-size: calc(10px * var(--fs, 1));
  font-family: 'Montserrat', sans-serif;
  background: #fafafa;
  color: #1a1a1a;
  outline: none;
}
.home-status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 20px 2px;
  padding-top: 10px;
  font-size: calc(11px * var(--fs, 1));
  font-weight: 600;
  color: #1a1a1a;
  flex-shrink: 0;
  font-family: 'DM Mono', 'Montserrat', monospace;
  text-shadow: 0 0 6px rgba(255,255,255,0.7);
}
.home-calendar-widget {
  margin: 6px 16px 10px;
  background: rgba(240,240,240,0.65);
  border: 1px solid rgba(200,200,200,0.5);
  border-radius: 16px;
  padding: 10px 12px;
  backdrop-filter: blur(8px);
  flex-shrink: 0;
}
.home-calendar-date {
  font-size: calc(15px * var(--fs, 1));
  font-weight: 700;
  color: #1a1a1a;
  letter-spacing: -0.3px;
  line-height: 1.2;
  margin-bottom: 6px;
}
.home-calendar-sub {
  font-size: calc(10px * var(--fs, 1));
  color: #888;
  font-weight: 500;
  margin-top: 0px;
