  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 6px;
}
.home-calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
  text-align: center;
  font-size: calc(9px * var(--fs, 1));
}
.home-calendar-grid .cal-header {
  font-weight: 700;
  color: #999;
  font-size: calc(8px * var(--fs, 1));
  padding: 2px 0;
  text-transform: uppercase;
}
.home-calendar-grid .cal-day {
  padding: 2px 0;
  color: #666;
  font-size: calc(9px * var(--fs, 1));
  border-radius: 50%;
