  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto;
}
.home-calendar-grid .cal-day.today {
  background: #1a1a1a;
  color: #fff;
  font-weight: 700;
}
.home-calendar-grid .cal-day.other-month {
  color: #ccc;
}
/* calendar dots removed - replaced by grid */
.home-main-area {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 0 16px;
  flex-shrink: 0;
}
.home-photo-widget {
  width: 152px;
  height: 152px;
  background: rgba(240,240,240,0.65);
  border: 1px solid rgba(200,200,200,0.5);
  border-radius: 18px;
  overflow: hidden;
  cursor: pointer;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(8px);
  flex-shrink: 0;
  box-sizing: border-box;
}
.home-photo-widget img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  position: absolute;
  top: 0;
  left: 0;
  border-radius: inherit;
  pointer-events: none;
}
.home-photo-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  color: #bbb;
}
.home-photo-placeholder i { font-size: calc(28px * var(--fs, 1)); }
.home-photo-placeholder span { font-size: calc(9px * var(--fs, 1)); text-transform: uppercase; letter-spacing: 1px; font-weight: 600; }
.home-apps-grid {
  display: grid;
  grid-template-columns: repeat(2, 72px);
  grid-template-rows: repeat(2, auto);
  gap: 8px;
}
.home-app-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  cursor: pointer;
  transition: transform 0.15s;
  /* Prevent text/image selection and iOS "Copy" callout on long-press */
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  user-select: none;
}
.home-app-icon:active { transform: scale(0.9); }
.home-app-icon-box {
  width: 72px;
  height: 72px;
  background: rgba(240,240,240,0.6);
  border: 1px solid rgba(210,210,210,0.5);
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(22px * var(--fs, 1));
  color: #555;
  backdrop-filter: blur(4px);
  transition: background 0.2s, width 0.22s, height 0.22s, border-radius 0.22s;
}
.home-app-icon-box:hover { background: rgba(230,230,230,0.8); }
.home-app-icon-label {
  font-size: calc(9px * var(--fs, 1));
  color: #555;
  font-weight: 600;
  text-align: center;
  letter-spacing: 0.3px;
  line-height: 1.2;
}
.home-dock-bar {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  padding: 6px 16px 10px;
  box-sizing: border-box;
  z-index: 86;
}
.home-dock {
  width: fit-content;
  min-width: 0;
  max-width: 90%;
  height: 86px;
  background: rgba(245,245,245,0.72);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 0.5px solid rgba(200,200,200,0.45);
  border-radius: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 16px;
  flex-shrink: 0;
  box-sizing: border-box;
}
/* Lock dock size — placeholders keep space when apps are dragged out */
#homeSharedDock {
  /* width will be locked by JS after first render */
}
.home-dock-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  pointer-events: none;
  visibility: hidden; /* invisible but takes up space */
}
.home-dock-placeholder-box {
  width: 54px;
  height: 54px;
  flex-shrink: 0;
}
.home-dock-placeholder-label {
  font-size: calc(8px * var(--fs, 1));
  height: 1em;
  flex-shrink: 0;
}
.home-dock-app {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  transition: transform 0.15s;
}
.home-dock-app:active { transform: scale(0.9); }
.home-dock-app-box {
  width: 54px;
  height: 54px;
  background: rgba(240,240,240,0.6);
  border: 1px solid rgba(210,210,210,0.5);
  border-radius: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(20px * var(--fs, 1));
  color: #555;
  backdrop-filter: blur(4px);
  overflow: hidden;
  transition: width 0.22s, height 0.22s, border-radius 0.22s, transform 0.2s;
}
.home-dock-app-label {
  font-size: calc(8px * var(--fs, 1));
  color: #666;
  font-weight: 600;
  letter-spacing: 0.3px;
}
/* Extra apps row below photo widget - aligned with photo widget left edge */
.home-extra-apps-row {
  display: flex;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 8px;
  /* Align with photo widget left edge: (container - (152+12+144)) / 2 + 16px padding */
  padding: 8px 16px 0 calc((100% - 308px) / 2);
  flex-shrink: 0;
  box-sizing: border-box;
}
.home-extra-apps-row .home-app-icon {
  width: 72px;
}
/* ===================== 剧本体验 Script Experience Styles ===================== */
#scriptPage { padding: 0; background: #fafafa; }
#scriptPage.active { display: flex; flex-direction: column; }
.script-hall { flex: 1; overflow-y: auto; padding: 16px; }
.script-hall::-webkit-scrollbar { display: none; }
.script-hall-title {
  font-size: calc(18px * var(--fs, 1)); font-weight: 700; color: #1a1a1a;
  letter-spacing: -0.3px; margin-bottom: 4px;
}
.script-hall-sub {
  font-size: calc(10px * var(--fs, 1)); color: #999; text-transform: uppercase;
  letter-spacing: 2px; font-weight: 600; margin-bottom: 16px;
  font-family: 'DM Mono', monospace;
}
.script-route-card {
  background: #fff; border: 1px solid #e0e0e0; border-radius: 12px;
  padding: 16px; margin-bottom: 12px; cursor: pointer;
  transition: all 0.15s;
}
.script-route-card:hover { border-color: #1a1a1a; }
.script-route-card:active { transform: scale(0.98); }
.script-route-title {
  font-size: calc(14px * var(--fs, 1)); font-weight: 700; color: #1a1a1a;
  margin-bottom: 4px; display: flex; align-items: center; gap: 8px;
}
.script-route-title i { font-size: calc(12px * var(--fs, 1)); color: #888; }
.script-route-desc {
  font-size: calc(11px * var(--fs, 1)); color: #888; line-height: 1.5;
}
/* Tag selection */
.script-tag-section { margin-bottom: 16px; }
.script-tag-group-title {
  font-size: calc(10px * var(--fs, 1)); font-weight: 700; color: #888;
  text-transform: uppercase; letter-spacing: 1.5px;
  margin-bottom: 8px; font-family: 'DM Mono', monospace;
  display: flex; align-items: center; justify-content: space-between;
  cursor: pointer; user-select: none;
}
.script-tag-group-title i { font-size: calc(8px * var(--fs, 1)); transition: transform 0.2s; }
.script-tag-options {
  display: flex; flex-wrap: wrap; gap: 6px;
}
.script-tag-opt {
  padding: 5px 12px; border: 1px solid #ddd; border-radius: 20px;
  font-size: calc(11px * var(--fs, 1)); color: #666; cursor: pointer; transition: all 0.15s;
  white-space: nowrap; user-select: none;
}
.script-tag-opt.selected { background: #1a1a1a; color: #fff; border-color: #1a1a1a; }
.script-tag-opt:hover:not(.selected) { border-color: #999; color: #333; }
.script-custom-input {
  width: 100%; border: 1px solid #ddd; border-radius: 10px;
  padding: 10px 12px; font-size: calc(12px * var(--fs, 1)); font-family: inherit;
  outline: none; resize: none; min-height: 80px; box-sizing: border-box;
  margin-bottom: 10px;
}
.script-custom-input:focus { border-color: #1a1a1a; }
.script-generate-btn {
  width: 100%; background: #1a1a1a; color: #fff; border: none;
  padding: 13px; border-radius: 10px; font-size: calc(12px * var(--fs, 1)); font-weight: 700;
  cursor: pointer; text-transform: uppercase; letter-spacing: 1px;
  font-family: 'DM Mono', monospace; transition: background 0.2s;
}
.script-generate-btn:active { background: #333; }
.script-generate-btn:disabled { background: #ccc; cursor: not-allowed; }
/* Script card */
.script-card-view { flex: 1; overflow-y: auto; padding: 16px; }
.script-card-view::-webkit-scrollbar { display: none; }
.script-card-block {
  background: #fff; border: 1px solid #e0e0e0; border-radius: 12px;
  padding: 16px; margin-bottom: 12px;
}
.script-card-label {
  font-size: calc(9px * var(--fs, 1)); font-weight: 700; color: #999;
  text-transform: uppercase; letter-spacing: 1.5px;
  margin-bottom: 6px; font-family: 'DM Mono', monospace;
}
.script-card-value {
  font-size: calc(13px * var(--fs, 1)); color: #1a1a1a; line-height: 1.7;
}
.script-card-value.title-val {
  font-size: calc(18px * var(--fs, 1)); font-weight: 700; letter-spacing: -0.3px;
}
.script-card-tags {
  display: flex; flex-wrap: wrap; gap: 5px; margin-top: 4px;
}
.script-card-tag {
  padding: 3px 10px; background: #f2f2f2; border-radius: 12px;
  font-size: calc(10px * var(--fs, 1)); color: #555;
}
/* Character table in script card */
.script-char-item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 0; border-bottom: 1px solid #f0f0f0;
}
.script-char-item:last-child { border-bottom: none; }
.script-char-avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: #1a1a1a; display: flex; align-items: center;
  justify-content: center; color: #fff; font-size: calc(14px * var(--fs, 1));
  font-weight: 700; flex-shrink: 0;
}
.script-char-info { flex: 1; }
.script-char-name { font-size: calc(13px * var(--fs, 1)); font-weight: 700; color: #1a1a1a; }
.script-char-role { font-size: calc(10px * var(--fs, 1)); color: #888; margin-top: 1px; }
.script-char-traits { font-size: calc(10px * var(--fs, 1)); color: #aaa; margin-top: 1px; }
/* Story direction choices */
.script-direction-item {
  background: #f8f8f8; border: 1px solid #e8e8e8; border-radius: 10px;
  padding: 12px; margin-bottom: 8px; cursor: pointer; transition: all 0.15s;
}
.script-direction-item:hover { border-color: #1a1a1a; }
.script-direction-item.selected { border-color: #1a1a1a; background: #f0f0f0; }
.script-direction-num {
  font-size: calc(9px * var(--fs, 1)); font-weight: 700; color: #999;
  text-transform: uppercase; letter-spacing: 1px;
  margin-bottom: 4px; font-family: 'DM Mono', monospace;
}
.script-direction-text { font-size: calc(12px * var(--fs, 1)); color: #333; line-height: 1.5; }
/* Role assignment */
.script-role-item {
  display: flex; align-items: center; gap: 10px;
  padding: 12px; background: #fff; border: 1px solid #e0e0e0;
  border-radius: 10px; margin-bottom: 8px;
}
.script-role-avatar {
  width: 40px; height: 40px; border-radius: 50%;
  background: #1a1a1a; display: flex; align-items: center;
  justify-content: center; color: #fff; font-size: calc(16px * var(--fs, 1));
  font-weight: 700; flex-shrink: 0;
}
.script-role-info { flex: 1; min-width: 0; }
.script-role-name { font-size: calc(13px * var(--fs, 1)); font-weight: 700; }
.script-role-desc { font-size: calc(10px * var(--fs, 1)); color: #888; margin-top: 2px; }
.script-role-assign {
  font-size: calc(10px * var(--fs, 1)); padding: 5px 12px; border: 1px solid #ddd;
  border-radius: 20px; cursor: pointer; background: #fff;
  font-family: inherit; font-weight: 600; transition: all 0.15s;
}
.script-role-assign.me { background: #1a1a1a; color: #fff; border-color: #1a1a1a; }
.script-role-assign:hover:not(.me) { border-color: #1a1a1a; }
/* Story progression */
.script-story-view { display: flex; flex-direction: column; flex: 1; overflow: hidden; }
.script-narrator-bar {
  background: #f5f5f5; padding: 10px 16px; font-size: calc(12px * var(--fs, 1));
  color: #666; font-style: italic; line-height: 1.6;
  border-bottom: 1px solid #eee; flex-shrink: 0;
  max-height: 80px; overflow-y: auto;
}
.script-narrator-bar::-webkit-scrollbar { display: none; }
.script-chat-area {
  flex: 1; overflow-y: auto; padding: 12px 16px;
}
.script-chat-area::-webkit-scrollbar { display: none; }
.script-msg-row { display: flex; width: 100%; margin-bottom: 10px; align-items: flex-end; gap: 8px; }
.script-msg-row.user { justify-content: flex-end; }
.script-msg-row.npc { justify-content: flex-start; }
.script-msg-meta { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.script-msg-avatar {
  width: 30px; height: 30px; border-radius: 50%;
  background: #1a1a1a; display: flex; align-items: center;
  justify-content: center; color: #fff; font-size: calc(12px * var(--fs, 1));
  font-weight: 700; flex-shrink: 0;
}
.script-msg-name {
  font-size: calc(8px * var(--fs, 1)); color: #999; text-transform: uppercase;
  letter-spacing: 0.5px; white-space: nowrap;
}
.script-msg-bubble {
  max-width: 70%; padding: 10px 14px; font-size: calc(13px * var(--fs, 1)); line-height: 1.6;
}
.script-msg-row.npc .script-msg-bubble {
  background: #f2f2f2; border-radius: 16px 16px 16px 2px; color: #1a1a1a;
}
.script-msg-row.user .script-msg-bubble {
  background: #1a1a1a; color: #fff; border-radius: 16px 16px 2px 16px;
}
.script-msg-row.narrator .script-msg-bubble {
  background: transparent; color: #999; font-style: italic;
  font-size: calc(11px * var(--fs, 1)); max-width: 90%; text-align: center;
  padding: 8px 0;
}
.script-msg-row.narrator { justify-content: center; }
/* Action bar at bottom */
.script-action-bar {
  border-top: 1px solid #eee; background: #fff;
  padding: 10px 16px; flex-shrink: 0;
  max-height: 45vh; display: flex; flex-direction: column;
