}
.script-tool-btn:hover { border-color: #1a1a1a; color: #1a1a1a; }
.script-tool-btn.wrap-btn { color: #c0392b; border-color: #e0b4b4; }
.script-tool-btn.wrap-btn:hover { border-color: #c0392b; }
/* Key decision point */
.script-decision-overlay {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.6); z-index: 100;
