  animation: slideUp 0.22s ease;
}
.script-decision-title {
  font-size: calc(12px * var(--fs, 1)); font-weight: 700; text-transform: uppercase;
  letter-spacing: 1.5px; margin-bottom: 12px; color: #1a1a1a;
