}
.script-archive-card:hover { border-color: #1a1a1a; }
.script-archive-title {
  font-size: calc(14px * var(--fs, 1)); font-weight: 700; color: #1a1a1a; margin-bottom: 4px;
}
.script-archive-meta {
  font-size: calc(10px * var(--fs, 1)); color: #999; font-family: 'DM Mono', monospace;
  margin-bottom: 6px;
}
.script-archive-tags { display: flex; flex-wrap: wrap; gap: 4px; }
.script-archive-tag {
  padding: 2px 8px; background: #f2f2f2; border-radius: 10px;
  font-size: calc(9px * var(--fs, 1)); color: #666;
}
.script-archive-actions {
  display: flex; gap: 6px; margin-top: 8px;
}
.script-archive-btn {
  padding: 5px 12px; border: 1px solid #ddd; border-radius: 16px;
  font-size: calc(10px * var(--fs, 1)); font-weight: 600; cursor: pointer;
