}
.script-loading-dots span:nth-child(2) { animation-delay: 0.2s; }
.script-loading-dots span:nth-child(3) { animation-delay: 0.4s; }
/* Chapter progress bar */
.script-chapter-bar {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 16px; background: #fff; border-bottom: 1px solid #eee;
  flex-shrink: 0;
}
.script-chapter-label {
  font-size: calc(10px * var(--fs, 1)); font-weight: 700; color: #1a1a1a;
  text-transform: uppercase; letter-spacing: 0.5px;
