}
.script-chapter-progress-fill {
  height: 100%; background: #1a1a1a; border-radius: 2px;
  transition: width 0.3s;
}
.script-chapter-count {
  font-size: calc(9px * var(--fs, 1)); color: #999; font-family: 'DM Mono', monospace;
