}
/* Back button for script sub-views */
.script-back-row {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 16px; border-bottom: 1px solid #eee;
  background: #fff; flex-shrink: 0;
}
.script-back-btn {
  display: flex; align-items: center; gap: 4px;
  background: none; border: 1px solid #ddd; border-radius: 20px;
  padding: 5px 12px 5px 8px; font-size: calc(10px * var(--fs, 1)); font-weight: 600;
  color: #555; cursor: pointer; font-family: inherit;
  transition: all 0.2s; text-transform: uppercase; letter-spacing: 0.5px;
}
.script-back-btn:hover { background: #1a1a1a; color: #fff; border-color: #1a1a1a; }
.script-back-btn i { font-size: calc(10px * var(--fs, 1)); }
.script-view-title {
  font-size: calc(13px * var(--fs, 1)); font-weight: 700; color: #1a1a1a;
