.seolei-gallery-header:hover { background: #d5d5d5; }
.seolei-file-list {
  background: #ececec;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid #d0d0d0;
  max-height: 110px;
  overflow-y: auto;
  transition: max-height 0.3s ease;
}
.seolei-file-list::-webkit-scrollbar { display: none; }
.seolei-file-list.collapsed { max-height: 0; border: none; }
.seolei-file-item {
  padding: 7px 10px;
  font-size: 10px;
  color: #333;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  border-bottom: 1px solid #ddd;
  transition: background 0.15s;
}
.seolei-file-item:last-child { border-bottom: none; }
.seolei-file-item:hover { background: #e0e0e0; }
.seolei-file-item.active { background: #1a1a1a; color: #fff; }
.seolei-footer-btns {
  display: flex;
  justify-content: center;
  gap: 10px;
  padding: 10px 12px;
  background: #f0f0f0;
  border-top: 1px solid #d0d0d0;
}
.seolei-footer-btn {
  background: #f5f5f5;
  border: 1.5px solid #bbb;
  border-radius: 20px;
  padding: 6px 16px;
  font-size: 10px;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  color: #333;
  cursor: pointer;
  transition: background 0.15s;
}
.seolei-footer-btn:hover { background: #e0e0e0; }
.seolei-footer-bar {
  background: #1a1a1a;
  display: flex;
  align-items: center;
  padding: 7px 12px;
  gap: 6px;
}
.seolei-footer-icon {
  width: 24px; height: 24px;
  background: #333;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  color: #ccc;
  flex-shrink: 0;
}
.seolei-footer-credits {
  flex: 1;
  text-align: center;
  font-size: 9px;
  color: #888;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  letter-spacing: 0.5px;
}
/* =========================================== */
/* SWACKIE.COM WINDOWS 98 DREAM CARD            */
/* =========================================== */
.swackie-window {
  background: #c0c0c0;
  border-top: 2px solid #ffffff;
  border-left: 2px solid #ffffff;
  border-right: 2px solid #808080;
  border-bottom: 2px solid #808080;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  box-shadow: 3px 3px 12px rgba(0,0,0,0.6);
  animation: dreamCardIn 0.45s cubic-bezier(0.34,1.2,0.64,1);
}
.swackie-titlebar {
  background: linear-gradient(90deg, #000080, #1084d0);
  display: flex;
  align-items: center;
  padding: 3px 4px;
  gap: 6px;
}
.swackie-titlebar-title {
  flex: 1;
  font-size: 11px;
  color: #fff;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  font-weight: 700;
  letter-spacing: 0.3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.swackie-win-btns { display: flex; gap: 2px; }
.swackie-win-btn {
  width: 18px; height: 16px;
  background: #c0c0c0;
  border-top: 1px solid #fff;
  border-left: 1px solid #fff;
  border-right: 1px solid #808080;
  border-bottom: 1px solid #808080;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  color: #000;
  font-weight: 900;
  font-family: 'Arial', sans-serif;
  cursor: pointer;
  flex-shrink: 0;
}
.swackie-win-btn:active {
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff;
}
/* inner content area */
.swackie-inner {
  padding: 4px;
  display: flex;
  gap: 4px;
}
/* left pane */
.swackie-left-col {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 44%;
}
.swackie-pane {
  background: #d4d0c8;
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff;
  padding: 5px;
  position: relative;
}
.swackie-pane-title {
  font-size: 10px;
  font-weight: 700;
  color: #000;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  margin-bottom: 4px;
}
.swackie-msg-item {
  margin-bottom: 5px;
}
.swackie-msg-time {
  font-size: 8px;
  color: #000;
  font-weight: 700;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
}
.swackie-msg-text {
  font-size: 8.5px;
  color: #111;
  line-height: 1.4;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  background: #fff;
  border: 1px solid #808080;
  padding: 3px 5px;
  margin-top: 1px;
  word-break: break-all;
}
.swackie-scrollbar {
  position: absolute;
  right: 2px; top: 22px; bottom: 4px;
  width: 12px;
  background: #c0c0c0;
  border-top: 1px solid #fff;
  border-left: 1px solid #fff;
  border-right: 1px solid #808080;
  border-bottom: 1px solid #808080;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.swackie-scrollbar-arrow {
  width: 12px; height: 12px;
  background: #c0c0c0;
  border-top: 1px solid #fff;
  border-left: 1px solid #fff;
  border-right: 1px solid #808080;
  border-bottom: 1px solid #808080;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 7px;
  color: #000;
  flex-shrink: 0;
}
.swackie-scrollbar-thumb {
  flex: 1;
  width: 10px;
  background: #c0c0c0;
  border: 1px solid #808080;
  margin: 1px;
}
/* right panel */
.swackie-right-col {
  flex: 1;
  display: flex;
  gap: 4px;
}
.swackie-profile-pane {
  flex: 1;
  background: #d4d0c8;
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff;
  padding: 5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}
.swackie-profile-title {
  font-size: 11px;
  font-weight: 900;
  color: #000080;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  text-align: center;
  letter-spacing: 0.5px;
}
.swackie-profile-img {
  width: 100%;
  aspect-ratio: 1/1.15;
  background: #aaa;
  border: 2px solid #808080;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.swackie-profile-img img { width: 100%; height: 100%; object-fit: cover; }
.swackie-profile-img i { font-size: 36px; color: #666; }
.swackie-welcome-badge {
  background: #000080;
  color: #fff;
  font-size: 8px;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  padding: 2px 7px;
  border-radius: 2px;
  font-weight: 700;
}
.swackie-profile-desc {
  font-size: 8.5px;
  color: #111;
  line-height: 1.5;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  text-align: left;
  width: 100%;
}
/* side number tabs */
.swackie-tabs-col {
  display: flex;
  flex-direction: column;
  gap: 3px;
  width: 22px;
}
.swackie-tab-btn {
  background: #c0c0c0;
  border-top: 2px solid #fff;
  border-left: 2px solid #fff;
  border-right: 2px solid #808080;
  border-bottom: 2px solid #808080;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8px;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  font-weight: 700;
  color: #000;
  cursor: pointer;
  writing-mode: vertical-rl;
  text-orientation: mixed;
  letter-spacing: 1px;
}
.swackie-tab-btn.active {
  background: #d4d0c8;
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff;
}
/* bottom vol bar */
.swackie-volbar {
  background: #c0c0c0;
  border-top: 1px solid #808080;
  margin: 0 4px;
  padding: 3px 6px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.swackie-vol-label {
  font-size: 9px;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  color: #000;
  white-space: nowrap;
}
.swackie-slider-wrap {
  flex: 1;
  position: relative;
  height: 14px;
  display: flex;
  align-items: center;
}
.swackie-slider-track {
  width: 100%;
  height: 3px;
  background: #808080;
  border-top: 1px solid #808080;
  border-bottom: 1px solid #fff;
}
.swackie-slider-thumb {
  position: absolute;
  left: 40%;
  width: 10px; height: 14px;
  background: #c0c0c0;
  border-top: 2px solid #fff;
  border-left: 2px solid #fff;
  border-right: 2px solid #808080;
  border-bottom: 2px solid #808080;
}
.swackie-mp3-area {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 8.5px;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  color: #000;
}
.swackie-vis-bars {
  display: flex;
  align-items: flex-end;
  gap: 1px;
  height: 12px;
}
.swackie-vis-bar {
  width: 2px;
  background: #000080;
  animation: swackieVis 0.6s ease-in-out infinite alternate;
}
@keyframes swackieVis {
  from { height: 30%; }
  to   { height: 100%; }
}
/* status bar */
.swackie-statusbar {
  background: #c0c0c0;
  border-top: 1px solid #808080;
  display: flex;
  font-size: 8px;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  color: #000;
}
.swackie-status-cell {
  border-right: 1px solid #808080;
  border-top: 1px solid #fff;
  padding: 2px 6px;
  flex: 1;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
}
/* dream card action buttons (below swackie window) */
.swackie-action-row {
  display: flex;
  gap: 8px;
  margin-top: 6px;
}
.swackie-action-btn {
  flex: 1;
  background: #c0c0c0;
  border-top: 2px solid #fff;
  border-left: 2px solid #fff;
  border-right: 2px solid #808080;
  border-bottom: 2px solid #808080;
  font-size: 10px;
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace;
  color: #000;
  padding: 5px 4px;
  cursor: pointer;
  text-align: center;
}
.swackie-action-btn:active {
  border-top: 2px solid #808080;
  border-left: 2px solid #808080;
  border-right: 2px solid #fff;
  border-bottom: 2px solid #fff;
}
/* Archive section */
.dream-archive-section {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 12px;
  overflow: hidden;
}
.dream-archive-header {
  padding: 12px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  cursor: pointer;
}
.dream-archive-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
}
.dream-archive-count {
  font-size: 9px;
  color: rgba(255,255,255,0.3);
  background: rgba(255,255,255,0.08);
  padding: 2px 7px;
  border-radius: 10px;
}
.dream-archive-list { display: block; }
.dream-archive-item {
  padding: 10px 14px;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  cursor: pointer;
  transition: background 0.2s;
}
.dream-archive-item:hover { background: rgba(255,255,255,0.05); }
.dream-archive-item-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 3px;
}
.dream-archive-item-name {
  font-size: 10px;
  font-weight: 700;
  color: rgba(255,255,255,0.75);
}
.dream-archive-item-date {
  font-size: 8px;
  color: rgba(255,255,255,0.3);
}
.dream-archive-item-preview {
  font-size: 9px;
  color: rgba(255,255,255,0.45);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.dream-archive-item-del {
  font-size: 8px;
  color: rgba(255,80,80,0.5);
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  border: 1px solid rgba(255,80,80,0.2);
  margin-left: 8px;
  transition: background 0.2s;
}
.dream-archive-item-del:hover { background: rgba(255,80,80,0.1); color: rgba(255,100,100,0.8); }
/* Settings modal */
.dream-settings-modal {
  display: none;
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.7);
  z-index: 100;
  align-items: flex-end;
}
.dream-settings-modal.open { display: flex; }
.dream-settings-panel {
  background: #1a1a1a;
  border-radius: 16px 16px 0 0;
  width: 100%;
  padding: 20px 16px 32px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  animation: slideUp 0.3s ease;
}
@keyframes slideUp {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}
.dream-settings-panel-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  text-align: center;
}
.dream-settings-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  background: rgba(255,255,255,0.05);
  border-radius: 10px;
  font-size: 11px;
  color: rgba(255,255,255,0.7);
  cursor: pointer;
  transition: background 0.2s;
}
.dream-settings-option:hover { background: rgba(255,255,255,0.09); }
.dream-settings-option.selected { border: 1px solid rgba(255,255,255,0.2); color: #fff; }
.dream-settings-close-btn {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 10px;
  color: rgba(255,255,255,0.6);
  font-size: 12px;
  padding: 10px;
  cursor: pointer;
  font-family: inherit;
}
@keyframes dreamCardIn {
  from { opacity: 0; transform: translateY(18px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes dreamFloat {
  0% { transform: translateY(0) rotate(0deg); opacity: 0.4; }
  100% { transform: translateY(-60px) rotate(30deg); opacity: 0; }
}
.dream-particle {
  position: absolute;
  width: 3px; height: 3px;
  border-radius: 50%;
  background: rgba(255,255,255,0.35);
  animation: dreamFloat linear infinite;
  pointer-events: none;
}
/* ===== 梦境像素字体覆盖 ===== */
#dreamPage,
#dreamPage * {
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace !important;
}
