}
#dreamPage .dream-title-sub-row {
  font-family: 'Press Start 2P', 'DotGothic16', monospace !important;
  font-size: 7px !important;
  letter-spacing: 2px !important;
}
#dreamPage .seolei-window,
#dreamPage .seolei-window * {
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace !important;
}
#dreamPage .swackie-window,
#dreamPage .swackie-window * {
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace !important;
}
#dreamPage .dream-archive-section,
#dreamPage .dream-archive-section * {
  font-family: 'DotGothic16', 'Press Start 2P', 'Courier New', monospace !important;
}
/* dream-settings-panel font override removed */
/* FontAwesome icons should keep their own font */
#dreamPage .fas,
#dreamPage .far,
#dreamPage .fab,
#dreamPage .fa,
