/* ===== 联机软件样式 ===== */
#onlinePage {
  background:
    radial-gradient(circle at top, rgba(255,255,255,0.9), rgba(242,242,242,0.96) 38%, rgba(232,232,232,1) 100%),
    linear-gradient(180deg, #fbfbfb 0%, #ececec 100%);
  color: #222;
  overflow: hidden;
}
.online-shell {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.78) 0%, rgba(245,245,245,0.8) 100%);
}
.online-shell::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 15% 18%, rgba(255,255,255,0.95), transparent 24%),
    radial-gradient(circle at 82% 8%, rgba(214,214,214,0.38), transparent 26%),
    linear-gradient(135deg, rgba(255,255,255,0.48), rgba(215,215,215,0.2));
