}
.online-back-btn,
.online-top-action {
  width: 36px;
  height: 36px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #444;
  cursor: pointer;
  font-size: 13px;
}
.online-title-wrap { flex: 1; min-width: 0; }
.online-title {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 1.5px;
  color: #1d1d1d;
}
.online-subtitle {
  margin-top: 3px;
  font-size: 10px;
  color: #7a7a7a;
  letter-spacing: 1.6px;
  text-transform: uppercase;
