.online-subnav::-webkit-scrollbar { display: none; }
.online-tab-btn {
  border-radius: 999px;
  padding: 8px 14px;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 700;
  color: #6a6a6a;
  cursor: pointer;
}
.online-tab-btn.active {
  background: linear-gradient(180deg, rgba(55,55,55,0.95), rgba(130,130,130,0.92));
  color: #fff;
  border-color: rgba(80,80,80,0.75);
}
.online-content {
  flex: 1;
  overflow-y: auto;
  padding: 0 18px 22px;
}
.online-panel { display: none; animation: onlinePanelIn 0.28s ease; }
.online-panel.active { display: block; }
.online-hero-card,
.online-card,
.online-plain-card,
.online-chat-bubble,
.online-setting-code {
