.online-hero-card {
  padding: 18px;
  margin-bottom: 14px;
}
.online-hero-top {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
}
.online-hero-name {
  font-size: 20px;
  font-weight: 800;
  color: #171717;
}
.online-hero-meta,
.online-muted,
.online-tiny {
  color: #7e7e7e;
}
.online-hero-meta {
  margin-top: 4px;
  font-size: 11px;
  line-height: 1.5;
}
.online-status-pill {
  padding: 7px 12px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
