.ha-ex-btn:active { border-color: #1a1a1a; color: #1a1a1a; }
.ha-ex-btn.del:active { border-color: #999; color: #999; }
.ha-empty { text-align: center; color: #ccc; font-size: 11px; padding: 28px 0; letter-spacing: 0.5px; }
.ha-empty i { display: block; font-size: 24px; margin-bottom: 8px; }
/* Calendar */
.ha-cal-header { display: flex; align-items: center; justify-content: center; gap: 16px; margin-bottom: 12px; }
.ha-cal-nav { background: none; border: none; color: #888; font-size: 16px; cursor: pointer; padding: 4px; }
.ha-cal-month { font-size: 12px; font-weight: 700; color: #1a1a1a; letter-spacing: 2px; text-transform: uppercase; }
.ha-cal-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 2px; }
.ha-cal-dow { text-align: center; font-size: 8px; color: #ccc; font-weight: 700; padding: 3px 0; letter-spacing: 0.5px; }
.ha-cal-day {
