.ha-cal-day.selected { box-shadow: 0 0 0 1.5px #1a1a1a; }
.ha-cal-legend { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 10px; padding-top: 10px; border-top: 1px solid #f0f0f0; }
.ha-cal-legend-item { display: flex; align-items: center; gap: 5px; font-size: 9px; color: #888; font-weight: 600; letter-spacing: 0.5px; }
.ha-cal-legend-dot { width: 10px; height: 10px; border-radius: 2px; flex-shrink: 0; }
.ha-predict-info { font-size: 10px; color: #888; margin-top: 8px; line-height: 1.6; letter-spacing: 0.3px; }
/* Period detail */
.ha-detail-2col { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.ha-field-label { font-size: 9px; color: #aaa; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 6px; }
.ha-chip-group { display: flex; flex-wrap: wrap; gap: 5px; }
.ha-chip {
  padding: 4px 10px; border-radius: 2px; font-size: 10px; font-weight: 700;
  background: #f5f5f5; color: #999; cursor: pointer; transition: all 0.15s;
  border: 1px solid #e8e8e8; letter-spacing: 0.5px; text-transform: uppercase;
