.ha-chip.active { background: #1a1a1a; color: #fff; border-color: #1a1a1a; }
.ha-notes-input {
  width: 100%; border: none; border-bottom: 1px solid #e8e8e8; background: transparent;
  padding: 6px 0; font-size: 11px; color: #555; outline: none; font-family: inherit;
  letter-spacing: 0.3px;
}
.ha-date-inp {
  width: 100%; border: 1px solid #e8e8e8; border-radius: 3px; padding: 7px 10px;
  font-size: 11px; color: #555; outline: none; font-family: inherit; background: #fff;
}
/* Buttons */
.ha-btn-row { display: flex; gap: 8px; margin-top: 16px; }
.ha-btn-primary {
  flex: 1; padding: 11px; background: #1a1a1a; color: #fff; border: none;
  border-radius: 3px; font-size: 10px; font-weight: 700; cursor: pointer;
