  flex: 1; padding: 11px; background: #fff; color: #555; border: 1px solid #e8e8e8;
  border-radius: 3px; font-size: 10px; font-weight: 700; cursor: pointer;
  font-family: inherit; letter-spacing: 2px; text-transform: uppercase; transition: all 0.15s;
}
.ha-btn-secondary:active { border-color: #1a1a1a; color: #1a1a1a; }
.ha-btn-danger {
  padding: 11px 14px; background: #fff; color: #999; border: 1px solid #e8e8e8;
