.ha-persona-row { display: flex; align-items: center; padding: 11px 0; border-bottom: 1px solid #f5f5f5; }
.ha-persona-row:last-child { border-bottom: none; }
.ha-persona-av { width: 36px; height: 36px; border-radius: 50%; object-fit: cover; flex-shrink: 0; border: 1px solid #e8e8e8; }
.ha-persona-av-ph { width: 36px; height: 36px; border-radius: 50%; background: #f0f0f0; display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700; color: #aaa; flex-shrink: 0; border: 1px solid #e8e8e8; }
