.shop-switcher-dot.open { background: #7fff7f; }
.shop-switcher-tab.active .shop-switcher-dot { background: rgba(127,255,127,0.8); }
.shop-switcher-add {
  padding: 6px 14px; border-radius: 20px; font-size: 11px; font-weight: 700;
  cursor: pointer; border: 1.5px dashed #d0d0d0; background: #fff; color: #bbb;
  white-space: nowrap; flex-shrink: 0; transition: all 0.15s;
}
.shop-switcher-add:active { background: #f5f5f5; }
/* ── Ingredient inventory + craft section ── */
.shop-ingredient-section {
  background: #fff; border: 1.5px solid #ebebeb; border-radius: 14px; overflow: hidden;
  margin-bottom: 12px;
}
.shop-ingredient-section-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 11px 15px; border-bottom: 1px solid #f0f0f0;
}
.shop-ingredient-section-title {
  font-size: 10px; font-weight: 800; color: #1a1a1a; letter-spacing: 1px; text-transform: uppercase;
}
.shop-ingredient-list {
  display: grid; grid-template-columns: repeat(3,1fr); gap: 8px; padding: 12px;
}
.shop-ingredient-item {
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  background: #f8f8f8; border-radius: 10px; padding: 10px 6px;
  border: 1.5px solid #ebebeb;
}
.shop-ingredient-qty {
  font-size: 16px; font-weight: 800; color: #1a1a1a; font-family: 'DM Mono',monospace; line-height: 1;
}
.shop-ingredient-qty.zero { color: #ccc; }
.shop-ingredient-name { font-size: 9px; color: #888; text-align: center; line-height: 1.3; }
.shop-craft-section { padding: 0 12px 12px; }
.shop-craft-title { font-size: 10px; font-weight: 800; color: #1a1a1a; letter-spacing: 1px; text-transform: uppercase; margin-bottom: 8px; }
.shop-craft-row {
  display: flex; align-items: center; gap: 10px;
  background: #f8f8f8; border-radius: 10px; padding: 10px 12px; margin-bottom: 7px;
  border: 1.5px solid #ebebeb;
}
.shop-craft-row:last-child { margin-bottom: 0; }
.shop-craft-name { flex: 1; font-size: 12px; font-weight: 700; color: #1a1a1a; }
.shop-craft-cost { font-size: 10px; color: #aaa; }
.shop-craft-btn {
  padding: 6px 13px; background: #1a1a1a; color: #fff;
  border: none; border-radius: 9px; font-size: 10px; font-weight: 800; cursor: pointer;
  white-space: nowrap;
}
.shop-craft-btn:active { transform: scale(0.95); }
.shop-craft-btn:disabled { background: #ddd; color: #bbb; cursor: not-allowed; }
/* ── Ingredient shop overlay ── */
.shop-ing-sheet {
  background: #fff; border-radius: 22px 22px 0 0;
  padding: 20px 18px 32px; width: 100%; max-width: 440px;
  max-height: 85vh; display: flex; flex-direction: column;
}
.shop-ing-sheet-header {
  display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px;
}
.shop-ing-wallet-badge {
  background: #1a1a1a; color: #fff; border-radius: 20px;
  padding: 5px 13px; font-size: 11px; font-weight: 800;
  font-family: 'DM Mono', monospace; letter-spacing: 0.5px;
}
.shop-ing-gen-btn {
  width: 100%; padding: 11px; background: #f5f5f5; border: none;
  border-radius: 12px; font-size: 11px; font-weight: 700; color: #555;
  cursor: pointer; letter-spacing: 0.5px; margin-bottom: 4px;
}
.shop-ing-gen-btn.primary { background: #1a1a1a; color: #fff; }
.shop-ing-gen-btn:active { opacity: 0.85; }
.shop-ing-gen-btn:disabled { opacity: 0.4; cursor: not-allowed; }
.shop-ing-item {
  display: flex; align-items: center; gap: 12px;
  background: #f8f8f8; border: 1.5px solid #ebebeb; border-radius: 12px; padding: 11px 13px;
}
.shop-ing-item-info { flex: 1; min-width: 0; }
.shop-ing-item-name { font-size: 12px; font-weight: 800; color: #1a1a1a; }
.shop-ing-item-sub  { font-size: 10px; color: #aaa; margin-top: 2px; }
.shop-ing-item-rare { color: #b07d3a; }
.shop-ing-item-qty  { font-size: 14px; font-weight: 800; color: #1a1a1a; font-family:'DM Mono',monospace; min-width:24px; text-align:center; }
.shop-ing-buy-controls { display: flex; align-items: center; gap: 6px; }
.shop-ing-qty-btn {
  width: 28px; height: 28px; border-radius: 50%; background: #f0f0f0; border: none;
  font-size: 16px; font-weight: 700; color: #333; cursor: pointer;
  display: flex; align-items: center; justify-content: center; line-height: 1; flex-shrink: 0;
}
.shop-ing-qty-btn:active { background: #e0e0e0; }
.shop-ing-qty-num { font-size: 14px; font-weight: 800; font-family:'DM Mono',monospace; min-width: 20px; text-align: center; }
.shop-ing-qty-input {
  width: 56px; height: 30px; border-radius: 9px; border: 1px solid #e2e2e2;
  background: #fff; color: #1a1a1a; text-align: center; font-size: 12px;
  font-weight: 800; font-family:'DM Mono',monospace; outline: none;
  padding: 0 4px;
}
.shop-ing-qty-input:focus { border-color: #1a1a1a; }
.shop-ing-price { font-size: 11px; font-weight: 700; color: #1a1a1a; white-space:nowrap; }
.shop-ing-confirm-btn {
  padding: 7px 13px; background: #1a1a1a; color: #fff;
  border: none; border-radius: 9px; font-size: 10px; font-weight: 800;
  cursor: pointer; white-space: nowrap;
}
.shop-ing-confirm-btn:disabled { background: #ddd; color: #bbb; cursor: not-allowed; }
.shop-ing-confirm-btn:not(:disabled):active { transform: scale(0.95); }
/* ── Synthesis overlay ── */
.shop-synth-ing-row {
  display: flex; align-items: center; gap: 10px;
  background: #f8f8f8; border: 1.5px solid #ebebeb; border-radius: 10px; padding: 9px 12px;
  cursor: pointer; transition: all 0.15s;
}
.shop-synth-ing-row.selected { border-color: #1a1a1a; background: #f0f0f0; }
.shop-synth-ing-row.disabled { opacity: 0.45; cursor: default; }
.shop-synth-ing-name { flex: 1; font-size: 12px; font-weight: 700; color: #1a1a1a; }
.shop-synth-ing-qty  { font-size: 11px; color: #aaa; font-family:'DM Mono',monospace; }
.shop-synth-chip {
  display: inline-flex; align-items: center; gap: 5px;
  background: #1a1a1a; color: #fff; border-radius: 20px; padding: 4px 10px;
  font-size: 10px; font-weight: 700; cursor: pointer;
}
.shop-synth-chip:active { opacity: 0.7; }
.shop-synth-result-card {
  background: #f8f8f8; border: 1.5px solid #1a1a1a; border-radius: 12px; padding: 14px;
}
.shop-synth-result-name { font-size: 15px; font-weight: 800; color: #1a1a1a; margin-bottom: 5px; }
.shop-synth-result-tag {
  display: inline-block; padding: 2px 9px; border-radius: 20px; font-size: 9px; font-weight: 800;
  letter-spacing: 0.3px; margin-right: 5px; margin-bottom: 6px;
}
.shop-synth-result-tag.limited  { background: #1a1a1a; color: #fff; }
.shop-synth-result-tag.seasonal { background: #5a8a5a; color: #fff; }
.shop-synth-result-tag.normal   { background: #f0f0f0; color: #888; }
.shop-synth-result-desc { font-size: 11px; color: #555; line-height: 1.6; margin-bottom: 8px; }
.shop-synth-add-btn {
  width: 100%; padding: 11px; background: #1a1a1a; color: #fff; border: none;
  border-radius: 10px; font-size: 11px; font-weight: 800; cursor: pointer; letter-spacing: 0.5px;
}
.shop-synth-add-btn:active { background: #333; }
.shop-pulse-wrap { padding: 16px 18px; display: flex; flex-direction: column; gap: 14px; }
.shop-pulse-gen-btn {
  width: 100%; padding: 14px; background: #1a1a1a; color: #fff; border: none;
  border-radius: 14px; font-size: 12px; font-weight: 800; cursor: pointer;
  letter-spacing: 1px; text-transform: uppercase;
}
.shop-pulse-gen-btn:active { background: #333; }
.shop-pulse-gen-btn:disabled { background: #ccc; cursor: not-allowed; }
.shop-pulse-loading {
  display: flex; flex-direction: column; align-items: center; gap: 10px;
  padding: 32px 0; color: #aaa; font-size: 12px; letter-spacing: 0.5px;
}
.shop-pulse-loading-dots { display: flex; gap: 5px; }
.shop-pulse-loading-dots span {
  width: 6px; height: 6px; background: #ccc; border-radius: 50%;
  animation: pulseLoadDot 1.2s infinite;
}
.shop-pulse-loading-dots span:nth-child(2) { animation-delay: 0.2s; }
.shop-pulse-loading-dots span:nth-child(3) { animation-delay: 0.4s; }
@keyframes pulseLoadDot { 0%,80%,100%{transform:scale(0.6);opacity:0.4} 40%{transform:scale(1);opacity:1} }
.shop-pulse-card {
  background: #fff; border: 1.5px solid #ebebeb; border-radius: 16px; overflow: hidden;
}
.shop-pulse-card-header {
  padding: 12px 16px; border-bottom: 1px solid #f0f0f0;
  display: flex; align-items: center; gap: 8px;
}
.shop-pulse-card-ico {
  width: 28px; height: 28px; border-radius: 8px; background: #1a1a1a;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; color: #fff; font-weight: 800; flex-shrink: 0;
  font-family: 'DM Mono', monospace;
}
.shop-pulse-card-title {
  font-size: 10px; font-weight: 800; color: #1a1a1a;
  letter-spacing: 1.2px; text-transform: uppercase;
}
.shop-pulse-card-body {
  padding: 13px 16px; font-size: 12px; color: #444; line-height: 1.8;
}
.shop-pulse-rating-bar-row {
  display: flex; align-items: center; gap: 10px; margin-bottom: 8px;
}
.shop-pulse-rating-label { font-size: 10px; color: #888; width: 52px; flex-shrink: 0; }
.shop-pulse-rating-track {
  flex: 1; height: 6px; background: #f0f0f0; border-radius: 3px; overflow: hidden;
}
.shop-pulse-rating-fill { height: 100%; background: #1a1a1a; border-radius: 3px; transition: width 0.5s; }
.shop-pulse-rating-score {
  font-size: 10px; font-weight: 700; color: #1a1a1a; width: 24px;
  text-align: right; font-family: 'DM Mono', monospace;
}
.shop-pulse-review-item {
  padding: 10px 0; border-bottom: 1px solid #f5f5f5;
}
.shop-pulse-review-item:last-child { border-bottom: none; }
.shop-pulse-review-author {
  font-size: 11px; font-weight: 700; color: #1a1a1a; margin-bottom: 3px;
}
.shop-pulse-review-cat {
  display: inline-block; padding: 1px 7px; background: #f0f0f0;
  border-radius: 20px; font-size: 9px; color: #888; font-weight: 700;
  margin: 0 4px 5px 0; letter-spacing: 0.3px;
}
.shop-pulse-review-text { font-size: 11px; color: #555; line-height: 1.6; }
.shop-pulse-staff-opinion {
  padding: 10px 0; border-bottom: 1px solid #f5f5f5;
  display: flex; align-items: flex-start; gap: 10px;
}
.shop-pulse-staff-opinion:last-child { border-bottom: none; }
.shop-pulse-staff-av {
  width: 32px; height: 32px; border-radius: 50%; background: #f0f0f0;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 800; color: #555; flex-shrink: 0; overflow: hidden;
}
.shop-pulse-staff-av img { width: 100%; height: 100%; object-fit: cover; }
.shop-pulse-staff-body { flex: 1; }
.shop-pulse-staff-name { font-size: 11px; font-weight: 700; color: #1a1a1a; margin-bottom: 3px; }
.shop-pulse-staff-text { font-size: 11px; color: #555; line-height: 1.6; }
/* ── Role picker ── */
.shop-role-row {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 14px; background: #f8f8f8; border-radius: 12px;
  cursor: pointer; border: 1.5px solid transparent; transition: all 0.15s;
}
.shop-role-row:not(.taken):active { background: #f0f0f0; }
.shop-role-row.taken { opacity: 0.4; cursor: default; }
.shop-role-badge {
  width: 36px; height: 36px; border-radius: 10px; background: #1a1a1a;
  display: flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 800; color: #fff; flex-shrink: 0; text-align: center; line-height: 1.2;
}
.shop-role-info { flex: 1; }
.shop-role-name { font-size: 13px; font-weight: 800; color: #1a1a1a; }
.shop-role-bonus { font-size: 10px; color: #aaa; margin-top: 2px; }
.shop-role-taken-badge { font-size: 9px; font-weight: 700; color: #bbb; white-space: nowrap; }
.shop-reno-wrap { padding: 16px 18px; display: flex; flex-direction: column; gap: 14px; }
.shop-reno-level-card {
  border: 2px solid #ebebeb; border-radius: 16px; overflow: hidden;
  transition: border-color 0.2s;
}
.shop-reno-level-card.active { border-color: #1a1a1a; }
.shop-reno-level-card.locked { opacity: 0.55; }
.shop-reno-level-header {
  display: flex; align-items: center; gap: 12px;
  padding: 14px 16px; background: #fff;
}
.shop-reno-level-badge {
  width: 36px; height: 36px; border-radius: 10px; background: #1a1a1a;
  display: flex; align-items: center; justify-content: center;
  font-size: 16px; flex-shrink: 0; color: #fff;
}
.shop-reno-level-badge.lite { background: #f0f0f0; color: #1a1a1a; }
.shop-reno-level-info { flex: 1; }
.shop-reno-level-name { font-size: 13px; font-weight: 800; color: #1a1a1a; }
.shop-reno-level-sub { font-size: 10px; color: #aaa; margin-top: 2px; }
.shop-reno-level-status {
  font-size: 9px; font-weight: 800; padding: 4px 10px; border-radius: 20px;
  background: #1a1a1a; color: #fff; white-space: nowrap;
}
.shop-reno-level-status.current { background: #1a1a1a; }
.shop-reno-level-status.locked-badge { background: #f0f0f0; color: #aaa; }
.shop-reno-perks { padding: 0 16px 14px; background: #fff; display: flex; flex-direction: column; gap: 5px; }
.shop-reno-perk-row { display: flex; align-items: center; gap: 8px; font-size: 11px; color: #555; }
.shop-reno-perk-dot { width: 5px; height: 5px; border-radius: 50%; background: #1a1a1a; flex-shrink: 0; }
.shop-reno-upgrade-btn {
  width: 100%; padding: 13px; background: #1a1a1a; color: #fff; border: none;
  border-radius: 14px; font-size: 12px; font-weight: 800; cursor: pointer; letter-spacing: 1px;
}
.shop-reno-upgrade-btn:active { background: #333; }
.shop-reno-upgrade-btn:disabled { background: #ccc; cursor: not-allowed; }
/* ── Tasks tab ── */
.shop-tasks-wrap { padding: 16px 18px; display: flex; flex-direction: column; gap: 14px; }
.shop-tasks-section-title {
  font-size: 10px; font-weight: 800; color: #999;
  letter-spacing: 1.5px; text-transform: uppercase;
}
.shop-task-item {
  display: flex; align-items: center; gap: 12px;
  background: #fff; border: 1.5px solid #ebebeb; border-radius: 14px; padding: 12px 14px;
}
.shop-task-item.claimed { background: #f8f8f8; border-color: #ebebeb; }
.shop-task-ico { font-size: 20px; width: 28px; text-align: center; flex-shrink: 0; }
.shop-task-info { flex: 1; }
.shop-task-name { font-size: 12px; font-weight: 700; color: #1a1a1a; }
.shop-task-desc { font-size: 10px; color: #aaa; margin-top: 1px; }
.shop-task-progress { font-size: 9px; color: #888; margin-top: 3px; font-family: 'DM Mono',monospace; }
.shop-task-claim-btn {
  padding: 7px 14px; background: #1a1a1a; color: #fff;
  border: none; border-radius: 10px; font-size: 10px; font-weight: 800;
  cursor: pointer; white-space: nowrap; flex-shrink: 0;
}
.shop-task-claim-btn:active { transform: scale(0.95); }
.shop-task-done-chip {
  padding: 5px 10px; background: #f0f0f0; color: #bbb;
  border-radius: 10px; font-size: 10px; font-weight: 700; white-space: nowrap; flex-shrink: 0;
}
.shop-task-reward-chip {
  font-size: 10px; color: #888; white-space: nowrap; flex-shrink: 0;
}
/* Achievement card */
.shop-achv-card {
  display: flex; align-items: center; gap: 12px;
  background: #fff; border: 1.5px solid #ebebeb; border-radius: 14px; padding: 13px 15px;
}
.shop-achv-card.unlocked { border-color: #1a1a1a; }
.shop-achv-icon { font-size: 22px; width: 32px; text-align: center; flex-shrink: 0; }
.shop-achv-info { flex: 1; }
.shop-achv-name { font-size: 12px; font-weight: 800; color: #1a1a1a; }
.shop-achv-cond { font-size: 10px; color: #aaa; margin-top: 2px; }
.shop-achv-reward { font-size: 10px; color: #888; margin-top: 2px; }
.shop-achv-badge {
  font-size: 9px; font-weight: 800; padding: 4px 10px;
  border-radius: 20px; white-space: nowrap; flex-shrink: 0;
}
.shop-achv-badge.done { background: #1a1a1a; color: #fff; }
.shop-achv-badge.pending { background: #f0f0f0; color: #aaa; }
/* ── Store/mall tab ── */
.shop-store-wrap { padding: 16px 18px; display: flex; flex-direction: column; gap: 14px; }
.shop-store-coins-bar {
  display: flex; align-items: center; justify-content: space-between;
  background: #1a1a1a; border-radius: 14px; padding: 14px 18px;
}
.shop-store-coins-label { font-size: 10px; color: rgba(255,255,255,0.5); letter-spacing: 1px; text-transform: uppercase; }
.shop-store-coins-val { font-size: 22px; font-weight: 800; color: #fff; font-family: 'DM Mono',monospace; }
.shop-store-cat-title {
  font-size: 10px; font-weight: 800; color: #999; letter-spacing: 1.5px; text-transform: uppercase; margin-bottom: 2px;
}
.shop-store-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.shop-store-item {
  background: #fff; border: 1.5px solid #ebebeb; border-radius: 14px;
  padding: 14px 12px; display: flex; flex-direction: column; gap: 7px;
}
.shop-store-item-icon { font-size: 26px; }
.shop-store-item-name { font-size: 12px; font-weight: 800; color: #1a1a1a; line-height: 1.3; }
.shop-store-item-desc { font-size: 10px; color: #aaa; line-height: 1.4; }
.shop-store-item-footer { display: flex; align-items: center; justify-content: space-between; margin-top: 2px; }
.shop-store-item-price { font-size: 13px; font-weight: 800; color: #1a1a1a; font-family: 'DM Mono',monospace; }
.shop-store-buy-btn {
  padding: 6px 14px; background: #1a1a1a; color: #fff;
  border: none; border-radius: 9px; font-size: 10px; font-weight: 800; cursor: pointer;
}
.shop-store-buy-btn:active { transform: scale(0.95); }
.shop-store-buy-btn:disabled { background: #ddd; color: #bbb; cursor: not-allowed; }
/* ── Product tag + freshness ── */
.shop-product-tag-ambiguous {
  display: inline-block; margin-top: 4px; margin-right: 4px; padding: 2px 8px;
  background: #1a1a1a; border-radius: 20px; font-size: 9px; color: #fff; font-weight: 700;
  letter-spacing: 0.3px;
}
.shop-product-fresh-bar {
  display: flex; align-items: center; gap: 6px; margin-top: 5px;
}
.shop-product-fresh-track {
  flex: 1; height: 4px; background: #f0f0f0; border-radius: 2px; overflow: hidden;
}
.shop-product-fresh-fill { height: 100%; background: #1a1a1a; border-radius: 2px; transition: width 0.3s; }
.shop-product-fresh-fill.low { background: #c0392b; }
.shop-product-fresh-label { font-size: 9px; color: #aaa; white-space: nowrap; font-family: 'DM Mono',monospace; }
.shop-product-limited-badge {
  position: absolute; top: -1px; left: -1px;
  background: #1a1a1a; color: #fff; font-size: 8px; font-weight: 800;
  padding: 2px 7px; border-radius: 14px 0 8px 0; letter-spacing: 0.3px;
}
/* ── Staff train ── */
.shop-staff-train-btn {
  padding: 5px 10px; border-radius: 20px; font-size: 9px; font-weight: 700;
  cursor: pointer; border: 1.5px solid #1a1a1a; background: #fff;
  color: #1a1a1a; letter-spacing: 0.3px; margin-top: 4px;
}
.shop-staff-train-btn:active { background: #f5f5f5; }
/* ── Message board ── */
.shop-msg-item {
  background: #f8f8f8; border-radius: 12px; padding: 12px 14px;
  display: flex; flex-direction: column; gap: 4px;
}
.shop-msg-author { font-size: 11px; font-weight: 700; color: #1a1a1a; }
.shop-msg-text { font-size: 12px; color: #444; line-height: 1.5; }
.shop-msg-time { font-size: 9px; color: #bbb; font-family: 'DM Mono',monospace; }
/* ── Ingredient gift section in overview ── */
.shop-ingredient-row {
  display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px;
}
.shop-ingredient-row::-webkit-scrollbar { display: none; }
.shop-ingredient-chip {
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  flex-shrink: 0; cursor: pointer;
}
.shop-ingredient-chip-box {
  width: 52px; height: 52px; border-radius: 14px; background: #f5f5f5;
  display: flex; align-items: center; justify-content: center;
  font-size: 24px; border: 1.5px solid #e8e8e8; transition: all 0.15s;
}
.shop-ingredient-chip-box:active { transform: scale(0.93); }
.shop-ingredient-chip-name { font-size: 8px; color: #888; text-align: center; max-width: 52px; }
/* add product / name modal (shared) */
.shop-modal-overlay {
  display: none; position: fixed; inset: 0; z-index: 1400;
  background: rgba(0,0,0,0.55); align-items: center; justify-content: center; padding: 24px;
}
.shop-modal-overlay.open { display: flex; }
.shop-modal {
  background: #fff; border-radius: 20px; padding: 24px 20px;
  width: 100%; max-width: 360px; max-height: 88vh; overflow-y: auto;
}
.shop-modal::-webkit-scrollbar { display: none; }
.shop-modal-title { font-size: 15px; font-weight: 800; color: #1a1a1a; margin-bottom: 16px; letter-spacing: 0.3px; }
.shop-modal-label { font-size: 10px; font-weight: 800; color: #888; letter-spacing: 1px; text-transform: uppercase; margin-bottom: 6px; display: block; }
.shop-modal-input {
  width: 100%; padding: 11px 14px; border: 1.5px solid #e0e0e0; border-radius: 12px;
  font-size: 13px; color: #1a1a1a; background: #fafafa; margin-bottom: 14px;
  box-sizing: border-box; font-family: inherit; outline: none;
}
.shop-modal-input:focus { border-color: #1a1a1a; }
.shop-modal-select {
  width: 100%; padding: 11px 14px; border: 1.5px solid #e0e0e0; border-radius: 12px;
  font-size: 13px; color: #1a1a1a; background: #fafafa; margin-bottom: 14px;
  box-sizing: border-box; font-family: inherit; outline: none; cursor: pointer;
  appearance: none;
}
.shop-modal-btns { display: flex; gap: 10px; margin-top: 4px; }
.shop-modal-cancel {
  flex: 1; padding: 12px; background: #f5f5f5; border: none;
  border-radius: 12px; font-size: 12px; font-weight: 700; color: #888; cursor: pointer;
}
.shop-modal-confirm {
  flex: 2; padding: 12px; background: #1a1a1a; border: none;
  border-radius: 12px; font-size: 12px; font-weight: 800; color: #fff; cursor: pointer;
}
.shop-modal-confirm:active { background: #333; }
/* ===== PET APP PAGE ===== */
#petAppPage {
  display: none; position: fixed; inset: 0; z-index: 900;
  background: #f7f5f0; flex-direction: column; overflow: hidden;
}
#petAppPage.active { display: flex; }
.pet-app-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 16px 10px;
  border-bottom: 1px solid #e8e8e8;
  background: #fff;
}
.pet-app-header-title {
  font-size: 15px; font-weight: 800; letter-spacing: 0.5px; color: #1a1a1a;
  font-family: 'DM Mono', monospace;
}
.pet-app-back {
  width: 32px; height: 32px; border-radius: 50%; background: #f0f0f0;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; font-size: 14px; color: #333; border: none;
}
.pet-app-tabs {
  display: flex; gap: 0; background: #fff;
  border-bottom: 1px solid #e8e8e8;
}
.pet-app-tab {
  flex: 1; padding: 9px 4px; text-align: center;
  font-size: 10px; font-weight: 700; letter-spacing: 0.5px;
  color: #999; cursor: pointer; border-bottom: 2px solid transparent;
  transition: all 0.2s; text-transform: uppercase;
}
.pet-app-tab.active { color: #1a1a1a; border-bottom-color: #1a1a1a; }
.pet-app-body { flex: 1; overflow-y: auto; }
/* Gacha tab */
.pet-gacha-machine {
  display: flex; flex-direction: column; align-items: center;
  padding: 20px 16px 12px;
}
.pet-gacha-svg-wrap {
  width: 120px; height: 160px; position: relative; margin-bottom: 16px;
}
.pet-gacha-count {
  font-size: 11px; color: #888; font-family: 'DM Mono', monospace;
  margin-bottom: 10px; letter-spacing: 1px;
}
.pet-gacha-btn {
  background: #1a1a1a; color: #fff; border: none; border-radius: 20px;
  padding: 11px 36px; font-size: 13px; font-weight: 800;
  cursor: pointer; letter-spacing: 1px; transition: transform 0.15s;
  font-family: 'DM Mono', monospace;
}
.pet-gacha-btn:active { transform: scale(0.95); }
.pet-gacha-btn:disabled { background: #ccc; cursor: not-allowed; }
.pet-gacha-pool {
  display: flex; flex-wrap: wrap; gap: 10px; justify-content: center;
  padding: 12px 16px;
}
.pet-gacha-pool-item {
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  width: 56px;
}
.pet-gacha-pool-img {
  width: 48px; height: 48px; border-radius: 12px;
  background: #f0f0f0; border: 1px solid #e0e0e0;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.pet-gacha-pool-img img { width: 40px; height: 40px; object-fit: contain; }
.pet-gacha-pool-name { font-size: 8px; color: #888; text-align: center; }
/* Hatch overlay */
.pet-hatch-overlay {
  display: none; position: fixed; inset: 0; z-index: 1000;
  background: rgba(0,0,0,0.6); align-items: center; justify-content: center;
  flex-direction: column; gap: 12px;
}
.pet-hatch-overlay.open { display: flex; }
.pet-hatch-egg {
  width: 100px; height: 120px; position: relative;
  animation: petEggWobble 0.5s ease-in-out infinite;
}
@keyframes petEggWobble {
  0%,100%{transform:rotate(-5deg)} 50%{transform:rotate(5deg)}
}
.pet-hatch-label {
  color: #fff; font-size: 14px; font-weight: 700; text-align: center;
  font-family: 'DM Mono', monospace;
}
.pet-hatch-progress {
  width: 180px; height: 6px; background: rgba(255,255,255,0.2);
  border-radius: 3px; overflow: hidden;
}
.pet-hatch-progress-bar {
  height: 100%; background: #fff; border-radius: 3px;
  transition: width 0.3s;
}
.pet-hatch-action-btn {
  background: #fff; color: #1a1a1a; border: none; border-radius: 20px;
  padding: 10px 32px; font-size: 12px; font-weight: 800;
  cursor: pointer; letter-spacing: 0.5px; margin-top: 4px;
}
/* My Pet tab */
.pet-my-area { padding: 14px 16px; }
.pet-my-empty {
  text-align: center; padding: 40px 16px; color: #aaa;
  font-size: 12px; line-height: 1.8;
}
.pet-status-bars { display: flex; flex-direction: column; gap: 7px; margin-bottom: 14px; }
.pet-status-row {
  display: flex; align-items: center; gap: 7px;
}
.pet-status-icon { font-size: 14px; width: 18px; text-align: center; }
.pet-status-label { font-size: 9px; color: #888; width: 28px; letter-spacing: 0.3px; }
.pet-status-bar-wrap {
  flex: 1; height: 6px; background: #ebebeb; border-radius: 3px; overflow: hidden;
}
.pet-status-bar-fill { height: 100%; border-radius: 3px; transition: width 0.4s; }
.pet-status-val { font-size: 9px; color: #aaa; width: 24px; text-align: right; font-family: 'DM Mono', monospace; }
.pet-character-area {
  display: flex; flex-direction: column; align-items: center;
  padding: 10px 0 14px;
  position: relative;
}
.pet-character-img {
  width: 110px; height: 110px; object-fit: contain;
  animation: petFloat 3s ease-in-out infinite;
  image-rendering: pixelated;
}
@keyframes petFloat {
  0%,100%{transform:translateY(0)} 50%{transform:translateY(-6px)}
}
.pet-character-name {
  font-size: 13px; font-weight: 800; color: #1a1a1a;
  margin-top: 6px; letter-spacing: 0.5px;
}
.pet-character-stage {
  font-size: 9px; color: #999; letter-spacing: 1px; text-transform: uppercase;
  margin-top: 2px;
}
.pet-speech-bubble {
  background: #fff; border: 1px solid #e0e0e0; border-radius: 12px 12px 12px 0;
  padding: 7px 12px; font-size: 11px; color: #555; line-height: 1.5;
  max-width: 200px; text-align: center; margin-top: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}
.pet-action-btns {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px;
  margin-top: 12px;
}
.pet-action-btn {
  background: #fff; border: 1.5px solid #e0e0e0; border-radius: 12px;
  padding: 10px 6px; font-size: 10px; font-weight: 700; color: #333;
  cursor: pointer; text-align: center; transition: all 0.15s;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
}
.pet-action-btn:active { transform: scale(0.95); background: #f5f5f5; }
.pet-action-btn .btn-icon { font-size: 18px; }
.pet-invite-section {
  margin-top: 14px; padding: 12px; background: #fff;
  border-radius: 14px; border: 1px solid #e8e8e8;
}
.pet-invite-title {
  font-size: 10px; font-weight: 700; color: #999;
  text-transform: uppercase; letter-spacing: 1px; margin-bottom: 8px;
}
.pet-invite-char-row {
  display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px;
}
.pet-invite-char {
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  cursor: pointer; flex-shrink: 0;
}
.pet-invite-char-avatar {
  width: 40px; height: 40px; border-radius: 50%; object-fit: cover;
  border: 2px solid #e0e0e0;
}
.pet-invite-char-avatar.invited { border-color: #1a1a1a; }
.pet-invite-char-name { font-size: 8px; color: #888; text-align: center; max-width: 44px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.pet-invite-char-badge {
  font-size: 7px; color: #fff; background: #1a1a1a; border-radius: 4px;
  padding: 1px 4px; letter-spacing: 0.3px;
}
/* Collection grid */
.pet-collection-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px;
  padding: 14px 16px;
}
.pet-collection-item {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  background: #fff; border-radius: 14px; padding: 12px 6px;
  border: 1.5px solid #e8e8e8; cursor: pointer; transition: all 0.15s;
  position: relative;
}
.pet-collection-item.active-pet { border-color: #1a1a1a; box-shadow: 0 2px 12px rgba(0,0,0,0.1); }
.pet-collection-item:active { transform: scale(0.95); }
.pet-collection-item img { width: 56px; height: 56px; object-fit: contain; image-rendering: pixelated; }
.pet-collection-item-name { font-size: 9px; font-weight: 700; color: #555; text-align: center; }
.pet-collection-active-badge {
  position: absolute; top: 5px; right: 5px;
  background: #1a1a1a; color: #fff; border-radius: 4px;
  font-size: 7px; font-weight: 700; padding: 1px 4px; letter-spacing: 0.3px;
}
.pet-collection-stage { font-size: 8px; color: #aaa; }
/* Co-raise tab */
.pet-coraise-area { padding: 14px 16px; display: flex; flex-direction: column; gap: 14px; }
.pet-coraise-card {
  background: #fff; border-radius: 14px; border: 1px solid #e8e8e8;
  padding: 14px;
}
.pet-coraise-card-title {
  font-size: 10px; font-weight: 800; color: #1a1a1a;
  text-transform: uppercase; letter-spacing: 1px; margin-bottom: 10px;
}
.pet-coraise-partner-row {
  display: flex; align-items: center; gap: 10px; margin-bottom: 12px;
}
.pet-coraise-partner-avatar {
  width: 44px; height: 44px; border-radius: 50%; object-fit: cover;
  border: 2px solid #1a1a1a;
}
.pet-coraise-partner-info { flex: 1; }
.pet-coraise-partner-name { font-size: 12px; font-weight: 700; color: #1a1a1a; }
.pet-coraise-partner-sub { font-size: 10px; color: #aaa; margin-top: 2px; }
.pet-coraise-change-btn {
  padding: 6px 12px; background: #f5f5f5; border: 1px solid #e0e0e0;
  border-radius: 8px; font-size: 10px; font-weight: 700; color: #555;
  cursor: pointer;
}
/* Schedule grid */
.pet-schedule-grid {
  display: grid; grid-template-columns: repeat(6, 1fr); gap: 3px;
  margin-bottom: 8px;
}
.pet-schedule-cell {
  height: 28px; border-radius: 4px; background: #f0f0f0;
  display: flex; align-items: center; justify-content: center;
  font-size: 7px; color: #aaa; cursor: pointer; transition: all 0.1s;
  user-select: none; font-weight: 600;
}
.pet-schedule-cell.user-slot  { background: #1a1a1a; color: #fff; }
.pet-schedule-cell.char-slot  { background: #e8e0f8; color: #7a5ab8; }
.pet-schedule-legend {
  display: flex; gap: 12px; margin-top: 6px;
}
.pet-schedule-legend-item {
  display: flex; align-items: center; gap: 5px; font-size: 9px; color: #888;
}
.pet-schedule-legend-dot {
  width: 10px; height: 10px; border-radius: 2px;
}
.pet-schedule-save-btn {
  width: 100%; margin-top: 10px; padding: 10px;
  background: #1a1a1a; color: #fff; border: none;
  border-radius: 10px; font-size: 12px; font-weight: 700; cursor: pointer;
}
/* Co-raise log */
.pet-coraise-log { display: flex; flex-direction: column; gap: 8px; }
.pet-coraise-log-item {
  display: flex; gap: 9px; align-items: flex-start;
  padding: 8px 0; border-bottom: 1px solid #f5f5f5;
}
.pet-coraise-log-avatar {
  width: 28px; height: 28px; border-radius: 50%; object-fit: cover;
  flex-shrink: 0; border: 1px solid #e0e0e0;
}
.pet-coraise-log-body { flex: 1; }
.pet-coraise-log-text { font-size: 11px; color: #444; line-height: 1.5; }
.pet-coraise-log-time { font-size: 9px; color: #bbb; margin-top: 2px; }
/* Partner select overlay */
.pet-partner-overlay {
  display: none; position: fixed; inset: 0; z-index: 1200;
  background: rgba(0,0,0,0.5); align-items: flex-end; justify-content: center;
}
.pet-partner-overlay.open { display: flex; }
.pet-partner-sheet {
  background: #fff; border-radius: 20px 20px 0 0;
  padding: 18px 18px 32px; width: 100%; max-width: 420px;
}
.pet-partner-sheet-title {
  font-size: 13px; font-weight: 800; color: #1a1a1a;
  margin-bottom: 12px; text-align: center;
}
.pet-partner-list { display: flex; flex-direction: column; gap: 8px; max-height: 240px; overflow-y: auto; }
.pet-partner-row {
  display: flex; align-items: center; gap: 10px;
  padding: 10px; border-radius: 12px; background: #f7f7f7;
  cursor: pointer; transition: all 0.15s;
}
.pet-partner-row:active { background: #efefef; }
.pet-partner-row-avatar {
  width: 40px; height: 40px; border-radius: 50%; object-fit: cover;
  border: 2px solid #e0e0e0;
}
.pet-partner-row-name { flex: 1; font-size: 12px; font-weight: 700; color: #333; }
.pet-partner-row-badge { font-size: 9px; color: #aaa; }
/* ── Pet Chat Tab ── */
.pet-chat-wrap { display: flex; flex-direction: column; height: 100%; }
.pet-chat-list-screen { padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; overflow-y: auto; flex: 1; }
.pet-chat-list-screen::-webkit-scrollbar { display: none; }
.pet-chat-room-card {
  display: flex; align-items: center; gap: 12px;
  background: #fff; border: 1.5px solid #ebebeb; border-radius: 14px;
  padding: 13px 15px; cursor: pointer; transition: all 0.15s;
}
.pet-chat-room-card:active { transform: scale(0.97); background: #f8f8f8; }
.pet-chat-room-avatar {
  width: 48px; height: 48px; border-radius: 50%; object-fit: contain;
  border: 2px solid #1a1a1a; flex-shrink: 0; background: #f5f5f5;
  display: flex; align-items: center; justify-content: center;
  image-rendering: pixelated; overflow: hidden;
}
.pet-chat-room-avatar img { width: 100%; height: 100%; object-fit: contain; image-rendering: pixelated; }
.pet-chat-room-avatars { position: relative; width: 48px; height: 48px; flex-shrink: 0; }
.pet-chat-room-avatars .av1 {
  width: 36px; height: 36px; border-radius: 50%; object-fit: contain;
  border: 2px solid #fff; position: absolute; top: 0; left: 0;
  background: #f5f5f5; image-rendering: pixelated; overflow: hidden;
}
.pet-chat-room-avatars .av2 {
  width: 30px; height: 30px; border-radius: 50%; object-fit: cover;
  border: 2px solid #fff; position: absolute; bottom: 0; right: 0;
  background: #f0f0f0; overflow: hidden;
}
.pet-chat-room-avatars .av1 img,
.pet-chat-room-avatars .av2 img { width: 100%; height: 100%; object-fit: cover; }
.pet-chat-room-info { flex: 1; min-width: 0; }
.pet-chat-room-name { font-size: 13px; font-weight: 800; color: #1a1a1a; }
.pet-chat-room-sub  { font-size: 10px; color: #aaa; margin-top: 2px; }
.pet-chat-new-btn {
  width: 100%; padding: 13px; background: #f5f5f5; border: 1.5px dashed #d0d0d0;
  border-radius: 14px; font-size: 11px; font-weight: 700; color: #aaa;
  cursor: pointer; text-align: center; letter-spacing: 0.3px;
}
.pet-chat-new-btn:active { background: #efefef; }
/* Pet chat conversation screen */
.pet-chat-conv { display: flex; flex-direction: column; height: 100%; background: #f9f9f9; }
.pet-chat-conv-header {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 16px; background: #fff; border-bottom: 1px solid #ebebeb; flex-shrink: 0;
}
.pet-chat-conv-back {
  width: 30px; height: 30px; border-radius: 50%; background: #f2f2f2;
  border: none; cursor: pointer; display: flex; align-items: center; justify-content: center;
  font-size: 13px; color: #333; flex-shrink: 0;
}
.pet-chat-conv-name { font-size: 13px; font-weight: 800; color: #1a1a1a; flex: 1; }
.pet-chat-messages { flex: 1; overflow-y: auto; padding: 14px 14px 8px; display: flex; flex-direction: column; gap: 12px; }
.pet-chat-messages::-webkit-scrollbar { display: none; }
.pet-chat-msg { display: flex; align-items: flex-end; gap: 8px; }
.pet-chat-msg.user { flex-direction: row-reverse; }
.pet-chat-msg-avatar {
  width: 32px; height: 32px; border-radius: 50%; flex-shrink: 0;
  object-fit: cover; border: 1.5px solid #e0e0e0; background: #f0f0f0;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 800; color: #555; overflow: hidden;
  image-rendering: pixelated;
}
.pet-chat-msg-avatar img { width: 100%; height: 100%; object-fit: contain; image-rendering: pixelated; }
.pet-chat-msg-avatar.char-av img { object-fit: cover; image-rendering: auto; }
.pet-chat-msg-body { max-width: 68%; display: flex; flex-direction: column; gap: 3px; }
.pet-chat-msg.user .pet-chat-msg-body { align-items: flex-end; }
.pet-chat-msg-name { font-size: 9px; color: #aaa; font-weight: 700; letter-spacing: 0.3px; }
.pet-chat-bubble {
  padding: 10px 13px; border-radius: 16px; font-size: 13px; line-height: 1.6; color: #1a1a1a;
  background: #fff; border: 1px solid #ebebeb;
}
.pet-chat-msg.user .pet-chat-bubble { background: #1a1a1a; color: #fff; border-color: #1a1a1a; }
.pet-chat-bubble.loading { color: #bbb; font-style: italic; }
.pet-chat-input-row {
  display: flex; gap: 8px; padding: 10px 14px 14px;
  background: #fff; border-top: 1px solid #ebebeb; flex-shrink: 0;
}
.pet-chat-input {
  flex: 1; padding: 10px 14px; border: 1.5px solid #e0e0e0; border-radius: 20px;
  font-size: 13px; color: #1a1a1a; background: #fafafa; outline: none;
  font-family: inherit;
}
.pet-chat-input:focus { border-color: #1a1a1a; }
.pet-chat-send-btn {
  width: 40px; height: 40px; border-radius: 50%; background: #1a1a1a; border: none;
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 16px; color: #fff;
}
.pet-chat-send-btn:active { background: #333; }
.pet-archive-list { padding: 12px 16px; display: flex; flex-direction: column; gap: 10px; }
.pet-archive-item {
  background: #fff; border-radius: 12px; padding: 12px 14px;
  border: 1px solid #ebebeb; display: flex; align-items: center; gap: 12px;
}
.pet-archive-img {
  width: 44px; height: 44px; object-fit: contain; image-rendering: pixelated;
  flex-shrink: 0;
}
.pet-archive-info { flex: 1; }
.pet-archive-name { font-size: 12px; font-weight: 700; color: #1a1a1a; }
.pet-archive-detail { font-size: 10px; color: #aaa; margin-top: 2px; }
/* Feed/play overlays */
.pet-action-overlay {
  display: none; position: fixed; inset: 0; z-index: 1100;
  background: rgba(0,0,0,0.5); align-items: flex-end; justify-content: center;
}
.pet-action-overlay.open { display: flex; }
.pet-action-sheet {
  background: #fff; border-radius: 20px 20px 0 0;
  padding: 18px 18px 32px; width: 100%; max-width: 420px;
}
.pet-action-sheet-title {
  font-size: 13px; font-weight: 800; color: #1a1a1a;
  margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;
}
.pet-food-grid, .pet-play-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px;
}
.pet-food-item, .pet-play-item {
  display: flex; flex-direction: column; align-items: center; gap: 5px;
  padding: 10px 4px; background: #f7f7f7; border-radius: 12px;
  cursor: pointer; border: 1.5px solid #ebebeb; transition: all 0.15s;
}
.pet-food-item:active, .pet-play-item:active { transform: scale(0.94); background: #f0f0f0; }
.pet-food-item .food-icon, .pet-play-item .play-icon { font-size: 24px; }
.pet-food-item .food-name, .pet-play-item .play-name { font-size: 9px; color: #666; font-weight: 600; }
.pet-sheet-close {
  width: 100%; margin-top: 12px; padding: 11px;
  background: #f5f5f5; border: none; border-radius: 12px;
  font-size: 12px; font-weight: 700; color: #666; cursor: pointer;
}
/* ===== PET TAB DOT ===== */
.pet-tab-dot {
  display: inline-block; width: 5px; height: 5px; background: #ff4d4d;
  border-radius: 50%; margin-left: 3px; vertical-align: super;
}
/* ===== PET TASKS TAB ===== */
