  max-width: calc(100% - 24px);
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(255,250,243,0.9);
  border: 1px solid rgba(64,49,36,0.16);
  color: #43342a;
  text-shadow: none;
  box-shadow: 0 4px 10px rgba(29,21,16,0.08);
}
.decrypt-deduction-grid {
  margin-top: 14px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.decrypt-deduction-card {
  border-radius: 18px;
  padding: 12px;
  background:
    linear-gradient(180deg, rgba(248,243,236,0.96), rgba(228,216,198,0.94)),
    repeating-linear-gradient(0deg, rgba(0,0,0,0.03) 0, rgba(0,0,0,0.03) 1px, transparent 1px, transparent 22px);
  border: 1px solid rgba(43,36,29,0.10);
}
.decrypt-deduction-head {
  font-size: calc(10px * var(--fs,1));
  font-weight: 800;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #7b2a2a;
}
.decrypt-deduction-options {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.decrypt-deduction-option {
  width: 100%;
  text-align: left;
  border: 1px solid rgba(43,36,29,0.12);
  background: rgba(255,255,255,0.72);
  color: #2a221c;
  border-radius: 14px;
  padding: 11px 12px;
  font-size: calc(10px * var(--fs,1));
  line-height: 1.6;
  font-family: inherit;
  cursor: pointer;
  transition: transform 0.16s, border-color 0.16s, background 0.16s, box-shadow 0.16s;
}
.decrypt-deduction-option.active {
  background: rgba(132,22,22,0.10);
  border-color: rgba(132,22,22,0.28);
  box-shadow: 0 0 0 2px rgba(132,22,22,0.08);
}
.decrypt-deduction-option:active {
  transform: scale(0.98);
}
.decrypt-archive-thumb {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 12px 10px;
  box-sizing: border-box;
  background:
    linear-gradient(180deg, rgba(244,238,228,0.98), rgba(224,212,194,0.96)),
    repeating-linear-gradient(0deg, rgba(0,0,0,0.035) 0, rgba(0,0,0,0.035) 1px, transparent 1px, transparent 24px) !important;
}
.decrypt-archive-thumb-state {
  color: rgba(125,40,40,0.86);
  font-size: calc(8px * var(--fs,1));
  font-weight: 800;
  letter-spacing: 1.2px;
  text-transform: uppercase;
}
.decrypt-archive-thumb-name {
  color: #2a221c;
  font-size: calc(12px * var(--fs,1));
  font-weight: 800;
  line-height: 1.45;
}
.decrypt-archive-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px;
}
.decrypt-archive-list {
  grid-template-columns: 1fr;
}
.decrypt-archive-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.decrypt-archive-head {
  display: flex;
  align-items: center;
  gap: 10px;
}
.decrypt-archive-title-row {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.decrypt-archive-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.decrypt-archive-badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(88,60,43,0.08);
  border: 1px solid rgba(88,60,43,0.12);
  color: rgba(42,34,28,0.78);
  font-size: calc(8px * var(--fs,1));
  font-weight: 800;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}
.decrypt-archive-badge.status {
  background: rgba(125,25,25,0.10);
  border-color: rgba(125,25,25,0.14);
  color: #7d1919;
}
.decrypt-archive-summary {
  padding: 10px 11px;
  border-radius: 14px;
  background: rgba(255,255,255,0.58);
  border: 1px dashed rgba(88,60,43,0.14);
  color: rgba(42,34,28,0.82);
  font-size: calc(10px * var(--fs,1));
  line-height: 1.74;
}
.decrypt-archive-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.decrypt-archive-stat {
  padding: 8px 9px;
  border-radius: 12px;
  background: rgba(104,80,61,0.07);
  border: 1px solid rgba(104,80,61,0.08);
}
.decrypt-archive-stat-label {
  font-size: calc(8px * var(--fs,1));
  color: rgba(42,34,28,0.52);
  font-weight: 800;
  letter-spacing: 0.9px;
  text-transform: uppercase;
}
.decrypt-archive-stat-value {
  margin-top: 4px;
  color: #241c17;
  font-size: calc(10px * var(--fs,1));
  font-weight: 800;
  line-height: 1.45;
}
.decrypt-archive-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.decrypt-archive-thumb {
  width: 100%;
  min-height: 122px;
  padding: 14px 14px 12px;
  border-radius: 14px;
  writing-mode: horizontal-tb;
}
.decrypt-archive-thumb-state,
.decrypt-archive-thumb-name,
.decrypt-archive-title,
.decrypt-archive-meta,
.decrypt-archive-summary,
.decrypt-archive-stat-label,
.decrypt-archive-stat-value {
  writing-mode: horizontal-tb;
  text-orientation: mixed;
}
.decrypt-archive-thumb-name {
  word-break: break-word;
  overflow-wrap: anywhere;
}
@media (max-width: 360px) {
  .decrypt-board-hero,
  .decrypt-mood-strip,
  .decrypt-thread-board,
  .decrypt-clue-grid,
  .decrypt-evidence-grid,
  .decrypt-deduction-grid,
  .decrypt-persona-grid,
  .decrypt-archive-list {
    grid-template-columns: 1fr;
  }
  .decrypt-archive-thumb {
    width: 100%;
    min-height: 118px;
  }
  .decrypt-archive-stats {
    grid-template-columns: 1fr;
  }
}
/* ===== TASK APP ICON (same size as music/blackbox) ===== */
.ig-task-icon-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  cursor: pointer;
}
.ig-task-icon-box {
  width: 72px;
  height: 72px;
  border-radius: 16px;
  background: rgba(240,240,240,0.6);
  border: 1px solid rgba(210,210,210,0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(24px * var(--fs, 1));
  color: #555;
  overflow: hidden;
  transition: transform 0.2s;
  backdrop-filter: blur(4px);
}
.ig-task-icon-box:active { transform: scale(0.92); }
.ig-task-icon-box img.custom-icon { width: 100%; height: 100%; object-fit: cover; border-radius: 16px; }
.ig-task-icon-label {
  font-size: calc(9px * var(--fs, 1));
  font-weight: 600;
  color: #444;
  text-align: center;
}
/* ===== TASK APP PAGE ===== */
#taskPage {
  display: none;
  position: absolute;
  inset: 0;
  background: #ffffff;
  flex-direction: column;
  z-index: 200;
  font-family: 'Montserrat', 'DM Mono', sans-serif;
  overflow: hidden;
}
.task-back-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px 8px;
  flex-shrink: 0;
  border-bottom: 1px solid #e0e0e0;
  background: #ffffff;
}
.task-back-btn {
  background: none; border: none; color: #555; font-size: calc(11px * var(--fs,1));
  cursor: pointer; font-family: inherit; letter-spacing: 0.5px;
}
.task-back-btn:active { color: #000; }
.task-page-title {
  font-size: calc(13px * var(--fs,1)); font-weight: 700; color: #1a1a1a;
  letter-spacing: 2px; text-transform: uppercase;
}
.task-header-right {
  display: flex; gap: 8px; align-items: center;
}
.task-history-btn {
  background: none; border: 1px solid #ccc; color: #666; font-size: calc(9px * var(--fs,1));
  padding: 4px 10px; border-radius: 20px; cursor: pointer; font-family: inherit;
  letter-spacing: 0.5px; transition: all 0.2s;
}
.task-history-btn:active { background: #f0f0f0; color: #000; }
/* Character selector */
.task-char-bar {
  display: flex; gap: 10px; padding: 12px 16px; overflow-x: auto;
  flex-shrink: 0; border-bottom: 1px solid #e0e0e0;
  background: #ffffff;
}
.task-char-bar::-webkit-scrollbar { display: none; }
.task-char-pill {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 14px; border-radius: 20px;
  border: 1px solid #ddd; background: #f8f8f8;
  color: #888; font-size: calc(10px * var(--fs,1));
  font-weight: 600; cursor: pointer; white-space: nowrap;
  transition: all 0.2s; flex-shrink: 0;
  letter-spacing: 0.3px;
}
.task-char-pill.active {
  border-color: #222; color: #111; background: #e8e8e8;
}
.task-char-pill img {
  width: 22px; height: 22px; border-radius: 50%;
  object-fit: cover; border: 1px solid #ccc;
}
/* Main content area */
.task-content {
  flex: 1; overflow-y: auto; padding: 16px;
  background: #ffffff;
}
.task-content::-webkit-scrollbar { width: 2px; }
.task-content::-webkit-scrollbar-thumb { background: #ccc; border-radius: 2px; }
/* Date header */
.task-date-header {
  text-align: center; margin-bottom: 20px;
}
.task-date-text {
  font-size: calc(10px * var(--fs,1)); color: #999;
  letter-spacing: 3px; text-transform: uppercase;
  font-weight: 700;
}
.task-date-sub {
  font-size: calc(18px * var(--fs,1)); color: #1a1a1a;
  font-weight: 300; margin-top: 2px;
  letter-spacing: 1px;
  font-family: 'DM Mono', monospace;
}
/* Streak bar */
.task-streak-bar {
  display: flex; align-items: center; justify-content: center;
  gap: 8px; margin-bottom: 20px;
  padding: 10px 16px; border-radius: 12px;
  background: #f5f5f5; border: 1px solid #e0e0e0;
}
.task-streak-icon {
  font-size: calc(14px * var(--fs,1)); color: #555;
}
.task-streak-text {
  font-size: calc(11px * var(--fs,1)); color: #666;
  font-weight: 600; letter-spacing: 0.5px;
}
.task-streak-count {
  color: #111; font-weight: 700;
  font-family: 'DM Mono', monospace;
}
.task-streak-next {
  font-size: calc(9px * var(--fs,1)); color: #999;
  letter-spacing: 0.3px;
}
/* Daily task card */
.task-daily-card {
  background: #fafafa; border: 1px solid #e0e0e0;
  border-radius: 16px; padding: 18px;
  margin-bottom: 16px; position: relative;
  overflow: hidden;
  transition: border-color 0.3s;
}
.task-daily-card::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, #ccc, transparent);
}
.task-daily-card.completed {
  border-color: #bbb;
}
.task-daily-card.completed::before {
  background: linear-gradient(90deg, transparent, #888, transparent);
}
.task-daily-card.locked {
  opacity: 0.45;
  pointer-events: none;
}
.task-card-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 12px;
}
.task-card-tag {
  font-size: calc(8px * var(--fs,1)); font-weight: 700;
  color: #666; background: #f0f0f0;
  padding: 3px 10px; border-radius: 10px;
  letter-spacing: 1.5px; text-transform: uppercase;
  border: 1px solid #ddd;
}
.task-card-status {
  font-size: calc(9px * var(--fs,1)); font-weight: 700;
  letter-spacing: 0.5px;
}
.task-card-status.pending { color: #999; }
.task-card-status.done { color: #333; }
.task-card-status.locked-status { color: #bbb; }
.task-card-title {
  font-size: calc(14px * var(--fs,1)); font-weight: 600;
  color: #1a1a1a; margin-bottom: 8px;
  line-height: 1.5; letter-spacing: 0.3px;
}
.task-card-desc {
  font-size: calc(10px * var(--fs,1)); color: #888;
  line-height: 1.6; margin-bottom: 14px;
  letter-spacing: 0.2px;
}
.task-card-progress {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 14px;
}
.task-progress-bar {
  flex: 1; height: 3px; background: #e0e0e0;
  border-radius: 2px; overflow: hidden;
}
.task-progress-fill {
  height: 100%; background: linear-gradient(90deg, #999, #444);
  border-radius: 2px;
  transition: width 0.5s ease;
}
.task-progress-text {
  font-size: calc(9px * var(--fs,1)); color: #888;
  font-family: 'DM Mono', monospace;
  font-weight: 600; letter-spacing: 0.5px;
  flex-shrink: 0;
}
.task-claim-btn {
  width: 100%; padding: 10px; border: 1px solid #ddd;
  background: #fff; color: #aaa;
  font-size: calc(10px * var(--fs,1)); font-weight: 700;
  letter-spacing: 1.5px; text-transform: uppercase;
  border-radius: 10px; cursor: pointer;
  font-family: inherit;
  transition: all 0.3s;
}
.task-claim-btn:hover { border-color: #999; color: #444; }
.task-claim-btn:active { background: #f0f0f0; }
.task-claim-btn.ready {
  border-color: #333; color: #fff; background: linear-gradient(135deg, #222, #444);
  animation: taskPulse 2s ease infinite;
}
.task-claim-btn.claimed {
  border-color: #e0e0e0; color: #bbb;
  background: #f5f5f5;
  cursor: default; pointer-events: none;
}
@keyframes taskPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(0,0,0,0); }
  50% { box-shadow: 0 0 12px 2px rgba(0,0,0,0.08); }
}
/* Streak milestone section */
.task-streak-section {
  margin-top: 24px; margin-bottom: 16px;
}
.task-section-title {
  font-size: calc(9px * var(--fs,1)); font-weight: 700;
  color: #999; letter-spacing: 2px;
  text-transform: uppercase; margin-bottom: 12px;
  padding-left: 2px;
}
.task-milestone {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 14px; margin-bottom: 8px;
  background: #fafafa; border: 1px solid #e8e8e8;
  border-radius: 12px;
  transition: all 0.3s;
}
.task-milestone.unlocked {
  border-color: #bbb; background: #f0f0f0;
}
.task-milestone-icon {
  width: 32px; height: 32px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: calc(12px * var(--fs,1));
  background: #fff; border: 1px solid #ddd;
  color: #bbb;
  flex-shrink: 0;
}
.task-milestone.unlocked .task-milestone-icon {
  background: #e8e8e8; color: #444;
  border-color: #999;
}
.task-milestone-info { flex: 1; min-width: 0; }
.task-milestone-label {
  font-size: calc(10px * var(--fs,1)); font-weight: 700;
  color: #888; letter-spacing: 0.3px;
}
.task-milestone.unlocked .task-milestone-label { color: #222; }
.task-milestone-sub {
  font-size: calc(9px * var(--fs,1)); color: #bbb;
  margin-top: 2px; letter-spacing: 0.2px;
}
.task-milestone.unlocked .task-milestone-sub { color: #777; }
.task-milestone-badge {
  font-size: calc(8px * var(--fs,1)); font-weight: 700;
  padding: 3px 8px; border-radius: 8px;
  letter-spacing: 0.5px; text-transform: uppercase;
  flex-shrink: 0;
}
.task-milestone-badge.locked {
  background: #f5f5f5; color: #bbb; border: 1px solid #e0e0e0;
}
.task-milestone-badge.unlocked {
  background: #e8e8e8; color: #444; border: 1px solid #aaa;
}
/* Reward history section */
.task-reward-list {
  margin-top: 16px;
}
.task-reward-item {
  padding: 14px; margin-bottom: 10px;
  background: #fafafa; border: 1px solid #e8e8e8;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s;
}
.task-reward-item:hover {
  background: #f0f0f0;
}
.task-reward-item.pending {
  border: 1px dashed #e0c080;
  background: #fffdf5;
  position: relative;
}
.task-reward-item.pending::after {
  content: '待生成';
  position: absolute; top: 8px; right: 8px;
  font-size: 9px; color: #c9a040;
  background: #fff8e8; border: 1px solid #e8d8a0;
  padding: 1px 6px; border-radius: 6px;
  font-weight: 600; letter-spacing: 0.5px;
}
.task-reward-item-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 8px;
}
.task-reward-item-cat {
  font-size: calc(8px * var(--fs,1)); font-weight: 700;
  color: #666; background: #f0f0f0;
  padding: 2px 8px; border-radius: 8px;
  letter-spacing: 1px; text-transform: uppercase;
  border: 1px solid #ddd;
}
.task-reward-item-date {
  font-size: calc(9px * var(--fs,1)); color: #999;
  font-family: 'DM Mono', monospace;
}
.task-reward-item-content {
  font-size: calc(10px * var(--fs,1)); color: #333;
  line-height: 1.7; letter-spacing: 0.2px;
}
.task-reward-item-char {
  font-size: calc(9px * var(--fs,1)); color: #888;
  margin-top: 6px; font-style: italic;
}
/* Reward popup (otome game style) */
.task-reward-overlay {
  display: none; position: fixed;
  inset: 0; z-index: 9999;
  background: rgba(0,0,0,0.4);
  align-items: center; justify-content: center;
  backdrop-filter: blur(8px);
}
.task-reward-overlay.open { display: flex; }
.task-reward-popup {
  width: 92%; max-width: 380px;
  background: #fff; border: 1px solid #ddd;
  border-radius: 22px; padding: 0;
  text-align: center; position: relative;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(0,0,0,0.15);
  animation: taskRewardIn 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes taskRewardIn {
  0% { opacity: 0; transform: scale(0.85) translateY(30px); }
  100% { opacity: 1; transform: scale(1) translateY(0); }
}
.task-reward-popup::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, transparent, #bbb, #666, #bbb, transparent);
}
.task-reward-popup-header {
  padding: 24px 22px 0;
  position: relative;
}
.task-reward-popup-header::after {
  content: '';
  display: block;
  width: 40px; height: 1px;
  background: #ddd;
  margin: 14px auto 0;
}
.task-reward-popup-icon {
  font-size: 28px; margin-bottom: 10px;
  display: block;
  animation: rewardIconPulse 2s ease-in-out infinite;
}
@keyframes rewardIconPulse {
  0%, 100% { transform: scale(1); opacity: 0.8; }
  50% { transform: scale(1.1); opacity: 1; }
}
.task-reward-popup-title {
  font-size: calc(13px * var(--fs,1)); font-weight: 700;
  color: #333; letter-spacing: 0.5px;
  margin-bottom: 4px;
  line-height: 1.5;
}
.task-reward-popup-cat {
  font-size: calc(9px * var(--fs,1)); font-weight: 600;
  color: #888; letter-spacing: 1.5px;
  margin-bottom: 0; padding: 3px 10px;
  display: inline-block;
  border: 1px solid #e0e0e0; border-radius: 20px;
  background: #f8f8f8;
  text-transform: uppercase;
}
.task-reward-popup-body {
  padding: 18px 22px;
  max-height: 50vh;
  overflow-y: auto;
}
.task-reward-popup-content {
  font-size: calc(12px * var(--fs,1)); color: #333;
  line-height: 1.9; margin: 0 0 14px;
  letter-spacing: 0.3px; min-height: 60px;
  padding: 0 2px;
  text-align: left;
}
.task-reward-popup-content .reward-quote {
  display: block;
  background: #f9f9f9;
  border-left: 3px solid #ccc;
  padding: 10px 14px;
  margin: 10px 0;
  border-radius: 0 10px 10px 0;
  font-style: italic;
  color: #444;
  line-height: 1.8;
}
.task-reward-popup-content .reward-scene {
  display: block;
  color: #888;
  font-size: calc(10px * var(--fs,1));
  margin-bottom: 8px;
  font-style: italic;
}
.task-reward-popup-content .reward-action {
  display: block;
  color: #666;
  font-size: calc(10px * var(--fs,1));
  margin: 6px 0;
  padding-left: 8px;
  border-left: 2px solid #e0e0e0;
}
.task-reward-popup-content .reward-whisper {
  display: block;
  text-align: center;
  color: #555;
  font-size: calc(11px * var(--fs,1));
  margin: 10px 0 4px;
  letter-spacing: 0.5px;
}
.task-reward-popup-content .reward-heart {
  display: block;
  text-align: center;
  color: #ccc;
  font-size: 10px;
  margin: 8px 0;
  letter-spacing: 4px;
}
.task-reward-popup-content .reward-list {
  list-style: none;
  padding: 0; margin: 8px 0;
}
.task-reward-popup-content .reward-list li {
  padding: 4px 0 4px 16px;
  position: relative;
  font-size: calc(11px * var(--fs,1));
  color: #444;
}
.task-reward-popup-content .reward-list li::before {
  content: '·';
  position: absolute; left: 4px;
  color: #aaa; font-weight: bold;
}
.task-reward-popup-char {
