}
.task-reward-popup-error i {
  display: block; font-size: 22px; margin-bottom: 8px; color: #d08070;
}
.task-reward-popup-retry {
  background: #f5f5f5; border: 1px solid #ddd;
  color: #555; padding: 8px 24px;
  font-size: calc(10px * var(--fs,1)); font-weight: 600;
  letter-spacing: 1px;
  border-radius: 10px; cursor: pointer;
  font-family: inherit;
  transition: all 0.2s;
  margin-top: 8px;
}
.task-reward-popup-retry:hover { background: #eee; border-color: #ccc; }
.task-reward-popup-save {
  background: #222; border: 1px solid #333;
  color: #fff; padding: 11px 36px;
  font-size: calc(10px * var(--fs,1)); font-weight: 700;
  letter-spacing: 1.5px; text-transform: uppercase;
  border-radius: 12px; cursor: pointer;
  font-family: inherit;
  transition: all 0.2s;
  width: 100%; max-width: 200px;
}
.task-reward-popup-save:hover { border-color: #000; color: #fff; background: #000; }
.task-reward-popup-regen {
  background: transparent; border: 1px solid #ccc;
  color: #666; padding: 8px 24px;
  font-size: calc(10px * var(--fs,1)); font-weight: 600;
  letter-spacing: 1px;
  border-radius: 10px; cursor: pointer;
  font-family: inherit;
  transition: all 0.2s;
  width: 100%; max-width: 200px;
}
.task-reward-popup-regen:hover { background: #f5f5f5; border-color: #999; color: #333; }
.task-reward-popup-delete {
  background: #fff7f7; border: 1px solid #efcaca;
  color: #c45a5a; padding: 8px 24px;
  font-size: calc(10px * var(--fs,1)); font-weight: 600;
  letter-spacing: 1px;
  border-radius: 10px; cursor: pointer;
  font-family: inherit;
  transition: all 0.2s;
  width: 100%; max-width: 200px;
}
.task-reward-popup-delete:hover { background: #fff0f0; border-color: #e8a9a9; color: #b24848; }
/* Character select modal for non-chat tasks */
.task-char-select-overlay {
  display: none; position: fixed;
  inset: 0; z-index: 9998;
  background: rgba(0,0,0,0.4);
  align-items: center; justify-content: center;
}
.task-char-select-overlay.open { display: flex; }
.task-char-select-box {
  width: 85%; max-width: 300px;
  background: #fff; border: 1px solid #ddd;
  border-radius: 16px; padding: 20px;
  box-shadow: 0 8px 30px rgba(0,0,0,0.12);
}
.task-char-select-title {
  font-size: calc(10px * var(--fs,1)); font-weight: 700;
  color: #666; letter-spacing: 2px;
  text-transform: uppercase; margin-bottom: 14px;
  text-align: center;
}
.task-char-select-list {
  display: flex; flex-direction: column; gap: 8px;
  max-height: 250px; overflow-y: auto;
}
.task-char-select-item {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: 10px;
  border: 1px solid #e0e0e0; background: #fafafa;
