}
.task-char-select-item:hover { border-color: #999; }
.task-char-select-item:active { background: #f0f0f0; }
.task-char-select-item img {
  width: 32px; height: 32px; border-radius: 50%;
  object-fit: cover; border: 1px solid #ccc;
}
.task-char-select-item-name {
  font-size: calc(11px * var(--fs,1)); font-weight: 600;
  color: #222; letter-spacing: 0.3px;
}
.task-char-select-cancel {
  margin-top: 12px; width: 100%; padding: 8px;
  background: none; border: 1px solid #ddd; color: #888;
  font-size: calc(9px * var(--fs,1)); font-weight: 700;
  letter-spacing: 1px; text-transform: uppercase;
  border-radius: 8px; cursor: pointer; font-family: inherit;
}
/* History modal */
.task-history-overlay {
  display: none; position: absolute;
  inset: 0; z-index: 210;
  background: #ffffff;
  flex-direction: column;
}
.task-history-overlay.open { display: flex; }
.task-history-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 16px 8px;
  border-bottom: 1px solid #e0e0e0;
}
.task-history-title {
  font-size: calc(12px * var(--fs,1)); font-weight: 700;
  color: #222; letter-spacing: 1.5px; text-transform: uppercase;
}
.task-history-close {
  background: none; border: none; color: #999;
  font-size: 16px; cursor: pointer;
}
.task-history-body {
  flex: 1; overflow-y: auto; padding: 16px;
}
.task-history-body::-webkit-scrollbar { width: 2px; }
.task-history-body::-webkit-scrollbar-thumb { background: #ccc; }
.task-history-empty {
  text-align: center; color: #999;
  font-size: calc(11px * var(--fs,1));
  padding: 40px 0; letter-spacing: 0.5px;
}
/* No character state */
.task-empty-state {
  text-align: center; padding: 60px 20px;
  color: #999;
}
.task-empty-state i {
  font-size: 36px; display: block;
  margin-bottom: 14px; color: #ccc;
}
.task-empty-state-text {
  font-size: calc(11px * var(--fs,1));
  letter-spacing: 0.5px;
}
/* ===== VOICE CALL FEATURE ===== */
/* Call button in headers */
.call-header-btn {
  background: none; border: none; cursor: pointer; padding: 6px;
  color: #1a1a1a; font-size: 17px; display: flex; align-items: center;
  justify-content: center; border-radius: 50%; transition: background 0.15s;
}
.call-header-btn:hover { background: rgba(0,0,0,0.06); }
.dating-call-header-btn {
  background: none; border: none; cursor: pointer; padding: 6px;
  color: #555; font-size: 17px; display: flex; align-items: center;
  justify-content: center; border-radius: 50%; transition: background 0.15s;
}
.dating-call-header-btn:hover { background: rgba(0,0,0,0.06); }
/* iPhone-style full-screen call overlay */
#voiceCallScreen {
  display: none;
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  z-index: 9999;
  flex-direction: column;
  align-items: center;
  background: linear-gradient(180deg, #1c1c1e 0%, #2c2c2e 100%);
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', sans-serif;
  color: #fff;
  padding: env(safe-area-inset-top, 44px) 0 env(safe-area-inset-bottom, 34px);
}
#voiceCallScreen.active { display: flex; }
.call-screen-top {
  display: flex; flex-direction: column; align-items: center;
  padding-top: 60px; flex: 1;
}
.call-screen-avatar {
  width: 96px; height: 96px; border-radius: 50%;
  overflow: hidden; margin-bottom: 16px;
  background: #48484a; display: flex; align-items: center; justify-content: center;
  font-size: 40px; color: #aeaeb2;
  box-shadow: 0 4px 20px rgba(0,0,0,0.4);
}
.call-screen-avatar img { width: 100%; height: 100%; object-fit: cover; }
.call-screen-name {
  font-size: 28px; font-weight: 600; letter-spacing: -0.5px; margin-bottom: 6px;
}
.call-screen-status {
  font-size: 14px; color: #aeaeb2; margin-bottom: 0;
}
.call-timer {
  font-size: 14px; color: #aeaeb2; font-variant-numeric: tabular-nums; margin-top: 4px;
}
/* In-call chat area */
.call-chat-area {
  width: 100%; max-width: 380px; flex: 1; overflow-y: auto;
  padding: 12px 16px; display: flex; flex-direction: column; gap: 8px;
}
.call-chat-area::-webkit-scrollbar { display: none; }
.call-msg-user {
  align-self: flex-end; background: rgba(255,255,255,0.12); border-radius: 16px 16px 4px 16px;
  padding: 8px 12px; max-width: 70%; font-size: 14px; color: #fff; line-height: 1.4;
}
.call-msg-ai {
  align-self: flex-start; background: rgba(255,255,255,0.18); border-radius: 16px 16px 16px 4px;
  padding: 8px 12px; max-width: 70%; font-size: 14px; color: #fff; line-height: 1.4;
}
.call-msg-main-text { line-height: 1.5; }
.call-msg-translation {
  margin-top: 6px; padding-top: 6px;
  border-top: 1px solid rgba(255,255,255,0.18);
  display: flex; flex-direction: column; gap: 2px;
}
.call-msg-tr-label {
  font-size: 9px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase;
  color: rgba(255,255,255,0.38); font-family: 'DM Mono', monospace; display: block;
}
.call-msg-tr-text {
  font-size: 12px; color: rgba(255,255,255,0.6); font-style: italic; line-height: 1.5;
}
.call-msg-typing {
  align-self: flex-start; background: rgba(255,255,255,0.12); border-radius: 16px;
  padding: 8px 16px; font-size: 20px; color: rgba(255,255,255,0.6); letter-spacing: 3px;
}
/* Input bar */
.call-input-bar {
  width: 100%; max-width: 380px; display: flex; align-items: center; gap: 10px;
  padding: 10px 16px; background: rgba(255,255,255,0.06); border-radius: 16px;
  margin: 0 16px 12px; box-sizing: border-box;
}
.call-input-bar input {
  flex: 1; background: none; border: none; outline: none; color: #fff;
  font-size: 15px; font-family: inherit; placeholder-color: #aeaeb2;
}
.call-input-bar input::placeholder { color: #636366; }
.call-send-btn {
  background: #fff; border: none; border-radius: 50%; width: 30px; height: 30px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; color: #1c1c1e; font-size: 13px; flex-shrink: 0;
}
/* Call controls bottom row */
.call-controls {
  display: flex; align-items: center; justify-content: center; gap: 32px;
  padding: 20px 0 8px; width: 100%;
}
.call-ctrl-btn {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  background: rgba(255,255,255,0.12); border: none; border-radius: 50%;
  width: 64px; height: 64px; cursor: pointer; color: #fff; font-size: 22px;
  transition: background 0.15s;
}
.call-ctrl-btn:active { background: rgba(255,255,255,0.2); }
.call-end-btn {
  background: #ff3b30; border: none; border-radius: 50%;
  width: 72px; height: 72px; display: flex; align-items: center; justify-content: center;
  cursor: pointer; color: #fff; font-size: 26px;
  box-shadow: 0 4px 16px rgba(255,59,48,0.4);
  transition: transform 0.1s;
}
.call-end-btn:active { transform: scale(0.92); }
/* Call bubble in chat history */
.bubble-call {
  background: #f0f0f0; border-radius: 12px; padding: 10px 14px;
  display: inline-flex; align-items: center; gap: 10px;
  font-size: 13px; max-width: 220px; color: #1a1a1a;
  cursor: pointer; user-select: none;
}
.bubble-call:active { opacity: 0.7; }
.bubble-call i { font-size: 16px; color: #34c759; }
.bubble-call-declined { background: #f0f0f0; }
.bubble-call-declined i { color: #ff3b30; }
.bubble-call .call-duration { font-size: 11px; color: #888; margin-top: 1px; }
.bubble-call .call-view-hint { font-size: 10px; color: #aaa; margin-top: 2px; }
.wechat-style .bubble-call { background: #fff; border: 1px solid #e0e0e0; }
/* Call log modal */
#callLogModal {
  display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  z-index: 10200; background: rgba(0,0,0,0.55); align-items: center; justify-content: center;
}
#callLogModal.active { display: flex; }
#callLogModalBox {
  background: #1c1c1e; border-radius: 18px; width: 320px; max-height: 80vh;
  display: flex; flex-direction: column; overflow: hidden; color: #fff;
}
#callLogModalHeader {
  padding: 16px 18px 10px; display: flex; align-items: center; justify-content: space-between;
  border-bottom: 1px solid #2c2c2e;
}
#callLogModalTitle { font-size: 15px; font-weight: 600; }
#callLogModalClose {
  background: none; border: none; color: #aaa; font-size: 20px; cursor: pointer; padding: 0 4px;
}
#callLogModalMeta { padding: 10px 18px 8px; font-size: 12px; color: #8e8e93; border-bottom: 1px solid #2c2c2e; }
#callLogModalBody {
  flex: 1; overflow-y: auto; padding: 12px 14px; display: flex; flex-direction: column; gap: 8px;
}
.calllog-msg-user {
  align-self: flex-end; background: #0a84ff; color: #fff;
  border-radius: 14px 14px 4px 14px; padding: 8px 12px; font-size: 13px; max-width: 80%;
}
.calllog-msg-ai {
  align-self: flex-start; background: #3a3a3c; color: #fff;
  border-radius: 14px 14px 14px 4px; padding: 8px 12px; font-size: 13px; max-width: 80%;
}
.calllog-empty { color: #636366; font-size: 13px; text-align: center; margin: 20px 0; }
/* Incoming call from character */
#charIncomingCallScreen {
  display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  z-index: 9998; flex-direction: column; align-items: center; justify-content: space-between;
  background: linear-gradient(180deg, #1c1c1e 0%, #2c2c2e 100%);
  color: #fff; padding: 80px 0 60px;
}
#charIncomingCallScreen.active { display: flex; }
#charIncomingRinging { font-size: 13px; color: #aeaeb2; animation: charRingPulse 1.4s infinite; }
@keyframes charRingPulse { 0%,100%{opacity:1} 50%{opacity:0.4} }
/* Incoming call screen */
#incomingCallScreen {
  display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  z-index: 9999; flex-direction: column; align-items: center; justify-content: space-between;
  background: linear-gradient(180deg, #1c1c1e 0%, #2c2c2e 100%);
  color: #fff; padding: 80px 0 60px;
}
#incomingCallScreen.active { display: flex; }
.incoming-call-top { display: flex; flex-direction: column; align-items: center; gap: 14px; }
.incoming-call-label { font-size: 13px; color: #aeaeb2; }
.incoming-call-avatar {
  width: 96px; height: 96px; border-radius: 50%; overflow: hidden;
  background: #48484a; display: flex; align-items: center; justify-content: center;
  font-size: 40px; color: #aeaeb2;
}
.incoming-call-avatar img { width: 100%; height: 100%; object-fit: cover; }
.incoming-call-name { font-size: 28px; font-weight: 600; }
.incoming-call-buttons { display: flex; gap: 48px; align-items: center; }
.incoming-decline-btn {
  width: 72px; height: 72px; border-radius: 50%; background: #ff3b30;
  border: none; color: #fff; font-size: 28px; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
}
.incoming-accept-btn {
  width: 72px; height: 72px; border-radius: 50%; background: #34c759;
  border: none; color: #fff; font-size: 28px; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
}
/* ═══════════════════════════════════════════════════════
   线下模式 OFFLINE MODE — 韩系黑白灰精致风格
   ═══════════════════════════════════════════════════════ */
/* Offline Mode Themes */
#offlinePage { --off-bg: #0a0a0a; --off-bg2: #0d0d0d; --off-border: #181818; --off-border2: #1e1e1e; --off-text: #d0d0d0; --off-text2: #767676; --off-text3: #383838; --off-text4: #282828; --off-dot: #e8e8e8; --off-bubble: #111111; --off-bubble-user: #1c1c1c; --off-bubble-border: #1e1e1e; --off-bubble-user-border: #2a2a2a; --off-input-bg: #0e0e0e; --off-input-border: #1e1e1e; --off-send-bg: #e8e8e8; --off-send-icon: #0a0a0a; --off-meta: #545454; --off-time: #2e2e2e; --off-tab-sel: #e0e0e0; --off-tab-unsel: #383838; --off-empty-icon: #1c1c1c; --off-empty-title: #383838; --off-scenebreak: #2a2a2a; --off-accent: #c8c8c8; --off-divider: rgba(255,255,255,0.04); }
#offlinePage.theme-white { --off-bg: #fdfdfd; --off-bg2: #f7f7f7; --off-border: #ebebeb; --off-border2: #e4e4e4; --off-text: #1a1a1a; --off-text2: #888; --off-text3: #c0c0c0; --off-text4: #d4d4d4; --off-dot: #1a1a1a; --off-bubble: #f2f2f2; --off-bubble-user: #1a1a1a; --off-bubble-border: #e8e8e8; --off-bubble-user-border: #1a1a1a; --off-input-bg: #f2f2f2; --off-input-border: #e4e4e4; --off-send-bg: #1a1a1a; --off-send-icon: #ffffff; --off-meta: #aaa; --off-time: #ccc; --off-tab-sel: #1a1a1a; --off-tab-unsel: #c4c4c4; --off-empty-icon: #e0e0e0; --off-empty-title: #c8c8c8; --off-scenebreak: #ddd; --off-accent: #555; --off-divider: rgba(0,0,0,0.04); }
#offlinePage.theme-cream { --off-bg: #f6f1e9; --off-bg2: #f0ebe1; --off-border: #e4ddd2; --off-border2: #ddd5c8; --off-text: #2e2a22; --off-text2: #8a7e70; --off-text3: #bcb4a8; --off-text4: #cec8bc; --off-dot: #2e2a22; --off-bubble: #ede8df; --off-bubble-user: #2e2a22; --off-bubble-border: #e0d8ce; --off-bubble-user-border: #2e2a22; --off-input-bg: #ede8df; --off-input-border: #ddd5c8; --off-send-bg: #2e2a22; --off-send-icon: #f6f1e9; --off-meta: #a09488; --off-time: #cec8bc; --off-tab-sel: #2e2a22; --off-tab-unsel: #bcb4a8; --off-empty-icon: #d8d0c4; --off-empty-title: #bcb4a8; --off-scenebreak: #cec8bc; --off-accent: #6a5e50; --off-divider: rgba(0,0,0,0.03); }
#offlinePage.theme-navy { --off-bg: #0c1320; --off-bg2: #101828; --off-border: #192032; --off-border2: #1e2838; --off-text: #c4d0e8; --off-text2: #6878a4; --off-text3: #2e3c56; --off-text4: #243050; --off-dot: #8898c8; --off-bubble: #111c2e; --off-bubble-user: #1c2e48; --off-bubble-border: #1a2838; --off-bubble-user-border: #283e5c; --off-input-bg: #0c1828; --off-input-border: #1a2838; --off-send-bg: #c4d0e8; --off-send-icon: #0c1320; --off-meta: #485880; --off-time: #243050; --off-tab-sel: #c4d0e8; --off-tab-unsel: #2e3c56; --off-empty-icon: #1a2838; --off-empty-title: #2e3c56; --off-scenebreak: #243050; --off-accent: #8898c8; --off-divider: rgba(255,255,255,0.03); }
#offlinePage {
  display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  z-index: 1500; background: var(--off-bg); flex-direction: column;
  font-family: 'Noto Sans TC', 'Apple SD Gothic Neo', -apple-system, sans-serif;
}
#offlinePage.active { display: flex; animation: offlinePageIn 0.4s cubic-bezier(0.16,1,0.3,1); }
@keyframes offlinePageIn {
  from { opacity: 0; transform: translateY(24px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
/* ── Header ── */
.offline-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 20px 12px; border-bottom: 1px solid var(--off-border); flex-shrink: 0;
  background: var(--off-bg);
}
.offline-header-left { display: flex; align-items: center; gap: 14px; }
.offline-back-btn {
  background: none; border: none; color: var(--off-text2); font-size: 17px;
  cursor: pointer; padding: 6px; opacity: 0.7; transition: opacity 0.15s;
}
.offline-back-btn:hover { opacity: 1; }
.offline-mode-badge { display: flex; align-items: center; gap: 7px; }
.offline-mode-dot {
  width: 5px; height: 5px; border-radius: 50%; background: var(--off-dot);
  animation: offlinePulse 2.5s ease-in-out infinite;
}
@keyframes offlinePulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.25;transform:scale(0.7)} }
@keyframes offline回复Pulse { 0%{transform:scale(1)} 40%{transform:scale(1.18)} 100%{transform:scale(1)} }
.offline-mode-label {
  font-size: 9px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase;
  color: var(--off-text2); font-family: 'DM Mono', monospace;
}
.offline-char-name {
  font-size: 14px; font-weight: 500; color: var(--off-text); letter-spacing: 0.2px;
}
.offline-header-actions { display: flex; gap: 8px; align-items: center; }
.offline-action-btn {
  background: none; border: 1px solid var(--off-border2); border-radius: 20px;
  color: var(--off-text2); font-size: 9px; font-weight: 700; letter-spacing: 1.5px;
  text-transform: uppercase; padding: 6px 13px; cursor: pointer; font-family: 'DM Mono', monospace;
  transition: all 0.2s;
}
.offline-action-btn:hover { border-color: var(--off-text2); color: var(--off-text); }
.offline-action-btn i { font-size: 9px; }
/* ── Mode tabs ── */
.offline-mode-tabs {
  display: flex; border-bottom: 1px solid var(--off-border); flex-shrink: 0;
  background: var(--off-bg);
}
.offline-mode-tab {
  flex: 1; padding: 11px 0 10px; font-size: 9px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase; text-align: center;
  color: var(--off-tab-unsel); cursor: pointer; border-bottom: 1.5px solid transparent;
  transition: all 0.22s; font-family: 'DM Mono', monospace;
}
.offline-mode-tab.selected { color: var(--off-tab-sel); border-bottom-color: var(--off-tab-sel); }
/* ── Scroll ── */
.offline-scroll { flex: 1; overflow-y: auto; background: var(--off-bg); }
.offline-scroll::-webkit-scrollbar { display: none; }
/* ══ LONG NARRATIVE ENTRY ══ */
.offline-entry {
  padding: 32px 24px 28px;
  border-bottom: 1px solid var(--off-divider);
  animation: offlineEntryIn 0.5s cubic-bezier(0.16,1,0.3,1);
}
.offline-entry:last-child { border-bottom: none; }
@keyframes offlineEntryIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
.offline-entry.user-entry {
  background: var(--off-divider);
  border-left: 2px solid var(--off-border2);
  padding-left: 22px;
}
/* Entry header row */
.offline-entry-meta {
  display: flex; align-items: center; gap: 9px; margin-bottom: 18px;
}
.offline-entry-avatar {
  width: 24px; height: 24px; border-radius: 50%; object-fit: cover; flex-shrink: 0;
  border: 1px solid var(--off-border2); opacity: 0.9;
}
.offline-entry-author {
  font-size: 9px; font-weight: 700; letter-spacing: 2.5px; text-transform: uppercase;
  color: var(--off-meta); font-family: 'DM Mono', monospace;
}
.offline-entry-divider {
  width: 1px; height: 10px; background: var(--off-border2); flex-shrink: 0;
}
.offline-entry-time {
  font-size: 9px; color: var(--off-time); font-family: 'DM Mono', monospace; margin-left: auto;
}
/* Narrative text */
.offline-narrative {
  font-size: 14.5px; line-height: 2.1; color: var(--off-text);
  letter-spacing: 0.15px; word-spacing: 1px;
}
.offline-narrative em {
  color: var(--off-text2); font-style: italic; font-size: 13px; letter-spacing: 0.3px;
  font-family: Georgia, 'Times New Roman', serif;
}
.offline-narrative strong { color: var(--off-accent); font-weight: 600; }
.offline-narrative .scene-break {
  display: block; text-align: center; color: var(--off-scenebreak);
  letter-spacing: 8px; font-size: 9px; margin: 24px 0; font-family: 'DM Mono', monospace;
  opacity: 0.6;
}
.offline-narrative .bgm-tag {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 8.5px; letter-spacing: 2px; color: var(--off-text2);
  font-family: 'DM Mono', monospace; margin-bottom: 18px;
  padding: 5px 12px; border: 1px solid var(--off-border2); border-radius: 20px;
  opacity: 0.8;
}
.offline-narrative .bgm-tag i { font-size: 7px; opacity: 0.7; }
/* ══ SHORT MODE ══ */
.offline-short-row {
  padding: 10px 20px;
  display: flex; flex-direction: column;
  animation: offlineEntryIn 0.4s cubic-bezier(0.16,1,0.3,1);
}
.offline-short-row.char-row { align-items: flex-start; }
.offline-short-row.user-row { align-items: flex-end; }
.offline-short-meta {
  display: flex; align-items: center; gap: 7px; margin-bottom: 7px;
}
.offline-short-meta img {
  width: 22px; height: 22px; border-radius: 50%; object-fit: cover;
  border: 1px solid var(--off-border2);
}
.offline-short-meta-name {
  font-size: 9px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase;
  color: var(--off-meta); font-family: 'DM Mono', monospace;
}
.offline-short-bubble {
  background: var(--off-bubble); border: 1px solid var(--off-bubble-border);
  border-radius: 14px 14px 14px 4px;
  padding: 12px 15px; max-width: 82%;
  font-size: 14px; line-height: 1.65; color: var(--off-text);
  position: relative;
}
.offline-short-bubble.user-bubble {
  background: var(--off-bubble-user); border-color: var(--off-bubble-user-border);
  color: var(--off-send-icon); border-radius: 14px 14px 4px 14px;
}
.offline-short-time {
  font-size: 8.5px; color: var(--off-time); font-family: 'DM Mono', monospace;
  margin-top: 5px; letter-spacing: 0.5px;
}
.offline-location-pill {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 8.5px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase;
  color: var(--off-text3); font-family: 'DM Mono', monospace;
  padding: 4px 10px; border: 1px solid var(--off-border2); border-radius: 20px;
  margin-bottom: 10px;
}
.offline-location-pill i { font-size: 7px; }
/* ── Input ── */
.offline-input-area {
  border-top: 1px solid var(--off-border); padding: 12px 16px 20px;
  background: var(--off-bg); flex-shrink: 0;
}
.offline-input-row { display: flex; gap: 10px; align-items: flex-end; }
.offline-textarea {
  flex: 1; background: var(--off-input-bg); border: 1px solid var(--off-input-border);
  border-radius: 12px; color: var(--off-text); font-size: 13.5px; line-height: 1.55;
  padding: 11px 15px; resize: none; outline: none; font-family: inherit;
  min-height: 44px; max-height: 130px; transition: border-color 0.2s;
}
.offline-textarea:focus { border-color: var(--off-text2); }
.offline-textarea::placeholder { color: var(--off-text3); }
.offline-send-btn {
  width: 42px; height: 42px; border-radius: 50%; background: var(--off-send-bg);
  border: none; cursor: pointer; display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; transition: all 0.18s;
}
.offline-send-btn:active { transform: scale(0.9); opacity: 0.8; }
.offline-send-btn i { font-size: 14px; color: var(--off-send-icon); }
.offline-send-btn.generating { background: var(--off-border2); cursor: not-allowed; }
.offline-send-btn.generating i { color: var(--off-text3); }
.offline-reply-btn {
  width: 40px; height: 40px; border-radius: 50%; background: none;
  border: 1px solid var(--off-border2); display: flex; align-items: center;
  justify-content: center; cursor: pointer; flex-shrink: 0; transition: all 0.2s;
  color: var(--off-accent);
}
.offline-reply-btn:hover { border-color: var(--off-accent); background: var(--off-divider); }
.offline-reply-btn:active { transform: scale(0.9); }
.offline-reply-btn.generating { opacity: 0.35; cursor: not-allowed; }
.offline-reply-btn i { font-size: 15px; }
.offline-input-hint {
  font-size: 8px; color: var(--off-text4); letter-spacing: 1.5px; text-transform: uppercase;
  text-align: center; margin-top: 9px; font-family: 'DM Mono', monospace;
}
/* ── Typing ── */
.offline-typing {
  padding: 18px 24px; display: flex; align-items: center; gap: 10px;
}
.offline-typing-dots { display: flex; gap: 5px; }
.offline-typing-dots span {
  width: 4px; height: 4px; border-radius: 50%; background: var(--off-text3);
  animation: offlineDot 1.4s ease-in-out infinite;
}
.offline-typing-dots span:nth-child(2) { animation-delay: 0.25s; }
.offline-typing-dots span:nth-child(3) { animation-delay: 0.5s; }
@keyframes offlineDot {
  0%,70%,100%{transform:scale(1);opacity:0.35} 35%{transform:scale(1.4);opacity:1}
}
.offline-typing-label {
  font-size: 8.5px; color: var(--off-text3); letter-spacing: 2px;
  text-transform: uppercase; font-family: 'DM Mono', monospace;
}
/* ── Empty state ── */
.offline-empty {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 80px 32px; text-align: center; gap: 16px; height: 100%;
}
.offline-empty-icon { font-size: 24px; color: var(--off-empty-icon); margin-bottom: 4px; }
.offline-empty-title {
  font-size: 10px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase;
  color: var(--off-empty-title); font-family: 'DM Mono', monospace;
}
.offline-empty-desc {
  font-size: 12px; color: var(--off-text3); line-height: 1.8;
  max-width: 200px; word-break: keep-all;
}
/* ── Settings ── */
.offline-setting-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 15px 20px; border-bottom: 1px solid var(--off-border); cursor: pointer;
  transition: background 0.15s;
}
.offline-setting-row:hover { background: var(--off-divider); }
.offline-setting-label { font-size: 12.5px; color: var(--off-text); letter-spacing: 0.2px; }
.offline-setting-value { font-size: 10px; color: var(--off-text2); font-family: 'DM Mono', monospace; letter-spacing: 0.5px; margin-top: 3px; }
.offline-toggle {
  width: 38px; height: 22px; border-radius: 11px; background: var(--off-border2);
  position: relative; cursor: pointer; transition: background 0.25s; flex-shrink: 0;
}
.offline-toggle.on { background: var(--off-dot); }
.offline-toggle::after {
  content: ''; position: absolute; top: 3px; left: 3px;
  width: 16px; height: 16px; border-radius: 50%; background: var(--off-text3);
  transition: all 0.25s cubic-bezier(0.4,0,0.2,1);
}
.offline-toggle.on::after { left: 19px; background: var(--off-bg); }
/* ── Archive ── */
.offline-archive-item {
  padding: 17px 20px; border-bottom: 1px solid var(--off-border);
  cursor: pointer; transition: background 0.15s;
}
.offline-archive-item:hover { background: var(--off-divider); }
.offline-archive-title { font-size: 13px; font-weight: 500; color: var(--off-text); margin-bottom: 5px; letter-spacing: 0.2px; }
.offline-archive-meta {
  font-size: 9px; color: var(--off-text3); font-family: 'DM Mono', monospace;
  letter-spacing: 1px; text-transform: uppercase;
}
.offline-archive-preview { font-size: 11.5px; color: var(--off-text2); margin-top: 7px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; line-height: 1.5; }
/* ── Theme swatches ── */
.offline-theme-picker { display: flex; gap: 12px; padding: 16px 20px 8px; }
/* ── Context menu ── */
.offline-ctx-menu {
  position: fixed; background: #1c1c1c; border-radius: 14px;
  padding: 6px 4px; display: flex; flex-wrap: wrap; gap: 2px;
  z-index: 99999; box-shadow: 0 12px 36px rgba(0,0,0,0.55);
  animation: menuPop 0.15s cubic-bezier(0.16,1,0.3,1);
  max-width: calc(100vw - 24px); backdrop-filter: blur(8px);
}
.offline-ctx-btn {
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  padding: 9px 11px; color: #e0e0e0; cursor: pointer;
  border-radius: 10px; transition: background 0.12s; min-width: 50px;
}
.offline-ctx-btn:hover { background: rgba(255,255,255,0.1); }
.offline-ctx-btn i { font-size: 14px; }
.offline-ctx-btn span { font-size: 9px; white-space: nowrap; letter-spacing: 0.5px; }
.offline-ctx-btn.danger i, .offline-ctx-btn.danger span { color: #e05555; }
/* ── Multi-select highlight ── */
.offline-msg-row.offline-selected .offline-short-bubble,
.offline-msg-row.offline-selected .offline-narrative {
  outline: 2px solid rgba(200,200,200,0.4); border-radius: 8px;
}
.offline-msg-row.offline-selected { background: rgba(255,255,255,0.03); }
.offline-theme-swatch {
  width: 52px; height: 52px; border-radius: 14px; cursor: pointer;
  position: relative; transition: transform 0.18s, box-shadow 0.18s;
  display: flex; align-items: flex-end; justify-content: center; padding-bottom: 6px;
}
.offline-theme-swatch:active { transform: scale(0.9); }
.offline-theme-swatch.selected {
  box-shadow: 0 0 0 2px var(--off-tab-sel);
}
.offline-theme-swatch.selected::after {
  content: '✓'; position: absolute; top: 50%; left: 50%;
  transform: translate(-50%,-60%); font-size: 15px; font-weight: 700;
}
.offline-theme-swatch span {
  font-size: 7.5px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase;
  font-family: 'DM Mono', monospace; opacity: 0.65;
}
/* Family Tree Interactive */
.ft-avatar-wrap { transition: transform 0.2s cubic-bezier(0.34,1.56,0.64,1), filter 0.2s ease !important; }
@media (hover: hover) {
  [id^="ftree_"] div[onclick]:hover .ft-avatar-wrap { transform: scale(1.12); filter: brightness(1.2); }
  [id^="ftree_"] div[onclick]:hover { transform: translateY(-2px); }
}
[id^="ftree_"] div[onclick]:active .ft-avatar-wrap { transform: scale(0.9) !important; }


/* ═══════════════════════════════════════════════
   NEW DIARY MODULE — Japanese Gray-White Aesthetic
   ═══════════════════════════════════════════════ */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;1,300;1,400&family=Noto+Serif+SC:wght@300;400&family=Playfair+Display:ital@1&family=Shippori+Mincho:wght@300;400&display=swap');

:root {
  --diary-cream: #f9f7f4;
  --diary-paper: #fafaf8;
  --diary-line: #e0ddd9;
  --diary-ink: #2a2726;
  --diary-soft: #8a8380;
  --diary-accent: #b8b0a8;
  --diary-cover-default: #ede9e4;
  --diary-shadow: rgba(0,0,0,0.12);
}

/* ── Main Diary Page ── */
#diaryPage { background: var(--diary-cream); flex-direction: column; }

.diary-main-wrap {
  flex: 1; display: flex; flex-direction: column; overflow: hidden;
  background: var(--diary-cream);
  transition: background 0.3s;
  position: relative;
}

/* ── Shelf Floating Background Deco ── */
.diary-bg-deco {
  position: absolute; inset: 0; pointer-events: none; overflow: hidden; z-index: 0;
}
.diary-bg-kanji {
  position: absolute; font-family: 'Shippori Mincho', serif;
  color: rgba(165,155,145,0.07); user-select: none; line-height: 1;
}
.diary-bg-petal {
  position: absolute; font-size: 14px; opacity: 0;
  animation: petalFloat 12s infinite ease-in-out;
  pointer-events: none;
}
@keyframes petalFloat {
  0%   { opacity:0; transform: translateY(0) rotate(0deg); }
  10%  { opacity:0.5; }
  90%  { opacity:0.3; }
  100% { opacity:0; transform: translateY(-80px) rotate(180deg); }
}

/* ── Deco Zone (bottom of shelf screen) ── */
.diary-deco-zone {
  flex-shrink: 0; height: 110px;
  position: relative; z-index: 1;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 8px; padding: 0 20px;
}
.diary-deco-inner {
  display: flex; align-items: center; justify-content: center; gap: 18px; width: 100%;
}
.ddz-stamp {
  opacity: 0.6; flex-shrink: 0;
}
.ddz-phrase {
  text-align: center; flex: 1;
}
.ddz-kanji {
  font-family: 'Shippori Mincho', serif;
  font-size: 13px; color: var(--diary-soft); letter-spacing: 0.18em;
}
.ddz-romaji {
  font-family: 'Cormorant Garamond', serif;
  font-size: 9.5px; color: var(--diary-accent); letter-spacing: 0.12em;
  font-style: italic; margin-top: 3px;
}
.ddz-washi-col {
  display: flex; flex-direction: column; gap: 5px; flex-shrink: 0;
}
.ddz-washi-tape {
  width: 52px; height: 10px; border-radius: 2px;
  background: repeating-linear-gradient(
    90deg,
    rgba(190,175,210,0.55) 0px, rgba(190,175,210,0.55) 6px,
    rgba(210,195,225,0.4) 6px, rgba(210,195,225,0.4) 12px
  );
  transform: rotate(-1.5deg);
}
.ddz-washi-2 {
  width: 44px;
  background: repeating-linear-gradient(
    90deg,
    rgba(210,185,170,0.55) 0px, rgba(210,185,170,0.55) 5px,
    rgba(230,210,195,0.4) 5px, rgba(230,210,195,0.4) 10px
  );
  transform: rotate(1deg);
}
.ddz-ink-row {
  display: flex; align-items: center; gap: 6px;
  opacity: 0.45;
}
.ddz-dot {
  width: 4px; height: 4px; border-radius: 50%;
  background: var(--diary-soft);
}
.ddz-line {
  flex: 1; max-width: 60px; height: 0.5px; background: var(--diary-accent);
}
.ddz-sakura {
  font-size: 11px; color: var(--diary-soft);
  font-family: serif;
}
.ddz-corner-note {
  position: absolute; right: 16px; bottom: 10px;
  font-family: 'Cormorant Garamond', serif;
  font-size: 8.5px; color: var(--diary-accent);
  letter-spacing: 0.15em; font-style: italic;
}

/* ── Top Bar ── */
.diary-topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 14px 8px;
  border-bottom: 1px solid var(--diary-line);
  background: var(--diary-cream);
  flex-shrink: 0;
  gap: 6px;
  transition: background 0.3s;
}
.diary-topbar-title {
  font-family: 'Cormorant Garamond', serif;
  font-size: 18px; font-weight: 300; letter-spacing: 0.10em;
  color: var(--diary-ink); flex-shrink: 0;
}
.diary-topbar-actions { display: flex; gap: 5px; align-items: center; flex-shrink: 0; }
.diary-btn {
  font-family: 'Shippori Mincho', serif;
  font-size: 10px; padding: 4px 9px;
  border-radius: 16px; cursor: pointer;
  border: 1px solid var(--diary-ink);
  background: transparent; color: var(--diary-ink);
  letter-spacing: 0.04em; transition: all 0.2s; white-space: nowrap;
}
.diary-btn:hover { background: var(--diary-ink); color: #fff; }
.diary-btn-primary { background: var(--diary-ink); color: #fff; }
.diary-btn-primary:hover { opacity: 0.8; }

/* ── Book Shelf (Horizontal Scroll) ── */
.diary-shelf {
  flex: 1; display: flex; align-items: center;
  padding: 30px 20px 20px;
  overflow-x: auto; overflow-y: hidden;
  gap: 24px;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  position: relative; z-index: 1;
}
.diary-shelf::-webkit-scrollbar { display: none; }

/* ── Book Cover Card ── */
.diary-book-card {
  flex-shrink: 0; scroll-snap-align: center;
  display: flex; flex-direction: column; align-items: center;
  cursor: pointer; position: relative;
  width: 160px;
}
.diary-book-cover {
  width: 160px; height: 220px;
  border-radius: 4px 14px 14px 4px;
  background: var(--diary-cover-default);
  box-shadow: -4px 4px 16px var(--diary-shadow), -2px 2px 6px rgba(0,0,0,0.08);
  position: relative; overflow: hidden;
  transition: transform 0.3s cubic-bezier(.34,1.56,.64,1), box-shadow 0.3s;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
}
.diary-book-card:hover .diary-book-cover {
  transform: translateY(-8px) rotate(1deg);
  box-shadow: -6px 14px 28px rgba(0,0,0,0.18), -2px 4px 8px rgba(0,0,0,0.1);
}

/* Spine effect */
.diary-book-cover::before {
  content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 14px;
  background: linear-gradient(to right, rgba(0,0,0,0.18), rgba(0,0,0,0.05) 60%, transparent);
  border-radius: 4px 0 0 4px;
}
/* Ring binder dot */
.diary-book-cover::after {
  content: ''; position: absolute; right: -8px; top: 50%;
  transform: translateY(-50%);
  width: 16px; height: 16px; border-radius: 50%;
  background: #e8e4df;
  box-shadow: 0 1px 4px rgba(0,0,0,0.15), inset 0 1px 2px rgba(255,255,255,0.6);
}

.diary-book-cover-img {
  width: 100px; height: 90px; object-fit: cover;
  border: 3px solid rgba(255,255,255,0.85);
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  display: block; margin: auto;
  border-radius: 2px;
}
.diary-cover-text-layer {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0; pointer-events: none;
}
.diary-cover-sticker-layer {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0; pointer-events: none;
}
.diary-cover-default-text {
  font-family: 'Cormorant Garamond', serif;
  font-size: 13px; font-style: italic; letter-spacing: 0.08em;
  color: rgba(42,39,38,0.6); text-align: center;
  line-height: 1.6; padding: 16px 16px 0;
}

.diary-book-label {
  margin-top: 10px; text-align: center;
}
.diary-book-name {
  font-family: 'Shippori Mincho', serif;
  font-size: 12px; color: var(--diary-ink);
  font-weight: 400; letter-spacing: 0.04em;
}
.diary-book-count {
  font-family: 'Cormorant Garamond', serif;
  font-size: 10px; color: var(--diary-soft);
  margin-top: 2px; letter-spacing: 0.06em;
}

/* Pencil edit button */
.diary-book-edit-btn {
  position: absolute; top: 6px; right: 6px;
  width: 28px; height: 28px; border-radius: 50%;
  background: rgba(255,255,255,0.9);
  border: 1px solid var(--diary-line);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; font-size: 11px; color: var(--diary-soft);
  box-shadow: 0 1px 4px rgba(0,0,0,0.1);
  transition: all 0.2s; z-index: 2;
  opacity: 0;
}
.diary-book-card:hover .diary-book-edit-btn { opacity: 1; }

/* ── Diary Book Viewer (Full Screen) ── */
#diaryBookViewer {
  position: fixed; inset: 0; z-index: 9000;
  background: rgba(245,242,238,0.96);
  display: none; flex-direction: column;
  align-items: center; justify-content: flex-start;
  overflow: hidden;
}
#diaryBookViewer.active { display: flex; }

.diary-viewer-topbar {
  width: 100%; display: flex; align-items: center; justify-content: space-between;
  padding: 12px 20px;
  background: var(--diary-cream);
  border-bottom: 1px solid var(--diary-line);
  flex-shrink: 0; z-index: 10;
}
.diary-viewer-title {
  font-family: 'Cormorant Garamond', serif;
  font-size: 17px; font-weight: 300; letter-spacing: 0.1em;
  color: var(--diary-ink);
}
.diary-viewer-close {
  font-size: 13px; color: var(--diary-soft);
  cursor: pointer; padding: 4px 10px;
  border: 1px solid var(--diary-line); border-radius: 14px;
  font-family: 'Cormorant Garamond', serif;
  letter-spacing: 0.05em; transition: all 0.2s;
}
.diary-viewer-close:hover { background: var(--diary-ink); color: #fff; border-color: var(--diary-ink); }

/* ── Page Flip Container ── */
.diary-page-container {
  flex: 1; display: flex; align-items: center; justify-content: center;
  perspective: 1200px; width: 100%;
  padding: 20px 16px; box-sizing: border-box;
  overflow: hidden;
}

.diary-page-scene {
  position: relative;
  width: min(380px, 90vw);
  height: min(560px, calc(100vh - 140px));
}

/* Page wrapper with flip animation */
.diary-page-book {
  width: 100%; height: 100%;
  position: relative;
  transform-style: preserve-3d;
}

/* Actual page */
.diary-page {
  width: 100%; height: 100%;
  background: var(--diary-paper);
  border-radius: 2px 8px 8px 2px;
  box-shadow: -3px 4px 20px rgba(0,0,0,0.15), 3px 4px 12px rgba(0,0,0,0.08);
  position: relative; overflow: hidden;
  display: flex; flex-direction: column;
}

/* Lined paper effect */
.diary-page-lines {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-image: repeating-linear-gradient(
    to bottom,
    transparent,
    transparent 31px,
    var(--diary-line) 31px,
    var(--diary-line) 32px
  );
  background-position: 0 48px;
  pointer-events: none;
}

/* Page top margin red line */
.diary-page-margin {
  position: absolute; top: 0; left: 44px; bottom: 0;
  width: 1px; background: #e8b8b8; opacity: 0.5;
  pointer-events: none;
}

.diary-page-content {
  position: relative; z-index: 2;
  padding: 16px 20px 16px 52px;
  flex: 1; overflow-y: auto; overflow-x: hidden;
}
.diary-page-content::-webkit-scrollbar { display: none; }

/* Page numbers */
.diary-page-num {
  position: absolute; bottom: 10px; right: 16px;
  font-family: 'Cormorant Garamond', serif;
  font-size: 11px; color: var(--diary-accent);
  letter-spacing: 0.1em;
}

/* ── Diary Entry on Page ── */
.diary-entry-date {
  font-family: 'Cormorant Garamond', serif;
  font-size: 12px; color: var(--diary-soft);
  letter-spacing: 0.12em; margin-bottom: 12px;
  line-height: 32px;
}
.diary-entry-text {
  font-family: 'Shippori Mincho', serif;
  font-size: 13px; line-height: 32px;
  color: var(--diary-ink);
  white-space: pre-wrap; word-break: break-word;
}
.diary-entry-paragraph {
  margin-bottom: 0;
  line-height: 32px;
  text-indent: 2em;
}

/* ── TOC Page ── */
.diary-toc-title {
  font-family: 'Cormorant Garamond', serif;
  font-size: 20px; font-style: italic;
  letter-spacing: 0.15em; color: var(--diary-ink);
  text-align: center; margin-bottom: 24px;
  margin-top: 8px; line-height: 32px;
}
.diary-toc-item {
  display: flex; align-items: baseline;
  font-family: 'Shippori Mincho', serif;
  font-size: 12px; line-height: 32px;
  color: var(--diary-ink); cursor: pointer;
  border-bottom: none; transition: color 0.15s;
  gap: 4px;
}
.diary-toc-item:hover .diary-toc-date { color: var(--diary-ink); text-decoration: underline; }
.diary-toc-date { flex: 0 0 auto; letter-spacing: 0.06em; }
.diary-toc-dots {
  flex: 1; border-bottom: 1px dotted var(--diary-accent);
  margin: 0 6px; height: 1px; align-self: center;
  transform: translateY(-6px);
}
.diary-toc-page-num {
  flex: 0 0 auto; color: var(--diary-soft); font-size: 11px;
}
.diary-toc-calendar-link {
  font-family: 'Cormorant Garamond', serif;
  font-size: 12px; font-style: italic;
  color: var(--diary-soft); cursor: pointer;
  line-height: 32px; letter-spacing: 0.08em;
  transition: color 0.15s;
}
.diary-toc-calendar-link:hover { color: var(--diary-ink); }

/* ── Navigation Arrows ── */
.diary-nav {
  display: flex; gap: 12px; justify-content: center; align-items: center;
  padding: 12px 0 16px; flex-shrink: 0;
}
.diary-nav-btn {
  width: 36px; height: 36px; border-radius: 50%;
  border: 1px solid var(--diary-line);
  background: var(--diary-paper);
  color: var(--diary-soft); font-size: 13px;
  cursor: pointer; transition: all 0.2s;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 2px 6px rgba(0,0,0,0.08);
}
.diary-nav-btn:hover { background: var(--diary-ink); color: #fff; border-color: var(--diary-ink); }
.diary-nav-btn:disabled { opacity: 0.3; cursor: default; }
.diary-nav-page-info {
  font-family: 'Cormorant Garamond', serif;
  font-size: 12px; color: var(--diary-soft);
  letter-spacing: 0.1em; min-width: 60px; text-align: center;
}

/* ── Page Flip Animation ── */
@keyframes flipPageForward {
  0% { transform: rotateY(0deg); }
  100% { transform: rotateY(-90deg); }
}
@keyframes flipPageBack {
  0% { transform: rotateY(90deg); }
  100% { transform: rotateY(0deg); }
}
.diary-page.flip-out {
  animation: flipPageForward 0.3s ease-in forwards;
  transform-origin: left center;
}
.diary-page.flip-in {
  animation: flipPageBack 0.3s ease-out forwards;
  transform-origin: left center;
}

/* ── Open Animation (Book Opening) ── */
@keyframes bookOpen {
  0% { transform: scale(0.3) rotateY(-40deg); opacity: 0; }
  60% { transform: scale(1.04) rotateY(-5deg); opacity: 1; }
  100% { transform: scale(1) rotateY(0deg); opacity: 1; }
}
.diary-page.book-opening {
  animation: bookOpen 0.55s cubic-bezier(.22,.61,.36,1) forwards;
}

/* ── Calendar Page ── */
.diary-calendar-page {
  padding: 16px 20px 20px; height: 100%; box-sizing: border-box;
  display: flex; flex-direction: column; overflow: hidden;
}
.diary-cal-month {
  font-family: 'Cormorant Garamond', serif;
  font-size: 28px; font-weight: 300; letter-spacing: 0.15em;
  color: var(--diary-ink); line-height: 1;
}
.diary-cal-year {
  font-family: 'Cormorant Garamond', serif;
  font-size: 12px; color: var(--diary-soft);
  letter-spacing: 0.2em; margin-bottom: 10px;
  margin-top: 2px;
}
.diary-cal-grid {
  display: grid; grid-template-columns: repeat(7, 1fr);
  border-left: 1px solid var(--diary-line);
  border-top: 1px solid var(--diary-line);
  flex: 1;
}
.diary-cal-header {
  font-family: 'Cormorant Garamond', serif;
  font-size: 9px; letter-spacing: 0.12em;
  color: var(--diary-soft); text-transform: uppercase;
  padding: 4px 2px; text-align: right;
  border-right: 1px solid var(--diary-line);
  border-bottom: 1px solid var(--diary-line);
}
.diary-cal-cell {
  border-right: 1px solid var(--diary-line);
  border-bottom: 1px solid var(--diary-line);
  padding: 3px 4px; min-height: 52px;
  display: flex; flex-direction: column;
  overflow: hidden;
  font-family: 'Cormorant Garamond', serif;
}
.diary-cal-cell-num {
  font-size: 11px; color: var(--diary-soft);
  text-align: right; flex-shrink: 0;
  line-height: 1.2;
}
.diary-cal-cell.has-diary .diary-cal-cell-num { color: var(--diary-ink); font-weight: 400; }
.diary-cal-cell-empty { border-right: 1px solid var(--diary-line); border-bottom: 1px solid var(--diary-line); background: #f5f3f0; }
.diary-cal-memo {
  font-size: 7.5px; color: #6a6460; line-height: 1.35;
  overflow: hidden; flex: 1; margin-top: 1px;
  font-family: 'Noto Serif SC', serif;
}
.diary-cal-notes {
  border-top: 1px solid var(--diary-line); margin-top: 6px;
  padding-top: 4px; flex-shrink: 0;
}
.diary-cal-notes-label {
  font-family: 'Cormorant Garamond', serif;
  font-size: 8px; letter-spacing: 0.2em;
  color: var(--diary-soft); text-transform: uppercase;
  margin-bottom: 4px;
}
.diary-cal-notes-lines { display: flex; flex-direction: column; gap: 4px; }
.diary-cal-notes-line {
  height: 1px; background: var(--diary-line);
}

/* ── Cover Editor Modal ── */
#diaryCoverEditor {
  position: fixed; inset: 0; z-index: 10000;
  background: rgba(0,0,0,0.5);
  display: none; align-items: flex-end; justify-content: center;
}
#diaryCoverEditor.active { display: flex; }
.diary-cover-editor-panel {
  background: var(--diary-cream); border-radius: 20px 20px 0 0;
  width: 100%; max-width: 480px;
  padding: 20px 20px 32px;
  max-height: 85vh; overflow-y: auto;
}
.diary-cover-editor-panel::-webkit-scrollbar { display: none; }
.diary-cover-editor-title {
  font-family: 'Cormorant Garamond', serif;
  font-size: 17px; font-weight: 300; letter-spacing: 0.12em;
  color: var(--diary-ink); margin-bottom: 16px;
  display: flex; align-items: center; justify-content: space-between;
}
.diary-cover-editor-section {
  margin-bottom: 18px;
}
.diary-cover-editor-label {
  font-family: 'Shippori Mincho', serif;
  font-size: 11px; color: var(--diary-soft);
  letter-spacing: 0.08em; margin-bottom: 8px;
  text-transform: uppercase;
}

/* Cover Preview in editor */
.diary-cover-preview {
  width: 140px; height: 192px;
  border-radius: 3px 12px 12px 3px;
  background: var(--diary-cover-default);
  box-shadow: -3px 3px 12px var(--diary-shadow);
  position: relative; overflow: visible;
  margin: 0 auto 16px;
  cursor: default;
}
.diary-cover-preview::before {
  content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 12px;
  background: linear-gradient(to right, rgba(0,0,0,0.18), transparent);
  border-radius: 3px 0 0 3px;
  pointer-events: none; z-index: 1;
}

/* Color swatches */
.diary-color-swatches {
  display: flex; gap: 8px; flex-wrap: wrap;
}
.diary-swatch {
  width: 28px; height: 28px; border-radius: 50%;
  cursor: pointer; border: 2px solid transparent;
  transition: border-color 0.2s; flex-shrink: 0;
}
.diary-swatch.selected { border-color: var(--diary-ink); }

/* Font options */
.diary-font-options { display: flex; gap: 6px; flex-wrap: wrap; }
.diary-font-opt {
  padding: 4px 10px; border: 1px solid var(--diary-line);
  border-radius: 12px; font-size: 12px; cursor: pointer;
  transition: all 0.2s; background: var(--diary-paper);
  color: var(--diary-ink);
}
.diary-font-opt.selected { background: var(--diary-ink); color: #fff; border-color: var(--diary-ink); }

/* Draggable sticker/text on cover */
.diary-cover-decos {
  position: absolute; inset: 0; pointer-events: none;
}
.diary-cover-deco-item {
  position: absolute; pointer-events: all;
  cursor: move; user-select: none;
  touch-action: none;
}
.diary-cover-deco-item.selected {
  outline: 1px dashed var(--diary-soft);
  outline-offset: 2px;
}

/* ── Diary Write Modal ── */
#diaryWriteModal {
  position: fixed; inset: 0; z-index: 9500;
  background: rgba(0,0,0,0.45);
  display: none; align-items: flex-end; justify-content: center;
}
#diaryWriteModal.active { display: flex; }
.diary-write-panel {
  background: var(--diary-paper); border-radius: 20px 20px 0 0;
  width: 100%; max-width: 480px; padding: 20px 20px 40px;
}
.diary-write-title {
  font-family: 'Cormorant Garamond', serif;
  font-size: 17px; letter-spacing: 0.12em; font-weight: 300;
  color: var(--diary-ink); margin-bottom: 12px;
  display: flex; justify-content: space-between;
}
.diary-write-textarea {
  width: 100%; min-height: 140px;
  border: none; border-bottom: 1px solid var(--diary-line);
  outline: none; resize: none; padding: 8px 0;
  font-family: 'Shippori Mincho', serif;
  font-size: 14px; line-height: 1.8;
  background: transparent; color: var(--diary-ink);
  letter-spacing: 0.03em;
}
.diary-write-actions {
  display: flex; gap: 8px; margin-top: 14px; justify-content: flex-end;
}

/* ── AI Generate Modal ── */
#diaryAiModal {
  position: fixed; inset: 0; z-index: 9500;
  background: rgba(0,0,0,0.45);
  display: none; align-items: flex-end; justify-content: center;
}
#diaryAiModal.active { display: flex; }
.diary-ai-panel {
  background: var(--diary-paper); border-radius: 20px 20px 0 0;
  width: 100%; max-width: 480px; padding: 20px 20px 40px;
}
.diary-ai-title {
  font-family: 'Cormorant Garamond', serif;
  font-size: 17px; letter-spacing: 0.12em; font-weight: 300;
  color: var(--diary-ink); margin-bottom: 14px;
}
.diary-char-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px;
  margin-bottom: 14px; max-height: 200px; overflow-y: auto;
}
.diary-char-option {
  border: 1px solid var(--diary-line); border-radius: 10px;
  padding: 10px 8px; text-align: center; cursor: pointer;
  transition: all 0.2s; background: var(--diary-paper);
}
.diary-char-option.selected {
  border-color: var(--diary-ink); background: var(--diary-ink); color: #fff;
}
.diary-char-avatar {
  width: 40px; height: 40px; border-radius: 50%; object-fit: cover;
  margin: 0 auto 6px; display: block;
  background: var(--diary-line);
}
.diary-char-name {
  font-family: 'Shippori Mincho', serif;
  font-size: 11px; color: inherit;
}

/* ── Page sticker drag handle ── */
.diary-page-sticker {
  position: absolute; cursor: move; user-select: none;
  touch-action: none;
}
.diary-page-sticker.selected {
  outline: 1px dashed #aaa; outline-offset: 2px;
}
.diary-page-sticker img { pointer-events: none; }
.diary-sticker-resize {
  position: absolute; right: -5px; bottom: -5px;
  width: 14px; height: 14px;
  background: var(--diary-ink); border-radius: 50%;
  cursor: se-resize; opacity: 0.7;
}
.diary-sticker-delete {
  position: absolute; right: -5px; top: -5px;
  width: 16px; height: 16px;
  background: #e74c3c; border-radius: 50%;
  cursor: pointer; color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 8px;
}

/* ── Japanese decorative stickers ── */
.diary-jp-sticker {
  position: absolute; opacity: 0.7;
  font-size: 20px; pointer-events: none; user-select: none;
}

/* ── Loading spinner ── */
.diary-loading {
  display: flex; flex-direction: column; align-items: center;
  justify-content: center; padding: 40px;
  font-family: 'Cormorant Garamond', serif;
  font-size: 14px; color: var(--diary-soft);
  letter-spacing: 0.1em; gap: 12px;
}
.diary-loading-dot {
  display: flex; gap: 5px;
}
.diary-loading-dot span {
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--diary-accent);
  animation: dotPulse 1.2s infinite;
}
.diary-loading-dot span:nth-child(2) { animation-delay: 0.2s; }
.diary-loading-dot span:nth-child(3) { animation-delay: 0.4s; }
@keyframes dotPulse {
  0%, 80%, 100% { transform: scale(0.6); opacity: 0.4; }
  40% { transform: scale(1); opacity: 1; }
}

/* ── Sticker add button on page ── */
.diary-page-add-sticker {
  position: absolute; bottom: 30px; right: 12px;
  width: 32px; height: 32px; border-radius: 50%;
  background: var(--diary-paper); border: 1px solid var(--diary-line);
  color: var(--diary-soft); cursor: pointer; z-index: 10;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; box-shadow: 0 2px 6px rgba(0,0,0,0.1);
  transition: all 0.2s;
}
.diary-page-add-sticker:hover { background: var(--diary-ink); color: #fff; }

/* ── Text color picker ── */
.diary-text-color-row {
  display: flex; align-items: center; gap: 10px;
}

/* ── Regen button on page ── */
.diary-regen-btn {
  font-size: 10px; padding: 3px 10px;
  border: 1px solid var(--diary-line); border-radius: 10px;
  background: transparent; color: var(--diary-soft);
  cursor: pointer; font-family: 'Shippori Mincho', serif;
  letter-spacing: 0.04em; transition: all 0.2s; margin-left: 8px;
}
.diary-regen-btn:hover { background: var(--diary-ink); color: #fff; border-color: var(--diary-ink); }

/* ── Delete entry btn ── */
.diary-delete-btn {
  font-size: 10px; padding: 3px 10px;
  border: 1px solid #f5c6c6; border-radius: 10px;
  background: transparent; color: #e74c3c;
  cursor: pointer; font-family: 'Shippori Mincho', serif;
  letter-spacing: 0.04em; transition: all 0.2s;
}
.diary-delete-btn:hover { background: #e74c3c; color: #fff; }

/* ── Image sticker modal ── */
#diaryImgStickerModal {
  position: fixed; inset: 0; z-index: 10500;
  background: rgba(0,0,0,0.5);
  display: none; align-items: flex-end; justify-content: center;
}
#diaryImgStickerModal.active { display: flex; }
.diary-img-sticker-panel {
  background: var(--diary-paper); border-radius: 20px 20px 0 0;
  width: 100%; max-width: 480px; padding: 20px 20px 40px;
}

/* ── Shape selector ── */
.diary-shape-options { display: flex; gap: 10px; flex-wrap: wrap; }
.diary-shape-opt {
  width: 52px; height: 52px;
  border: 1px solid var(--diary-line); border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; transition: all 0.2s; background: var(--diary-paper);
  font-size: 10px; color: var(--diary-soft); text-align: center;
  flex-direction: column; gap: 3px;
  font-family: 'Shippori Mincho', serif;
}
.diary-shape-opt:hover, .diary-shape-opt.selected {
  border-color: var(--diary-ink); background: var(--diary-ink); color: #fff;
}
.diary-shape-icon { font-size: 20px; }

/* ── Regen spinner overlay ── */
.diary-regen-overlay {
  position: absolute; inset: 0; background: rgba(249,247,244,0.85);
  display: flex; align-items: center; justify-content: center;
  z-index: 20; border-radius: 2px 8px 8px 2px;
}



/* ===== FIX: Custom chat background must show in default theme too =====
#chatPage.mono-has-custom-bg #chatBox,
#chatPage.mono-has-custom-bg .chat-messages {
  background-image: var(--mono-chat-bg-image) !important;
  background-size: cover !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
}
#chatPage.mono-has-custom-bg.bubble-preset-wechat #chatBox,
#chatPage.mono-has-custom-bg.bubble-preset-imessage #chatBox,
#chatPage.mono-has-custom-bg.bubble-preset-line #chatBox,
#chatPage.mono-has-custom-bg.bubble-preset-retro #chatBox,
#chatPage.mono-has-custom-bg.bubble-preset-journal #chatBox {
  background-image: var(--mono-chat-bg-image) !important;
  background-size: cover !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
}
#chatPage.mono-has-custom-bg:not(.chat-theme-frosted) #chatBox::before,
#chatPage.mono-has-custom-bg:not(.chat-theme-frosted) .chat-messages::before {
  content: none !important;
}



/* ===== style-4 ===== */

/* ===== Secondary API Management Styles ===== */
/* --- Secondary API Section in API Settings Modal --- */
.secondary-api-section {
  border-top: 2px solid #eee;
  padding-top: 20px;
  margin-top: 24px;
}
.secondary-api-section .section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.secondary-api-section .section-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: #333;
}
.secondary-api-section .add-api-btn {
  font-size: 10px;
  border: 1px solid #1a1a1a;
  padding: 5px 14px;
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
  font-family: inherit;
  font-weight: 600;
  transition: all 0.2s;
}
.secondary-api-section .add-api-btn:hover {
  background: #1a1a1a;
  color: #fff;
}
/* Active API indicator */
.active-api-indicator {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-radius: 8px;
  margin-bottom: 16px;
  font-size: 11px;
  color: #166534;
}
.active-api-indicator .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #22c55e;
  flex-shrink: 0;
  animation: apiPulse 2s infinite;
}
@keyframes apiPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}
.active-api-indicator .api-name {
  font-weight: 700;
