.secondary-api-card .card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}
.secondary-api-card .card-name {
  font-size: 12px;
  font-weight: 700;
  color: #1a1a1a;
  display: flex;
  align-items: center;
  gap: 6px;
}
.secondary-api-card .card-name .active-badge {
  font-size: 8px;
  padding: 1px 6px;
  background: #22c55e;
  color: #fff;
  border-radius: 4px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.secondary-api-card .card-actions {
  display: flex;
  gap: 6px;
}
.secondary-api-card .card-actions button {
  font-size: 10px;
  padding: 3px 8px;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  background: #fff;
  cursor: pointer;
  font-family: inherit;
  transition: all 0.15s;
}
.secondary-api-card .card-actions button:hover {
  background: #f3f4f6;
}
.secondary-api-card .card-actions .delete-btn:hover {
  background: #fef2f2;
  border-color: #fca5a5;
  color: #dc2626;
}
.secondary-api-card .card-info {
  font-size: 10px;
  color: #888;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.secondary-api-card .card-info span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Empty state */
.secondary-api-empty {
  text-align: center;
  padding: 20px;
  color: #aaa;
  font-size: 11px;
}
/* --- Add/Edit Secondary API Form Modal --- */
.sec-api-form-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s;
}
.sec-api-form-overlay.show {
  opacity: 1;
  pointer-events: auto;
}
.sec-api-form {
  background: #fff;
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 380px;
  max-height: 80vh;
  overflow-y: auto;
  box-shadow: 0 20px 60px rgba(0,0,0,0.2);
  transform: translateY(20px);
  transition: transform 0.25s;
}
.sec-api-form-overlay.show .sec-api-form {
  transform: translateY(0);
}
.sec-api-form h4 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 16px;
  text-align: center;
  letter-spacing: -0.5px;
}
.sec-api-form .form-group {
  margin-bottom: 14px;
}
.sec-api-form .form-group label {
  display: block;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #666;
  margin-bottom: 4px;
}
.sec-api-form .form-group input,
.sec-api-form .form-group select {
  width: 100%;
  border: none;
  border-bottom: 1px solid #ccc;
  padding: 8px 0;
  outline: none;
  font-size: 12px;
  font-family: inherit;
  background: transparent;
}
.sec-api-form .form-group input:focus,
.sec-api-form .form-group select:focus {
  border-bottom-color: #1a1a1a;
}
.sec-api-form .model-row {
  display: flex;
  gap: 6px;
  align-items: flex-end;
}
.sec-api-form .model-row select {
  flex: 1;
}
.sec-api-form .model-row button {
  font-size: 10px;
  border: 1px solid #1a1a1a;
  padding: 6px 12px;
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
  margin-bottom: 1px;
}
.sec-api-form .model-row button:hover {
  background: #1a1a1a;
  color: #fff;
}
.sec-api-form .form-actions {
  display: flex;
  gap: 8px;
  margin-top: 20px;
}
.sec-api-form .form-actions button {
  flex: 1;
  padding: 12px;
  border: 1px solid #1a1a1a;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  border-radius: 8px;
  transition: all 0.2s;
}
.sec-api-form .form-actions .cancel-btn {
  background: #fff;
  color: #1a1a1a;
}
.sec-api-form .form-actions .cancel-btn:hover {
  background: #f3f4f6;
}
.sec-api-form .form-actions .save-btn {
  background: #1a1a1a;
  color: #fff;
}
.sec-api-form .form-actions .save-btn:hover {
  background: #333;
}
.sec-api-form .fetch-status {
  font-size: 10px;
  margin-top: 4px;
  min-height: 14px;
}
/* --- Floating API Switcher Button (FAB) --- */
.api-fab {
  position: fixed;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, #1a1a1a, #444);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: grab;
  z-index: 9999;
  box-shadow: 0 4px 16px rgba(0,0,0,0.3);
  user-select: none;
  touch-action: none;
  transition: box-shadow 0.2s, transform 0.2s;
  font-size: 16px;
}
.api-fab:active {
  cursor: grabbing;
  box-shadow: 0 6px 24px rgba(0,0,0,0.4);
  transform: scale(1.08);
}
.api-fab .fab-icon {
  pointer-events: none;
  font-size: 18px;
  line-height: 1;
}
.api-fab .fab-dot {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #22c55e;
  border: 1.5px solid #fff;
}
/* --- FAB Slide-out Panel --- */
.api-fab-panel {
  position: fixed;
  z-index: 9998;
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 8px 40px rgba(0,0,0,0.18);
  padding: 16px;
  width: 260px;
  max-height: 360px;
  overflow-y: auto;
  opacity: 0;
  pointer-events: none;
  transform: scale(0.9) translateY(10px);
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  transform-origin: bottom right;
}
.api-fab-panel.show {
  opacity: 1;
  pointer-events: auto;
  transform: scale(1) translateY(0);
}
.api-fab-panel .panel-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #333;
  margin-bottom: 12px;
  text-align: center;
}
.api-fab-panel .api-option {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  margin-bottom: 8px;
  cursor: pointer;
  transition: all 0.15s;
  position: relative;
}
.api-fab-panel .api-option:hover {
  background: #f9fafb;
  border-color: #d1d5db;
}
.api-fab-panel .api-option.selected {
  border-color: #22c55e;
  background: #f0fdf4;
}
.api-fab-panel .api-option .option-radio {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 2px solid #d1d5db;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s;
}
.api-fab-panel .api-option.selected .option-radio {
  border-color: #22c55e;
}
.api-fab-panel .api-option.selected .option-radio::after {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #22c55e;
}
.api-fab-panel .api-option .option-info {
  flex: 1;
  min-width: 0;
}
.api-fab-panel .api-option .option-name {
  font-size: 12px;
  font-weight: 600;
  color: #1a1a1a;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.api-fab-panel .api-option .option-model {
  font-size: 9px;
  color: #999;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-top: 1px;
}
.api-fab-panel .panel-save-btn {
  width: 100%;
  padding: 10px;
  background: #1a1a1a;
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-top: 4px;
  transition: background 0.2s;
}
.api-fab-panel .panel-save-btn:hover {
  background: #333;
}
/* --- FAB Toggle Switch in API Settings --- */
.fab-toggle-section {
  border-top: 2px solid #eee;
  padding-top: 20px;
  margin-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.fab-toggle-section .toggle-label {
  font-size: 11px;
  font-weight: 600;
  color: #333;
}
.fab-toggle-section .toggle-desc {
  font-size: 9px;
  color: #999;
  margin-top: 2px;
}
.toggle-switch {
  position: relative;
  width: 44px;
  height: 24px;
  flex-shrink: 0;
}
.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}
.toggle-switch .slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  background: #ccc;
  border-radius: 24px;
  transition: background 0.3s;
}
.toggle-switch .slider::before {
  content: '';
  position: absolute;
  width: 18px;
  height: 18px;
  left: 3px;
  bottom: 3px;
  background: #fff;
  border-radius: 50%;
  transition: transform 0.3s;
}
.toggle-switch input:checked + .slider {
  background: #22c55e;
}
.toggle-switch input:checked + .slider::before {
  transform: translateX(20px);
}
/* Scrollbar for secondary API list */
.secondary-api-list::-webkit-scrollbar {
  width: 4px;
}
.secondary-api-list::-webkit-scrollbar-track {
  background: transparent;
}
.secondary-api-list::-webkit-scrollbar-thumb {
  background: #ddd;
  border-radius: 4px;
}
.sec-api-form::-webkit-scrollbar {
  width: 4px;
}
.sec-api-form::-webkit-scrollbar-thumb {
  background: #ddd;
  border-radius: 4px;
}
.api-fab-panel::-webkit-scrollbar {
  width: 3px;
}
.api-fab-panel::-webkit-scrollbar-thumb {
  background: #ddd;
  border-radius: 3px;
}



/* ===== dw-korean-patch ===== */

/* DECRYPT WIDGET — KOREAN GRAY-WHITE REDESIGN PATCH */
.dw-stage {
  background: radial-gradient(ellipse at 68% 0%, rgba(255,255,255,0.82) 0%, transparent 52%), linear-gradient(158deg, #f6f4f1 0%, #ede9e4 54%, #f2ede9 100%) !important;
  border: 1px solid rgba(206,194,182,0.52) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.96), 0 14px 38px rgba(145,125,105,0.14), 0 4px 10px rgba(115,98,82,0.09) !important;
}
.dw-stage::before {
  background: linear-gradient(180deg, #ddd6ce, #cfc8c0) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.66), 0 1.5px 0 rgba(0,0,0,0.052) !important;
}
.dw-stage::after {
  background: linear-gradient(180deg, #ebe6e1, #dedbd3) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.76), inset 0 -6px 14px rgba(0,0,0,0.022) !important;
}
.dw-ribbon {
  background: linear-gradient(180deg, #ddd7cf, #d0c9c0) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.65), 0 2px 0 rgba(0,0,0,0.052) !important;
}
.dw-frame {
  background: repeating-linear-gradient(180deg, rgba(172,155,132,0.068) 0 1px, transparent 1px 20px), linear-gradient(180deg, #ffffff 0%, #faf8f5 100%) !important;
  border: 1px solid rgba(190,174,152,0.60) !important;
  box-shadow: inset 0 1px 0 rgba(255,254,251,1), inset 0 -4px 10px rgba(152,132,108,0.052), 0 6px 18px rgba(118,98,76,0.088) !important;
}
.dw-frame::before {
  background: linear-gradient(180deg, #d6cfc8, #c9c2ba) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.52), 0 2px 6px rgba(0,0,0,0.088) !important;
}
.dw-main-sheet, .dw-sub-sheet {
  background: repeating-linear-gradient(180deg, rgba(162,146,122,0.070) 0 1px, transparent 1px 20px), linear-gradient(180deg, rgba(255,254,251,0.97), rgba(252,250,246,0.98)) !important;
  border: 1px solid rgba(184,168,144,0.40) !important;
  box-shadow: inset 0 1px 0 rgba(255,254,250,0.98) !important;
}
/* ── LAYOUT FIX: give cipher and answer more vertical room ── */
.dw-frame { height: 226px !important; }
.dw-monitor { overflow: hidden !important; }
.dw-main-sheet.dw-card-main { flex: 1.08 1 0 !important; min-height: 0 !important; overflow: hidden !important; }
.dw-card-body { overflow-y: auto !important; }
.dw-sub-sheet.dw-card-sub { flex: 0.92 1 0 !important; min-height: 72px !important; overflow: hidden !important; }
.dw-sub-body { overflow-y: auto !important; }
.dw-answer { overflow: visible !important; overflow-wrap: anywhere !important; word-break: break-word !important; color: #2c211a !important; }
.dw-answer small { overflow-wrap: anywhere !important; white-space: normal !important; color: #6c584a !important; }
.dw-card-body, .dw-sub-body { color: #3c2f22 !important; }
.dw-sub-body { color: #4c3d30 !important; }
.dw-card-kicker { color: #7c6448 !important; }
.dw-status-dot { background: #b6a68c !important; box-shadow: 0 0 0 3px rgba(182,166,140,0.18) !important; }
.dw-placeholder { color: #9c8772 !important; }
.dw-persona-badge, .dw-mode-badge, .dw-tiny-btn {
  background: linear-gradient(180deg, rgba(255,253,250,0.95), rgba(245,240,234,0.95)) !important;
  border: 1px solid rgba(182,166,142,0.50) !important;
  color: #5c4a34 !important;
  box-shadow: inset 0 1px 0 rgba(255,254,250,0.97), 0 1px 0 rgba(80,60,34,0.09) !important;
}
.dw-orbit {
  right: 12px !important; top: 10px !important;
  width: 28px !important; height: 28px !important; border-radius: 50% !important;
  background: rgba(240,236,230,0.95) !important;
  border: 1px solid rgba(188,172,152,0.66) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.88), 0 2px 5px rgba(0,0,0,0.076) !important;
  color: #6c5848 !important; display: flex !important; align-items: center !important;
  justify-content: center !important; padding: 0 !important; font-size: 0 !important;
  transition: background 0.15s ease, transform 0.18s cubic-bezier(0.34,1.56,0.64,1) !important;
}
.dw-orbit::before, .dw-orbit::after { display: none !important; content: none !important; }
.dw-orbit svg { display: block !important; width: 14px !important; height: 14px !important; color: #6c5848 !important; pointer-events: none !important; }
.dw-orbit:hover { background: rgba(232,226,218,0.98) !important; }
.dw-orbit:active { transform: scale(0.93) rotate(45deg) !important; }
.dw-tool-icon, .dw-tool-pill, .dw-tool-send { text-shadow: none !important; }
.dw-tool-icon { background: radial-gradient(circle at 38% 32%, #f5f1eb, #e4ddd6) !important; border: 1px solid rgba(186,170,148,0.66) !important; color: #5c4a34 !important; box-shadow: inset 0 1px 0 rgba(255,255,255,0.84), 0 3px 0 rgba(148,132,108,0.17) !important; }
.dw-tool-pill { background: linear-gradient(180deg, #f4f0ea 0%, #e9e3db 100%) !important; border: 1px solid rgba(186,170,148,0.66) !important; color: #5c4a34 !important; box-shadow: inset 0 1px 0 rgba(255,255,255,0.84), 0 4px 0 rgba(148,132,108,0.17) !important; }
.dw-tool-send { background: linear-gradient(180deg, #bead9f 0%, #a08c7e 100%) !important; border: 1px solid rgba(148,128,112,0.66) !important; color: #faf5f0 !important; box-shadow: inset 0 1px 0 rgba(255,255,255,0.28), 0 4px 0 rgba(92,74,58,0.17) !important; text-shadow: 0 1px 0 rgba(0,0,0,0.18) !important; }
.dw-tool-icon:active, .dw-tool-pill:active, .dw-tool-send:active { transform: translateY(2px) !important; box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 1px 0 rgba(148,132,108,0.17) !important; }
.mini-decrypt-secret { background: linear-gradient(158deg, #f2eee8 0%, #e5e0d9 100%) !important; box-shadow: 0 1px 6px rgba(115,96,76,0.11) !important; }
.mini-ds-dock { background: linear-gradient(180deg, #ddd8d2, #c9c3bb) !important; border: 1px solid rgba(184,168,144,0.68) !important; }
.mini-ds-dock::before, .mini-ds-dock::after { background: rgba(202,186,162,0.86) !important; }
.photo-widget-decrypt-secret { border-radius: 20px !important; box-shadow: 0 8px 26px rgba(96,76,56,0.13) !important; }
.dw-stage { border-radius: 20px !important; }
@keyframes dw-line-appear { from { opacity: 0; transform: translateX(-8px); } to { opacity: 1; transform: translateX(0); } }
@keyframes dw-answer-appear { from { opacity: 0; transform: translateY(6px); filter: blur(3px); } to { opacity: 1; transform: translateY(0); filter: blur(0); } }
@keyframes dw-placeholder-appear { from { opacity: 0; } to { opacity: 1; } }
.dw-morse-line, .dw-poem-line { animation: dw-line-appear 0.38s cubic-bezier(0.34,1.56,0.64,1) both !important; }
.dw-morse-line:nth-child(1), .dw-poem-line:nth-child(1) { animation-delay: 0.04s !important; }
.dw-morse-line:nth-child(2), .dw-poem-line:nth-child(2) { animation-delay: 0.17s !important; }
.dw-morse-line:nth-child(3), .dw-poem-line:nth-child(3) { animation-delay: 0.30s !important; }
.dw-morse-line:nth-child(4), .dw-poem-line:nth-child(4) { animation-delay: 0.43s !important; }
.dw-answer { animation: dw-answer-appear 0.46s ease both !important; }
.dw-placeholder { animation: dw-placeholder-appear 0.5s ease both !important; }



