.mt-modal{position:fixed;inset:0;z-index:99999;background:rgba(10,10,10,.38);backdrop-filter:blur(12px);display:none;align-items:center;justify-content:center;padding:14px;font-family:'Montserrat','Noto Sans SC',sans-serif;}
