/* ===== style-22 ===== */

/* 陪读按钮激活态 */
.companion-btn-active { background: #1a1a1a !important; color: #fff !important; }
/* 段落金色下划线 — 用于 novel reader 的内联段落 */
.companion-highlighted-para {
  text-decoration: underline;
  text-decoration-color: #c9971c;
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
}
/* ─── 便签卡片 ─── */
.companion-sticky {
  position: relative;
  background: #fffef5;
  border: 1px solid #e8d98a;
  border-radius: 3px 12px 12px 12px;
  padding: 14px 16px 12px 14px;
  margin: 10px 0 18px 0;
  box-shadow: 0 2px 12px rgba(180,150,30,0.10), 0 1px 3px rgba(0,0,0,0.07);
  line-height: 1.65;
  color: #3a2e00;
  animation: cStickyIn 0.3s cubic-bezier(0.22,1,0.36,1);
  overflow: visible;
}
/* 折角效果 */
.companion-sticky::before {
  content: '';
  position: absolute;
  top: -1px; left: -1px;
  width: 0; height: 0;
  border-style: solid;
  border-width: 18px 18px 0 0;
  border-color: #f0f0f0 transparent transparent transparent;
}
/* 顶部金色线条 */
.companion-sticky::after {
  content: '';
  position: absolute;
  top: 0; left: 18px; right: 0;
  height: 2px;
  background: linear-gradient(90deg, #e6b830 0%, #f5d76e 100%);
  border-radius: 0 12px 0 0;
}
@keyframes cStickyIn {
  from { opacity:0; transform:translateY(-8px) scale(0.97); }
  to   { opacity:1; transform:translateY(0) scale(1); }
}
/* 便签头部：头像 + 名字 */
.companion-sticky-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  padding-left: 4px;
}
.companion-sticky-avatar {
  width: 26px; height: 26px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
  box-shadow: 0 0 0 2px #e6b830;
}
.companion-sticky-avatar-placeholder {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: #1a1a1a;
  color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 700;
  flex-shrink: 0;
  box-shadow: 0 0 0 2px #e6b830;
}
.companion-sticky-name {
  font-size: 11px;
  font-weight: 700;
  color: #a07800;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}
.companion-sticky-dot {
  width: 4px; height: 4px; border-radius: 50%;
  background: #e6b830; flex-shrink: 0;
}
.companion-sticky-body {
  font-size: 13px;
  padding-left: 4px;
}
/* 加载中状态 */
.companion-sticky-loading .companion-sticky-body {
  color: #bba040;
  font-style: italic;
  font-size: 12px;
}
/* TXT 陪读便签内联区域（滚动模式，注入到章节底部） */
#txtStickyInline {
  margin-top: 0;
  padding-bottom: 1px;
}



/* ===== style-23 ===== */

/* ── Wiggle animation (edit mode) ── */
@keyframes iPhoneWiggle {
  0%   { transform: rotate(-1.8deg); }
  50%  { transform: rotate(0deg); }
  100% { transform: rotate(1.8deg); }
}
.home-edit-active [data-drag-id] {
  animation: iPhoneWiggle 0.22s ease-in-out infinite alternate !important;
  cursor: grab !important;
}
/* item being dragged: invisible placeholder in place */
[data-drag-id].is-dragging-source {
  opacity: 0 !important;
  animation: none !important;
  pointer-events: none !important;
  /* Keep its locked w/h (set inline) so the hole stays the right size */
}
/* The floating drag ghost — absolutely positioned, no size change */
#iph-drag-ghost {
  position: fixed;
  z-index: 999999;
  pointer-events: none;
  display: none;
  /* NO width/height set here — set by JS from actual element rect */
  /* NO transform scale — iPhone keeps native size during drag */
  transform-origin: top left;
  will-change: left, top;
  animation: none !important;
}
/* ── Alignment guides while dragging ── */
#iph-align-overlay {
  position: fixed;
  inset: 0;
  z-index: 999997;
  pointer-events: none;
  display: none;
}
#iph-align-overlay .iph-align-line {
  position: absolute;
  display: none;
  background: rgba(26,26,26,0.9);
  box-shadow: 0 0 0 1px rgba(255,255,255,0.22), 0 0 10px rgba(26,26,26,0.16);
  border-radius: 999px;
}
#iph-align-overlay .iph-align-line.v {
  width: 2px;
}
#iph-align-overlay .iph-align-line.h {
  height: 2px;
}
/* ── Done button (top-right, iPhone-style) ── */
#iph-edit-done {
  position: absolute;
  top: 46px;
  right: 12px;
  z-index: 99998;
  background: rgba(255,255,255,0.92);
  color: #000;
  border: none;
  border-radius: 14px;
  padding: 6px 16px;
  font-size: 14px;
  font-weight: 600;
  display: none;
  cursor: pointer;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 2px 12px rgba(0,0,0,0.18);
  letter-spacing: 0.2px;
  font-family: -apple-system, sans-serif;
}
#iph-edit-enter {
  position: relative;
  z-index: 99998;
  background: rgba(0,0,0,0.15);
  color: inherit;
  border: none;
  border-radius: 6px;
  width: 20px;
  height: 20px;
  font-size: 9px;
  text-align: center;
  padding: 0;
  cursor: pointer;
  font-family: -apple-system, sans-serif;
  opacity: 0.55;
  transition: opacity 0.15s, transform 0.15s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  vertical-align: middle;
  flex-shrink: 0;
}
#iph-edit-enter:active { opacity: 1; transform: scale(0.88); }
.home-edit-active #iph-edit-enter { display: none; }
/* ── Prevent page swipe while dragging ── */
.iph-dragging .home-pages-wrapper {
  transition: none !important;
  pointer-events: none !important;
}
/* pages need position:relative as origin for absolute children */
#homePage1, #homePage2, #homePage3, #homeSharedDock,
.home-page-extra, .home-extra-dock {
  position: relative;
}
/* Saved-position items are absolute within their page/dock */
[data-drag-id].iph-placed {
  position: absolute !important;
  margin: 0 !important;
  flex-shrink: 0 !important;
  z-index: 20;
  /* width & height are set inline by JS — do NOT set them here */
}
/* Freeze inner icon boxes — prevent 100%/aspect-ratio from reflowing.
   Actual sizes are set inline by JS depending on whether in dock or page. */
[data-drag-id].iph-placed .home-app-icon-box,
[data-drag-id].iph-placed .home-dock-app-box,
[data-drag-id].iph-placed .ig-music-icon-box {
  flex-shrink: 0 !important;
  /* width/height set inline by JS */
}
/* Freeze widgets that use width:100% or flex sizing */
[data-drag-id].iph-placed.memo-widget,
[data-drag-id].iph-placed.ig-widget,
[data-drag-id].iph-placed.family-widget,
[data-drag-id].iph-placed.home-calendar-widget,
[data-drag-id].iph-placed.home-photo-widget,
[data-drag-id].iph-placed.couple-space-widget,
[data-drag-id].iph-placed.photo-widget-livechat,
[data-drag-id].iph-placed.photo-widget-couple-calendar,
[data-drag-id].iph-placed.photo-widget-decrypt-secret {
  /* width & height locked inline by JS — just ensure box-sizing is right */
  box-sizing: border-box !important;
  max-width: none !important;
  min-width: 0 !important;
  min-height: 0 !important;
}



/* ===== style-24 ===== */

