}
.bg-remove-sub {
  font-size: 13px; color: #666;
  text-align: center; margin-bottom: 20px;
  line-height: 1.5;
}
.bg-remove-toggle-row {
  display: flex; align-items: center; justify-content: space-between;
  background: #f5f5f5; border-radius: 12px;
