}
.bg-remove-toggle-label {
  font-size: 14px; font-weight: 600; color: #1a1a1a;
}
.bg-remove-toggle-sub {
  font-size: 11px; color: #888; margin-top: 2px;
}
/* Toggle switch */
.ci-toggle {
  position: relative; width: 48px; height: 28px;
  flex-shrink: 0; margin-left: 12px;
}
.ci-toggle input { opacity: 0; width: 0; height: 0; }
.ci-toggle-slider {
  position: absolute; inset: 0;
  background: #ccc; border-radius: 28px;
  cursor: pointer; transition: background 0.2s;
}
.ci-toggle-slider::before {
  content: ''; position: absolute;
  height: 22px; width: 22px;
  left: 3px; top: 3px;
  background: #fff; border-radius: 50%;
  transition: transform 0.2s;
  box-shadow: 0 1px 4px rgba(0,0,0,0.25);
}
.ci-toggle input:checked + .ci-toggle-slider { background: #34c759; }
.ci-toggle input:checked + .ci-toggle-slider::before { transform: translateX(20px); }
.bg-remove-processing {
  display: none; text-align: center;
  color: #666; font-size: 13px;
  margin-bottom: 12px; padding: 8px;
}
.bg-remove-processing.show { display: block; }
.bg-remove-processing-bar {
  height: 3px; background: #e0e0e0; border-radius: 3px;
  margin: 8px 0 4px; overflow: hidden;
}
.bg-remove-processing-fill {
  height: 100%; width: 0%;
  background: linear-gradient(90deg,#34c759,#30d158);
  border-radius: 3px;
  transition: width 0.3s ease;
}
.bg-remove-btns {
  display: flex; gap: 10px;
}
.bg-remove-btn {
  flex: 1; padding: 14px;
  border-radius: 12px; border: none;
  font-size: 15px; font-weight: 600;
  cursor: pointer; transition: opacity 0.15s;
}
.bg-remove-btn:active { opacity: 0.75; }
.bg-remove-btn-cancel {
  background: #f0f0f0; color: #333;
}
.bg-remove-btn-confirm {
  background: #1a1a1a; color: #fff;
}
