/* ═══════════════════════════════════════════════════════
   DECRYPT SECRET WIDGET — Vintage Typewriter
   ═══════════════════════════════════════════════════════ */
.photo-widget-decrypt-secret {
  width: 320px;
  height: 380px;
  position: relative;
  background: transparent;
  border-radius: 26px;
  overflow: hidden;
  box-sizing: border-box;
}
.photo-widget-decrypt-secret .pw-delete-btn { z-index: 8; }
.dw-stage {
  position: absolute;
  left: 0;
  top: 0;
  width: 320px;
  height: 380px;
  transform-origin: top left;
  border-radius: 26px;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% -8%, rgba(255,255,255,0.16), transparent 24%),
    linear-gradient(180deg, #45484b 0%, #313335 46%, #232527 100%);
  border: 1px solid rgba(15,15,15,0.9);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08),
    inset 0 -18px 28px rgba(0,0,0,0.24),
    0 18px 34px rgba(0,0,0,0.22);
}
.dw-stage::before {
  content: '';
  position: absolute;
  left: 22px;
  right: 22px;
  top: 20px;
  height: 18px;
  border-radius: 999px;
  background: linear-gradient(180deg, #151617, #2a2b2e);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08),
    0 2px 0 rgba(0,0,0,0.16);
}
.dw-stage::after {
  content: '';
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  height: 86px;
  border-radius: 22px 22px 18px 18px;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.05), transparent 24%),
    linear-gradient(180deg, #2a2c2e, #17181a);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08),
    inset 0 -14px 20px rgba(0,0,0,0.28);
}
.dw-orbit {
  position: absolute;
  right: 16px;
  top: 48px;
  width: 28px;
  height: 72px;
  border-radius: 14px;
  border: 1px solid rgba(22,20,17,0.9);
  background:
    linear-gradient(180deg, #6d5641 0%, #4b3829 48%, #2d2118 100%);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.14),
    inset 0 -8px 12px rgba(0,0,0,0.24),
    0 6px 14px rgba(0,0,0,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  appearance: none;
  padding: 0;
}
.dw-orbit::before {
  content: '';
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 34% 34%, #f3efe8, #bca58c 58%, #6b523e 100%);
  box-shadow:
    inset 0 2px 0 rgba(255,255,255,0.36),
    0 2px 8px rgba(0,0,0,0.24);
}
.dw-orbit::after {
  content: '';
  position: absolute;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(76,53,34,0.9);
  box-shadow: 0 0 0 2px rgba(255,248,236,0.46);
}
.dw-orbit:active { transform: scale(0.97); }
.dw-aura {
  display: none;
}
.dw-ribbon {
  position: absolute;
  left: 22px;
  right: 54px;
  top: 44px;
  height: 22px;
  border-radius: 999px;
  background:
    linear-gradient(180deg, #1e2022, #36383a 48%, #111214 100%);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08),
    0 3px 0 rgba(0,0,0,0.18);
}
.dw-frame {
  position: absolute;
  left: 34px;
  top: 54px;
  width: 234px;
  height: 206px;
  border-radius: 12px 12px 18px 18px;
  background:
    linear-gradient(180deg, #f2e7cd 0%, #e9dbc0 100%);
  border: 1px solid rgba(108,84,56,0.95);
  box-shadow:
    inset 0 1px 0 rgba(255,252,245,0.98),
    inset 0 -8px 18px rgba(160,132,96,0.12),
    0 8px 18px rgba(0,0,0,0.14);
  padding: 14px 14px 12px;
}
.dw-frame::before {
  content: '';
  position: absolute;
  left: -16px;
  right: -16px;
  top: -14px;
  height: 20px;
  border-radius: 999px;
  background:
    linear-gradient(180deg, #26282a, #0f1011 100%);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08),
    0 3px 8px rgba(0,0,0,0.18);
  pointer-events: none;
}
.dw-frame::after {
  content: '';
  position: absolute;
  left: -18px;
  right: -18px;
  top: -13px;
  height: 22px;
  background:
    radial-gradient(circle at 11px 11px, #f2eee7 0, #b89f83 52%, #694f39 100%),
    radial-gradient(circle at calc(100% - 11px) 11px, #f2eee7 0, #b89f83 52%, #694f39 100%);
  pointer-events: none;
}
.dw-monitor {
