.dw-placeholder {
  color: #7e6550;
  font-family: 'Courier Prime','Courier New',monospace;
}
.dw-morse-lines {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  overflow: hidden;
}
.dw-morse-line,
.dw-poem-line {
  display: block;
  white-space: normal;
  overflow-wrap: anywhere;
  max-width: 100%;
}
.dw-toolbar {
  position: absolute;
  left: 20px;
  right: 20px;
  bottom: 22px;
  z-index: 2;
  display: grid;
  grid-template-columns: 44px 1fr 84px;
  gap: 10px;
  align-items: center;
  height: 52px;
}
.dw-tool-icon,
.dw-tool-pill,
.dw-tool-send {
  appearance: none;
  border: 1px solid rgba(16,15,14,0.92);
  font-family: 'Courier Prime','Courier New',monospace;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: #f7edd7;
  text-shadow: 0 1px 0 rgba(0,0,0,0.28);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08),
    0 4px 0 rgba(12,12,12,0.3);
}
.dw-tool-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 35% 30%, #5c6063, #17181a 72%);
  font-size: 15px;
  line-height: 1;
}
.dw-tool-pill {
  height: 52px;
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 22%, rgba(255,255,255,0.08), transparent 30%),
    linear-gradient(180deg, #5e6165 0%, #28292b 54%, #111214 100%);
  justify-content: flex-start;
  padding: 0 18px;
  font-size: 9.2px;
  letter-spacing: 0.12px;
}
.dw-tool-send {
  height: 52px;
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 18%, rgba(255,255,255,0.12), transparent 32%),
    linear-gradient(180deg, #83633f 0%, #563b22 56%, #2f2114 100%);
  font-size: 9.8px;
  font-weight: 700;
  color: #f7ebd5;
  letter-spacing: 0.12px;
}
.dw-tool-icon:active,
.dw-tool-pill:active,
.dw-tool-send:active {
  transform: translateY(2px);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08),
    0 2px 0 rgba(12,12,12,0.26);
}
.dw-status-dot {
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #8d5f30;
  margin-right: 6px;
  box-shadow: 0 0 0 3px rgba(141,95,48,0.14);
}
[data-drag-id].iph-placed.photo-widget-decrypt-secret {
  box-sizing: border-box !important;
  max-width: none !important;
  min-width: 0 !important;
  min-height: 0 !important;
  overflow: hidden !important;
}
.home-edit-active .photo-widget-decrypt-secret .pw-delete-btn { display: flex; }
.photo-widget-decrypt-secret.is-dragging-source .pw-delete-btn { display: none !important; }
.home-edit-active [data-drag-id].iph-placed.photo-widget-decrypt-secret .widget-resize-handle { display: block; }
.mini-decrypt-secret {
  height: 100%;
  border-radius: 16px;
  overflow: hidden;
  background:
    linear-gradient(180deg, #474a4d 0%, #242628 100%);
  box-shadow: 0 1px 8px rgba(0,0,0,0.14);
  padding: 7px;
  box-sizing: border-box;
  position: relative;
}
.mini-decrypt-secret img { display: none !important; }
.mini-decrypt-secret::before {
  content: '';
  position: absolute;
  left: 11px;
  right: 11px;
  top: 10px;
  height: 8px;
  border-radius: 999px;
  background: #141517;
}
.mini-decrypt-secret::after {
  content: '';
  position: absolute;
  left: 8px;
  right: 8px;
  bottom: 8px;
  height: 24px;
  border-radius: 10px 10px 8px 8px;
  background:
    linear-gradient(180deg, #2c2d2f, #18191b);
  border: 1px solid rgba(16,15,14,0.92);
}
.mini-ds-screen {
  position: absolute;
  left: 14px;
  right: 18px;
  top: 18px;
  height: 24px;
  border-radius: 5px;
  background: linear-gradient(180deg, #f2e7cc, #e5d5b6);
  border: 1px solid rgba(118,87,55,0.76);
}
.mini-ds-screen::before,
.mini-ds-screen::after {
  content: '';
  position: absolute;
  left: 8px;
  right: 8px;
  background: rgba(89,63,37,0.28);
}
.mini-ds-screen::before {
  top: 8px;
  height: 3px;
}
.mini-ds-screen::after {
  top: 14px;
  right: 24px;
  height: 2px;
}
.mini-ds-stem {
  position: absolute;
  left: 42px;
  top: 42px;
  width: 20px;
  height: 5px;
  border-radius: 999px;
  background: rgba(26,27,29,0.9);
}
.mini-ds-dock {
  position: absolute;
  left: 15px;
  right: 15px;
  bottom: 15px;
  height: 12px;
  border-radius: 999px;
  background: linear-gradient(180deg, #5c5f63, #151618);
  border: 1px solid rgba(15,15,14,0.92);
}
.mini-ds-dock::before,
.mini-ds-dock::after {
  content: '';
  position: absolute;
  top: 3px;
  height: 4px;
  border-radius: 999px;
  background: rgba(238,225,199,0.86);
}
.mini-ds-dock::before {
  left: 8px;
  width: 13px;
}
.mini-ds-dock::after {
  right: 8px;
  width: 10px;
}
#dwPersonaSheet,
#dwMorseSheet,
#dwSettingsSheet {
  position: fixed;
  inset: 0;
  z-index: 499999;
  display: none;
  align-items: flex-end;
  justify-content: center;
  background: rgba(0,0,0,0.34);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
#dwPersonaSheet.open,
#dwMorseSheet.open,
#dwSettingsSheet.open { display: flex; }
.dw-sheet {
  width: 100%;
  max-width: 430px;
  max-height: 78vh;
  overflow-y: auto;
  padding: 16px 16px 34px;
  border-radius: 26px 26px 0 0;
  background:
    radial-gradient(circle at 16% 12%, rgba(255,255,255,0.92), transparent 24%),
    linear-gradient(180deg, rgba(255,250,252,0.99), rgba(249,241,244,0.99));
  box-shadow: 0 -10px 40px rgba(0,0,0,0.14);
  font-family: 'Apple SD Gothic Neo','Noto Sans KR',-apple-system,sans-serif;
}
.dw-sheet-handle {
  width: 38px;
  height: 4px;
  border-radius: 999px;
  background: rgba(204,187,192,0.92);
  margin: 0 auto 14px;
}
.dw-sheet-title {
  font-size: 15px;
  font-weight: 700;
  color: #5c4c50;
  text-align: center;
  letter-spacing: 0.3px;
}
.dw-sheet-sub {
  margin-top: 4px;
  font-size: 11px;
  text-align: center;
  color: #a58d94;
  line-height: 1.45;
}
.dw-persona-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 16px;
}
.dw-persona-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 15px;
  border: 1px solid rgba(227,211,216,0.95);
  background: rgba(255,255,255,0.74);
  cursor: pointer;
}
.dw-persona-item.sel {
  border-color: rgba(214,176,188,0.98);
  background: rgba(255,244,247,0.96);
}
.dw-persona-avatar,
.dw-persona-avatar-ph {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}
.dw-persona-avatar-ph {
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(236,227,231,0.96);
  color: #92767d;
  font-weight: 700;
}
.dw-persona-main {
  flex: 1;
  min-width: 0;
}
.dw-persona-name {
  font-size: 13px;
  font-weight: 700;
  color: #59484c;
}
.dw-persona-desc {
  margin-top: 2px;
  font-size: 10px;
  line-height: 1.45;
  color: #ae979d;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.dw-check {
  color: #d28d9f;
  font-size: 14px;
}
.dw-sheet-btn,
.dw-inline-btn {
  appearance: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
}
.dw-sheet-btn {
  width: 100%;
  margin-top: 14px;
  height: 44px;
  border-radius: 15px;
  background: linear-gradient(180deg, #f0dde3, #ead3da);
  color: #604d52;
  font-size: 14px;
  font-weight: 700;
}
.dw-inline-btn {
  height: 34px;
  padding: 0 14px;
  border-radius: 12px;
  background: rgba(255,255,255,0.8);
  border: 1px solid rgba(224,206,212,0.95);
  color: #7e666e;
  font-size: 12px;
  font-weight: 700;
}
.dw-inline-btn.primary {
  background: linear-gradient(180deg, #f0d3dc, #e9c1cd);
  color: #5d434a;
}
.dw-setting-group {
  margin-top: 16px;
  padding: 14px;
  border-radius: 18px;
  background: rgba(255,255,255,0.76);
  border: 1px solid rgba(228,211,217,0.95);
}
.dw-setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
}
.dw-setting-row + .dw-setting-row {
  border-top: 1px solid rgba(233,220,224,0.95);
}
.dw-setting-label {
  font-size: 12px;
  font-weight: 700;
  color: #625257;
}
.dw-setting-hint {
  margin-top: 2px;
  font-size: 10px;
  line-height: 1.45;
  color: #ab959b;
}
.dw-setting-input,
.dw-setting-select {
  width: 118px;
  height: 34px;
  border-radius: 12px;
  border: 1px solid rgba(220,202,208,0.98);
  background: rgba(255,255,255,0.94);
  color: #655359;
  padding: 0 11px;
  font-size: 12px;
  font-family: inherit;
  outline: none;
}
.dw-setting-actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
.dw-morse-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 16px;
}
.dw-morse-item {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 11px;
  border-radius: 13px;
  background: rgba(255,255,255,0.8);
  border: 1px solid rgba(229,214,219,0.95);
  color: #69575d;
  font-family: 'DM Mono','Courier New',monospace;
  font-size: 11px;
}
.dw-morse-item strong {
  color: #8e7079;
  font-family: 'Apple SD Gothic Neo','Noto Sans KR',-apple-system,sans-serif;
}
/* ═══ Couple Calendar Widget ═══ */
.photo-widget-couple-calendar {
  width: 224px;
  height: 224px;
  position: relative;
  border-radius: 28px;
  overflow: hidden;
  background:
    radial-gradient(circle at 18% 16%, rgba(255,255,255,0.95), transparent 28%),
    radial-gradient(circle at 83% 18%, rgba(232,232,236,0.95), transparent 26%),
    linear-gradient(155deg, rgba(250,250,251,0.98), rgba(229,229,233,0.96));
  border: 1px solid rgba(193,193,199,0.76);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.96), 0 16px 34px rgba(82,82,90,0.15);
  color: #2d2d31;
  box-sizing: border-box;
}
.pw-couple-cal-shell {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.pw-couple-cal-shell::before {
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0.1;
  background-image:
    linear-gradient(90deg, rgba(110,110,118,0.12) 0, rgba(110,110,118,0.12) 1px, transparent 1px),
    linear-gradient(rgba(110,110,118,0.12) 0, rgba(110,110,118,0.12) 1px, transparent 1px);
  background-size: 10px 10px;
  pointer-events: none;
}
.pw-couple-cal-inner {
  width: 224px;
  height: 224px;
  position: absolute;
  left: 0;
  top: 0;
  transform-origin: top left;
  pointer-events: none;
}
.pw-cc-top {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px 10px;
}
.pw-cc-pet {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  box-shadow: inset 0 0 0 1px rgba(210,210,216,0.9);
  display: flex;
  align-items: center;
  justify-content: center;
}
.pw-cc-pet img {
  width: 28px;
  height: 28px;
  object-fit: contain;
}
.pw-cc-pet-sprite {
  width: 28px;
  height: 28px;
  display: block;
  background-repeat: no-repeat;
  background-size: 400% 400%;
  background-position: 33.333% 100%;
  background-image: none;
}
.pw-cc-title {
  text-align: center;
  flex: 1;
  padding-right: 10px;
}
.pw-cc-month {
  font-size: 18px;
  font-weight: 700;
  color: #55555d;
}
.pw-cc-year {
  font-size: 10px;
  color: rgba(96,96,104,0.64);
  margin-top: 2px;
}
.pw-cc-week {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  padding: 0 14px;
  gap: 0;
  font-size: 9px;
  color: rgba(94,94,102,0.66);
  text-align: center;
}
.pw-cc-week span { line-height: 18px; }
.pw-cc-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  grid-auto-rows: 82px;
  padding: 8px 10px 36px;
}
.pw-cc-day {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}
.pw-cc-day.other { opacity: 0.22; }
.pw-cc-day.today .pw-cc-daynum {
  color: #ef8f6d;
  font-weight: 700;
}
.pw-cc-daynum {
  font-size: 12px;
  color: rgba(70,70,78,0.72);
  line-height: 1;
  margin-top: 2px;
}
.pw-cc-icons {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 5px;
  min-height: 60px;
}
.pw-cc-icon-box,
.pw-cc-empty {
  width: 30px;
  height: 30px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
}
.pw-cc-icon-box {
  border: 1px solid rgba(213,213,220,0.92);
  background: transparent;
  overflow: hidden;
}
.pw-cc-icon,
.pw-cc-sprite {
  width: 24px;
  height: 24px;
  display: block;
}
.pw-cc-icon {
  object-fit: contain;
  mix-blend-mode: multiply;
}
.pw-cc-sprite {
  background-repeat: no-repeat;
  background-size: 400% 400%;
}
.pw-cc-empty {
  border: 1px dashed rgba(190,190,196,0.68);
  background: transparent;
}
.pw-cc-foot {
  position: absolute;
  left: 16px;
  right: 16px;
  bottom: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 9px;
  color: rgba(82,82,90,0.64);
  pointer-events: none;
}
.pw-cc-foot strong {
  color: #44444b;
  font-size: 10px;
}
[data-drag-id].iph-placed.photo-widget-couple-calendar {
  box-sizing: border-box !important;
  max-width: none !important;
  min-width: 0 !important;
  min-height: 0 !important;
}
.home-edit-active .photo-widget-couple-calendar .pw-delete-btn { display: flex; }
.photo-widget-couple-calendar.is-dragging-source .pw-delete-btn { display: none !important; }
.home-edit-active [data-drag-id].iph-placed.photo-widget-couple-calendar .widget-resize-handle { display: block; }
.mini-couple-calendar {
  height: 100%;
  border-radius: 11px;
  background: linear-gradient(155deg,#fafafb,#ededf2);
  box-shadow: 0 1px 6px rgba(0,0,0,.07);
  overflow: hidden;
  padding: 5px;
  box-sizing: border-box;
}
.mini-cc-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 3px;
  margin-bottom: 4px;
}
.mini-cc-pet,
.mini-cc-tree {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #e9e5e2;
}
.mini-cc-tree { border-radius: 4px 4px 2px 2px; width: 10px; height: 14px; }
.mini-cc-title { flex: 1; display: flex; flex-direction: column; gap: 2px; align-items: center; }
.mini-cc-m1,
.mini-cc-m2 {
  background: #d6d6dd;
  border-radius: 999px;
}
.mini-cc-m1 { width: 22px; height: 4px; }
.mini-cc-m2 { width: 15px; height: 3px; opacity: 0.8; }
.mini-cc-week {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  font-size: 4px;
  color: #9a9aa1;
  text-align: center;
  margin-bottom: 2px;
}
.mini-cc-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px;
}
.mini-cc-cell {
  height: 14px;
  border-radius: 6px;
  background: rgba(255,255,255,0.45);
  position: relative;
}
.mini-cc-cell i {
  position: absolute;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #f7c7d4;
  left: 4px;
  top: 3px;
}
.mini-cc-cell i.b {
  background: #b9d8f7;
  top: 8px;
}
.mini-cc-cell i.a {
  background: #ffd76a;
}
/* ═══ PERSONA PICKER SHEET ═══ */
#lcwPersonaSheet {
  position: fixed; inset: 0; z-index: 399999;
  background: rgba(0,0,0,0.38); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
  display: none; align-items: flex-end; justify-content: center;
}
#lcwPersonaSheet.open { display: flex; }
.lcw-ps-inner {
  background: #fff; border-radius: 22px 22px 0 0;
  padding: 16px 16px 40px; width: 100%; max-width: 420px;
  max-height: 72vh; overflow-y: auto;
}
.lcw-ps-handle { width: 36px; height: 4px; background: #e0e0e0; border-radius: 2px; margin: 0 auto 14px; }
.lcw-ps-title { font-size: 15px; font-weight: 700; color: #111; margin-bottom: 14px; text-align: center; font-family: -apple-system,sans-serif; }
.lcw-pi {
  display: flex; align-items: center; gap: 11px;
  padding: 10px 12px; border-radius: 12px; cursor: pointer; transition: background .12s;
}
.lcw-pi:active { background: #f5f5f7; }
.lcw-pi.sel { background: #f0f0f8; }
.lcw-pi img { width: 40px; height: 40px; border-radius: 50%; object-fit: cover; border: 1px solid #e5e5ea; flex-shrink: 0; }
.lcw-pi-av { width: 40px; height: 40px; border-radius: 50%; background: #e8e8ee; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700; color: #999; flex-shrink: 0; }
.lcw-pi-name { font-size: 14px; font-weight: 700; color: #1a1a1a; }
.lcw-pi-sub { font-size: 11px; color: #bbb; margin-top: 2px; }
.lcw-pi-chk { color: #635bff; font-size: 15px; display: none; margin-left: auto; }
.lcw-pi.sel .lcw-pi-chk { display: block; }
.lcw-ps-cancel { width: 100%; padding: 14px; border: none; border-radius: 14px; background: #f0f0f5; color: #333; font-size: 15px; font-weight: 600; cursor: pointer; margin-top: 12px; font-family: -apple-system,sans-serif; }
/* ═══ FLOATING POPUP ═══ */
#lcw-float-popup {
  position: fixed; z-index: 9999990;
  width: 310px; height: 480px;
  min-width: 240px; min-height: 320px;
  border-radius: 22px;
  background: rgba(251,251,253,0.98);
  box-shadow: 0 10px 44px rgba(0,0,0,0.20), 0 0 0 0.5px rgba(0,0,0,0.07);
  backdrop-filter: blur(28px); -webkit-backdrop-filter: blur(28px);
  display: none; flex-direction: column; overflow: hidden;
  font-family: 'Apple SD Gothic Neo','Noto Sans KR',-apple-system,sans-serif;
  bottom: 90px; right: 16px; touch-action: none;
  transition: box-shadow .2s;
  resize: none; /* custom resize handles */
}
#lcw-float-popup.visible { display: flex; }
#lcw-float-popup:active { box-shadow: 0 16px 56px rgba(0,0,0,0.26), 0 0 0 0.5px rgba(0,0,0,0.08); }
/* Resize handle on corner */
.lcw-fp-resize-handle {
  position: absolute; right: 0; bottom: 0;
  width: 34px; height: 34px; cursor: se-resize; z-index: 10;
  display: flex; align-items: flex-end; justify-content: flex-end;
  padding: 7px;
}
.lcw-fp-resize-handle::after {
  content: ''; display: block;
  width: 14px; height: 14px;
  border-right: 2.5px solid rgba(0,0,0,0.40);
  border-bottom: 2.5px solid rgba(0,0,0,0.40);
  border-radius: 0 0 4px 0;
}
/* PiP button */
.lcw-fp-pip-btn {
  width: 24px; height: 24px; border-radius: 50%; background: #f2f2f7;
  border: none; display: flex; align-items: center; justify-content: center;
  cursor: pointer; font-size: 10px; color: #888; flex-shrink: 0; margin-right: 2px;
}
.lcw-fp-pip-btn:active { background: #e5e5ea; }
/* New two-card float layout */
.lcw-fp-ai-card {
  flex: 1; min-height: 0;
