/* ===== style-25 ===== */

/* ── Resize handles — visible only in edit mode on iph-placed widgets ── */
.widget-resize-handle {
  position: absolute;
  z-index: 99999;
  display: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}
/* Corner handles */
.widget-resize-handle.corner {
  width: 22px;
  height: 22px;
  background: rgba(255,255,255,0.95);
  border-radius: 50%;
  box-shadow: 0 1px 6px rgba(0,0,0,0.35);
  border: 2px solid rgba(0,0,0,0.12);
}
.widget-resize-handle.corner.br { bottom: -9px; right: -9px; cursor: se-resize; }
.widget-resize-handle.corner.bl { bottom: -9px; left: -9px;  cursor: sw-resize; }
.widget-resize-handle.corner.tr { top: -9px;    right: -9px; cursor: ne-resize; }
.widget-resize-handle.corner.tl { top: -9px;    left: -9px;  cursor: nw-resize; }
/* Edge handles */
.widget-resize-handle.edge {
  background: rgba(255,255,255,0.90);
  border-radius: 4px;
  box-shadow: 0 1px 5px rgba(0,0,0,0.28);
  border: 1.5px solid rgba(0,0,0,0.10);
}
.widget-resize-handle.edge.right  { width: 8px; height: 44px; right: -7px; top: 50%; transform: translateY(-50%); cursor: ew-resize; }
.widget-resize-handle.edge.left   { width: 8px; height: 44px; left: -7px;  top: 50%; transform: translateY(-50%); cursor: ew-resize; }
.widget-resize-handle.edge.bottom { height: 8px; width: 44px; bottom: -7px; left: 50%; transform: translateX(-50%); cursor: ns-resize; }
.widget-resize-handle.edge.top    { height: 8px; width: 44px; top: -7px;    left: 50%; transform: translateX(-50%); cursor: ns-resize; }
/* Show handles only in edit mode on placed widgets */
.home-edit-active [data-drag-id].iph-placed.home-calendar-widget .widget-resize-handle,
.home-edit-active [data-drag-id].iph-placed.memo-widget .widget-resize-handle,
.home-edit-active [data-drag-id].iph-placed.ig-widget .widget-resize-handle,
.home-edit-active [data-drag-id].iph-placed.family-widget .widget-resize-handle,
.home-edit-active [data-drag-id].iph-placed.home-photo-widget .widget-resize-handle,
.home-edit-active [data-drag-id].iph-placed.couple-space-widget .widget-resize-handle,
.home-edit-active [data-drag-id].iph-placed.photo-widget-livechat .widget-resize-handle,
.home-edit-active [data-drag-id].iph-placed.photo-widget-couple-calendar .widget-resize-handle,
.home-edit-active [data-drag-id].iph-placed.photo-widget-decrypt-secret .widget-resize-handle {
  display: block !important;
}
/* While a widget is being resized, hide handles on all OTHER widgets */
body.widget-resizing-active .widget-resize-handle {
  display: none !important;
}
/* But keep handles on the widget currently being resized */
body.widget-resizing-active [data-resize-active] .widget-resize-handle {
  display: block !important;
}
/* Overflow visible so handles protrude outside widget bounds */
.home-edit-active [data-drag-id].iph-placed.home-calendar-widget,
.home-edit-active [data-drag-id].iph-placed.memo-widget,
.home-edit-active [data-drag-id].iph-placed.ig-widget,
.home-edit-active [data-drag-id].iph-placed.family-widget,
.home-edit-active [data-drag-id].iph-placed.home-photo-widget,
.home-edit-active [data-drag-id].iph-placed.couple-space-widget,
.home-edit-active [data-drag-id].iph-placed.photo-widget-livechat,
.home-edit-active [data-drag-id].iph-placed.photo-widget-couple-calendar,
.home-edit-active [data-drag-id].iph-placed.photo-widget-decrypt-secret {
  overflow: visible !important;
}
/* Resize outline on the active widget */
[data-resize-active] {
  outline: 2px solid rgba(255,255,255,0.8) !important;
  outline-offset: 2px !important;
}
/* ── Resize-done button ── */
#widget-resize-done-btn {
  position: fixed;
  top: 54px;
  left: 16px;
  z-index: 99999;
  background: rgba(255,255,255,0.92);
  color: #000;
  border: none;
  border-radius: 14px;
  padding: 7px 18px;
  font-size: 15px;
  font-weight: 600;
  display: none;
  cursor: pointer;
  backdrop-filter: blur(12px);
  box-shadow: 0 2px 12px rgba(0,0,0,0.18);
  letter-spacing: 0.2px;
  font-family: -apple-system, sans-serif;
}



