.iph-folder-overlay { position:fixed;inset:0;z-index:98000;background:rgba(0,0,0,0.55);backdrop-filter:blur(28px);-webkit-backdrop-filter:blur(28px);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;animation:folderOverlayIn 0.22s ease; }
