/* ===== style-28 ===== */

/* ===== 反向查岗 V2 - 主屏幕直接查岗 - Korean Grey-White ===== */
:root {
  --rpc2-bg: #f8f8f9;
  --rpc2-surface: #ffffff;
  --rpc2-border: #e5e5e8;
  --rpc2-text: #1a1a1f;
  --rpc2-subtext: #8a8a95;
  --rpc2-accent: #3a3a4a;
  --rpc2-accent2: #7c7c9a;
  --rpc2-shadow: 0 8px 40px rgba(0,0,0,0.08), 0 2px 8px rgba(0,0,0,0.04);
  --rpc2-shadow-lg: 0 20px 60px rgba(0,0,0,0.12), 0 4px 16px rgba(0,0,0,0.06);
}
/* ===== 锁屏弹窗覆盖层（韩系灰白风格） ===== */
.rpc2-lockscreen-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(175deg, #ffffff 0%, #f5f5f7 40%, #ebebef 100%);
  z-index: 9000;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  animation: rpc2FadeIn 0.4s ease;
}
.rpc2-lockscreen-overlay.open {
  display: flex;
}
@keyframes rpc2FadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes rpc2SlideUp {
  from { transform: translateY(30px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}
@keyframes rpc2PulseGlow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(120, 120, 150, 0.2); }
  50% { box-shadow: 0 0 0 15px rgba(120, 120, 150, 0); }
}
@keyframes rpc2Shake {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-8px); }
  40% { transform: translateX(8px); }
  60% { transform: translateX(-6px); }
  80% { transform: translateX(6px); }
}
/* 锁屏卡片 */
.rpc2-lockscreen-card {
  background: var(--rpc2-surface);
  border-radius: 32px;
  padding: 40px 36px;
  width: 90%;
  max-width: 360px;
  box-shadow: var(--rpc2-shadow-lg);
  text-align: center;
  animation: rpc2SlideUp 0.5s cubic-bezier(0.34, 1.2, 0.64, 1);
  border: 1px solid rgba(0,0,0,0.04);
}
.rpc2-lock-time {
  margin-bottom: 8px;
}
.rpc2-lock-time-display {
  font-size: 56px;
  font-weight: 200;
  color: var(--rpc2-text);
  letter-spacing: -3px;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', sans-serif;
  line-height: 1;
}
.rpc2-lock-date {
  font-size: 13px;
  color: var(--rpc2-subtext);
  font-weight: 500;
  letter-spacing: 0.5px;
  margin-bottom: 24px;
}
.rpc2-lock-avatar-section {
  margin-bottom: 20px;
}
.rpc2-lock-avatar {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  object-fit: cover;
  border: 3px solid var(--rpc2-border);
  margin-bottom: 12px;
}
.rpc2-lock-char-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--rpc2-text);
  margin-bottom: 4px;
}
.rpc2-lock-subtitle {
  font-size: 12px;
  color: var(--rpc2-subtext);
  margin-bottom: 28px;
  line-height: 1.5;
}
/* PIN 输入 */
.rpc2-pin-display {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 24px;
}
.rpc2-pin-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid var(--rpc2-border);
  background: transparent;
  transition: all 0.2s ease;
}
.rpc2-pin-dot.filled {
  background: var(--rpc2-accent);
  border-color: var(--rpc2-accent);
  transform: scale(1.1);
}
.rpc2-pin-dot.error {
  border-color: #e05050;
  background: #e05050;
}
.rpc2-pin-display.shake {
  animation: rpc2Shake 0.4s ease;
}
/* 数字键盘 */
.rpc2-numpad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  max-width: 240px;
  margin: 0 auto;
}
.rpc2-numpad-key {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: var(--rpc2-bg);
  border: 1px solid var(--rpc2-border);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
  margin: 0 auto;
}
.rpc2-numpad-key:hover {
  background: #ececef;
}
.rpc2-numpad-key:active {
  background: var(--rpc2-accent);
  color: #fff;
  transform: scale(0.95);
}
.rpc2-numpad-key .num {
  font-size: 22px;
  font-weight: 400;
  color: var(--rpc2-text);
  line-height: 1;
}
.rpc2-numpad-key:active .num {
  color: #fff;
}
.rpc2-numpad-key .alpha {
  font-size: 8px;
  color: var(--rpc2-subtext);
  letter-spacing: 1px;
  margin-top: 2px;
  text-transform: uppercase;
}
.rpc2-numpad-key.empty {
  background: transparent;
  border: none;
  cursor: default;
}
.rpc2-numpad-key.del {
  background: transparent;
  border: 1px solid var(--rpc2-border);
}
.rpc2-numpad-key.del:hover {
  background: #f0f0f2;
}
/* 取消按钮 */
.rpc2-lock-cancel {
  margin-top: 20px;
  font-size: 12px;
  color: var(--rpc2-subtext);
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px 16px;
  border-radius: 20px;
  transition: all 0.2s;
}
.rpc2-lock-cancel:hover {
  background: var(--rpc2-bg);
  color: var(--rpc2-text);
}
/* ===== 心声弹窗（小型、可拖动、一直显示） ===== */
.rpc2-thought-popup {
  position: fixed;
  top: 80px;
  left: 16px;
  width: 200px;
  background: var(--rpc2-surface);
  border-radius: 16px;
  box-shadow: var(--rpc2-shadow);
  border: 1px solid var(--rpc2-border);
  z-index: 8500;
  display: none;
  flex-direction: column;
  overflow: hidden;
  cursor: move;
  user-select: none;
  transition: box-shadow 0.2s;
}
.rpc2-thought-popup.active {
  display: flex;
}
.rpc2-thought-popup.dragging {
  box-shadow: var(--rpc2-shadow-lg);
}
.rpc2-thought-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--rpc2-bg);
  border-bottom: 1px solid var(--rpc2-border);
}
.rpc2-thought-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}
.rpc2-thought-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--rpc2-text);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.rpc2-thought-status {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 9px;
  color: var(--rpc2-accent2);
}
.rpc2-thought-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #4caf7d;
  animation: rpc2Blink 1.5s ease-in-out infinite;
}
@keyframes rpc2Blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}
.rpc2-thought-body {
  padding: 12px;
  max-height: 120px;
  overflow-y: auto;
}
.rpc2-thought-body::-webkit-scrollbar {
  display: none;
}
.rpc2-thought-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--rpc2-subtext);
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 4px;
}
.rpc2-thought-text {
  font-size: 11px;
  color: var(--rpc2-text);
  line-height: 1.6;
  font-style: italic;
}
.rpc2-thought-loading {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  color: var(--rpc2-subtext);
}
.rpc2-thought-loading-dots {
  display: flex;
  gap: 3px;
}
.rpc2-thought-loading-dots span {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--rpc2-accent2);
  animation: rpc2DotPulse 1.2s ease-in-out infinite;
}
.rpc2-thought-loading-dots span:nth-child(2) { animation-delay: 0.2s; }
.rpc2-thought-loading-dots span:nth-child(3) { animation-delay: 0.4s; }
@keyframes rpc2DotPulse {
  0%, 100% { opacity: 0.3; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1); }
}
/* ===== 虚拟光标（角色点击位置） ===== */
.rpc2-cursor {
  position: fixed;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(230, 230, 232, 0.92);
  pointer-events: none;
  z-index: 8600;
  transform: translate(-50%, -50%);
  display: none;
  transition: box-shadow 0.15s, transform 0.1s, width 0.2s, height 0.2s, border-radius 0.2s, opacity 0.2s;
  box-shadow: 0 2px 12px rgba(0,0,0,0.18), 0 0 0 3px rgba(200,200,205,0.45);
}
.rpc2-cursor.visible {
  display: block;
}
/* 滑动手势状态：稍微拉长像拇指，带运动轨迹感 */
.rpc2-cursor.swipe {
  width: 26px;
  height: 38px;
  border-radius: 13px;
  background: rgba(235, 235, 238, 0.88);
  box-shadow: 0 4px 18px rgba(0,0,0,0.22), 0 0 0 3px rgba(200,200,205,0.35);
}
.rpc2-cursor.tap {
  transform: translate(-50%, -50%) scale(0.78);
  box-shadow: 0 1px 8px rgba(0,0,0,0.14), 0 0 0 10px rgba(200,200,205,0.12);
}
/* 滑动时的尾迹线 */
.rpc2-cursor.swipe::after {
  content: '';
  position: absolute;
  top: 6px;
  left: 50%;
  width: 2px;
  height: 10px;
  border-radius: 2px;
  background: rgba(140, 140, 148, 0.55);
  transform: translateX(-50%);
}
.rpc2-cursor:not(.swipe)::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(160, 160, 168, 0.7);
  transform: translate(-50%, -50%);
}
/* ===== 查岗控制栏（顶部状态栏） ===== */
.rpc2-control-bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: var(--rpc2-surface);
  border-bottom: 1px solid var(--rpc2-border);
  display: none;
  align-items: center;
  padding: 0 16px;
  z-index: 8400;
  box-shadow: 0 2px 8px rgba(0,0,0,0.04);
}
.rpc2-control-bar.active {
  display: flex;
}
.rpc2-control-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--rpc2-border);
  margin-right: 10px;
}
.rpc2-control-info {
  flex: 1;
}
.rpc2-control-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--rpc2-text);
}
.rpc2-control-status {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  color: var(--rpc2-accent2);
}
.rpc2-control-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #4caf7d;
  animation: rpc2Blink 1.5s ease-in-out infinite;
}
.rpc2-control-stop {
  padding: 8px 14px;
  background: #fce8e8;
  color: #e05050;
  border: none;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  gap: 6px;
}
.rpc2-control-stop:hover {
  background: #e05050;
  color: #fff;
}
/* ===== 查岗请求弹窗 ===== */
.rpc2-request-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: var(--rpc2-surface);
  border-radius: 24px;
  padding: 24px;
  width: 90%;
  max-width: 320px;
  box-shadow: var(--rpc2-shadow-lg);
  z-index: 9100;
  display: none;
  animation: rpc2SlideUp 0.4s cubic-bezier(0.34, 1.2, 0.64, 1);
}
.rpc2-request-modal.open {
  display: block;
}
.rpc2-request-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0,0,0,0.4);
  z-index: 9050;
  display: none;
  backdrop-filter: blur(4px);
}
.rpc2-request-backdrop.open {
  display: block;
}
.rpc2-request-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}
.rpc2-request-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--rpc2-border);
}
.rpc2-request-info {
  flex: 1;
}
.rpc2-request-badge {
  display: inline-block;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 20px;
  background: #e8f0fe;
  color: #4a6cf7;
  margin-bottom: 4px;
}
.rpc2-request-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--rpc2-text);
}
.rpc2-request-msg {
  font-size: 12px;
  color: var(--rpc2-subtext);
  line-height: 1.5;
  margin-bottom: 20px;
  padding: 12px;
  background: var(--rpc2-bg);
  border-radius: 12px;
}
.rpc2-request-btns {
  display: flex;
  gap: 10px;
}
.rpc2-request-btn {
  flex: 1;
  padding: 12px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}
.rpc2-request-btn.allow {
  background: var(--rpc2-accent);
  color: #fff;
}
.rpc2-request-btn.allow:hover {
  background: #5a5a7a;
}
.rpc2-request-btn.deny {
  background: var(--rpc2-bg);
  color: var(--rpc2-subtext);
  border: 1px solid var(--rpc2-border);
}
.rpc2-request-btn.deny:hover {
  background: var(--rpc2-border);
}
/* ===== 查岗结束总结弹窗 ===== */
.rpc2-summary-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: var(--rpc2-surface);
  border-radius: 24px;
  padding: 28px;
  width: 90%;
  max-width: 340px;
  box-shadow: var(--rpc2-shadow-lg);
  z-index: 9100;
  display: none;
  animation: rpc2SlideUp 0.4s cubic-bezier(0.34, 1.2, 0.64, 1);
}
.rpc2-summary-modal.open {
  display: block;
}
.rpc2-summary-title {
  font-size: 14px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--rpc2-text);
  text-align: center;
  margin-bottom: 20px;
}
.rpc2-summary-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 16px;
}
.rpc2-summary-stat {
  background: var(--rpc2-bg);
  border-radius: 14px;
  padding: 14px;
  text-align: center;
}
.rpc2-summary-stat-num {
  font-size: 24px;
  font-weight: 700;
  color: var(--rpc2-accent);
}
.rpc2-summary-stat-label {
  font-size: 9px;
  color: var(--rpc2-subtext);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-top: 4px;
}
.rpc2-summary-mood {
  background: var(--rpc2-bg);
  border-radius: 14px;
  padding: 14px;
  margin-bottom: 16px;
}
.rpc2-summary-mood-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--rpc2-subtext);
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 6px;
}
.rpc2-summary-mood-val {
  font-size: 18px;
  font-weight: 600;
  color: var(--rpc2-text);
  display: flex;
  align-items: center;
  gap: 8px;
}
.rpc2-summary-verdict {
  font-size: 12px;
  color: var(--rpc2-text);
  line-height: 1.7;
  font-style: italic;
  padding: 14px;
  background: var(--rpc2-bg);
  border-radius: 14px;
  margin-bottom: 20px;
}
.rpc2-summary-close {
  width: 100%;
  padding: 14px;
  background: var(--rpc2-accent);
  color: #fff;
  border: none;
  border-radius: 14px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.2s;
}
.rpc2-summary-close:hover {
  background: #5a5a7a;
}



/* ===== style-29 ===== */

/* ===== 分步权限弹窗 ===== */
.rpc2-step-perm-backdrop {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.55); z-index: 9200; display: none;
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
}
.rpc2-step-perm-backdrop.open { display: block; }
.rpc2-step-perm-card {
  position: fixed; top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  background: #ffffff; border-radius: 22px;
  padding: 26px 22px; width: 88%; max-width: 330px;
  z-index: 9300; box-shadow: 0 24px 80px rgba(0,0,0,0.22);
  animation: rpc2SlideUp 0.35s cubic-bezier(0.34,1.2,0.64,1);
  display: none; text-align: center;
  border: 1px solid rgba(0,0,0,0.05);
}
.rpc2-step-perm-card.open { display: block; }
.rpc2-step-perm-icon { font-size: 34px; margin-bottom: 10px; }
.rpc2-step-perm-title {
  font-size: 15px; font-weight: 800; color: #1a1a1f;
  margin-bottom: 6px; letter-spacing: -0.3px;
}
.rpc2-step-perm-desc {
  font-size: 12px; color: #8a8a95; line-height: 1.65;
  margin-bottom: 16px;
}
.rpc2-step-perm-char-row {
  display: flex; align-items: center; gap: 10px;
  background: #f5f5f7; border-radius: 14px;
  padding: 10px 14px; margin-bottom: 18px; text-align: left;
}
.rpc2-step-perm-char-avatar {
  width: 38px; height: 38px; border-radius: 50%;
  object-fit: cover; border: 2px solid #e5e5e8; flex-shrink: 0;
}
.rpc2-step-perm-char-name {
  font-size: 13px; font-weight: 700; color: #1a1a1f;
}
.rpc2-step-perm-char-action {
  font-size: 11px; color: #8a8a95; margin-top: 2px;
}
.rpc2-step-perm-btns { display: flex; gap: 10px; }
.rpc2-step-perm-btn {
  flex: 1; padding: 13px; border-radius: 13px;
  font-size: 12px; font-weight: 700; border: none;
  cursor: pointer; transition: all 0.2s; letter-spacing: 0.5px;
  text-transform: uppercase;
}
.rpc2-step-perm-btn.allow {
  background: #3a3a4a; color: #fff;
}
.rpc2-step-perm-btn.allow:hover { background: #5a5a7a; }
.rpc2-step-perm-btn.deny {
  background: #f0f0f2; color: #8a8a95;
  border: 1px solid #e5e5e8;
}
.rpc2-step-perm-btn.deny:hover { background: #e5e5e8; }
/* ===== 跳过当前聊天室按钮 ===== */
.rpc2-skip-btn {
  position: fixed;
  bottom: 72px;
  right: 16px;
  background: rgba(242, 242, 244, 0.94);
  color: #555;
  padding: 9px 18px;
  border-radius: 22px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 8901;
  display: none;
  cursor: pointer;
  border: 1px solid rgba(200, 200, 205, 0.75);
  box-shadow: 0 4px 18px rgba(0,0,0,0.12);
  user-select: none;
  white-space: nowrap;
  transition: background 0.15s, transform 0.1s;
}
.rpc2-skip-btn:active { transform: scale(0.95); background: rgba(225,225,228,0.96); }
.rpc2-skip-btn.show { display: block; }
/* ===== 滑动动作指示条 ===== */
.rpc2-scroll-ind {
  position: fixed; bottom: 72px; left: 50%;
  transform: translateX(-50%);
  background: rgba(26,26,30,0.88); color: #fff;
  padding: 9px 18px; border-radius: 22px;
  font-size: 11px; font-weight: 600;
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  z-index: 8900; display: none; align-items: center; gap: 8px;
  white-space: nowrap; box-shadow: 0 4px 20px rgba(0,0,0,0.25);
}
.rpc2-scroll-ind.show { display: flex; }
.rpc2-scroll-dots { display: flex; gap: 3px; }
.rpc2-scroll-dots span {
  width: 4px; height: 4px; border-radius: 50%;
  background: rgba(255,255,255,0.85);
  animation: rpc2DotPulse 0.9s ease-in-out infinite;
}
.rpc2-scroll-dots span:nth-child(2) { animation-delay: 0.18s; }
.rpc2-scroll-dots span:nth-child(3) { animation-delay: 0.36s; }
/* ===== 心声弹窗上下文标签 ===== */
.rpc2-thought-ctx-label {
  font-size: 9px; font-weight: 700; letter-spacing: 1px;
  text-transform: uppercase; color: var(--rpc2-subtext);
  background: var(--rpc2-bg); border-radius: 8px;
  padding: 3px 8px; margin-bottom: 6px;
  display: inline-flex; align-items: center; gap: 4px;
}
/* ===== 设置面板 V2 权限区块 ===== */
.rpc2-perm-section {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid rgba(255,255,255,0.07);
}



/* ===== style-30 ===== */

/* ===== 角色间私聊 - 韩系灰白风格 ===== */
:root {
  --icc-bg: #f4f4f6;
  --icc-surface: #ffffff;
  --icc-border: #e2e2e6;
  --icc-text: #18181f;
  --icc-sub: #8a8a96;
  --icc-accent: #3a3a50;
  --icc-accent2: #7c7ca0;
  --icc-bubble-a: #ffffff;
  --icc-bubble-b: #3a3a50;
  --icc-bubble-b-text: #ffffff;
  --icc-shadow: 0 24px 80px rgba(0,0,0,0.18), 0 4px 16px rgba(0,0,0,0.08);
}
.icc-backdrop {
  position: fixed; inset: 0;
  background: rgba(10,10,18,0.62);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  z-index: 9500; display: none;
}
.icc-backdrop.open { display: block; }
.icc-modal {
  position: fixed; inset: 0;
  display: none; flex-direction: column;
  z-index: 9600;
  background: var(--icc-bg);
  animation: iccSlideUp 0.38s cubic-bezier(0.34,1.1,0.64,1);
}
.icc-modal.open { display: flex; }
@keyframes iccSlideUp {
  from { transform: translateY(100%); opacity: 0; }
  to   { transform: translateY(0);   opacity: 1; }
}
/* ── 顶部导航栏 ── */
.icc-nav {
  background: var(--icc-surface);
  border-bottom: 1px solid var(--icc-border);
  padding: 14px 16px 12px;
  display: flex; align-items: center; gap: 12px;
  flex-shrink: 0;
}
.icc-nav-back {
  width: 32px; height: 32px; border-radius: 50%;
  background: var(--icc-bg); border: 1px solid var(--icc-border);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; flex-shrink: 0; transition: background 0.15s;
  font-size: 14px; color: var(--icc-text);
}
.icc-nav-back:hover { background: #e8e8ec; }
.icc-nav-title {
  flex: 1;
  display: flex; flex-direction: column; align-items: center;
}
.icc-nav-names {
  font-size: 13px; font-weight: 800; color: var(--icc-text);
  letter-spacing: -0.3px;
}
.icc-nav-tag {
  font-size: 9px; font-weight: 700; letter-spacing: 1.5px;
  text-transform: uppercase; color: var(--icc-sub);
  margin-top: 2px;
}
.icc-nav-avatars {
  display: flex; flex-direction: row-reverse; flex-shrink: 0;
}
.icc-nav-avatar {
  width: 30px; height: 30px; border-radius: 50%;
  border: 2px solid var(--icc-surface);
  object-fit: cover; background: var(--icc-accent);
  margin-left: -8px;
}
.icc-nav-avatar:last-child { margin-left: 0; }
/* ── 聊天内容区 ── */
.icc-chat-area {
  flex: 1; overflow-y: auto; padding: 16px 12px;
  display: flex; flex-direction: column; gap: 10px;
}
.icc-chat-area::-webkit-scrollbar { display: none; }
/* ── 加载状态 ── */
.icc-loading {
  display: flex; flex-direction: column; align-items: center;
  justify-content: center; flex: 1; gap: 14px; color: var(--icc-sub);
}
.icc-loading-dots {
  display: flex; gap: 6px;
}
.icc-loading-dots span {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--icc-accent2);
  animation: iccDotBounce 1.1s ease-in-out infinite;
}
.icc-loading-dots span:nth-child(2) { animation-delay: 0.18s; }
.icc-loading-dots span:nth-child(3) { animation-delay: 0.36s; }
@keyframes iccDotBounce {
  0%,80%,100% { transform: scale(0.7); opacity: 0.5; }
  40%          { transform: scale(1.2); opacity: 1; }
}
.icc-loading-text {
  font-size: 12px; font-weight: 600; letter-spacing: 0.5px;
}
/* ── 消息气泡行 ── */
.icc-msg-row {
  display: flex; align-items: flex-end; gap: 8px;
}
.icc-msg-row.right { flex-direction: row-reverse; }
.icc-msg-avatar {
  width: 34px; height: 34px; border-radius: 50%;
  object-fit: cover; border: 1.5px solid var(--icc-border);
  flex-shrink: 0; background: var(--icc-accent);
}
.icc-msg-col { display: flex; flex-direction: column; max-width: 68%; }
.icc-msg-row.right .icc-msg-col { align-items: flex-end; }
.icc-msg-name {
  font-size: 9px; font-weight: 700; color: var(--icc-sub);
  letter-spacing: 0.5px; margin-bottom: 3px; padding: 0 4px;
}
.icc-bubble {
  padding: 10px 13px;
  border-radius: 18px;
  font-size: 13px; line-height: 1.55;
  word-break: break-word;
}
/* 左侧（对方角色） */
.icc-msg-row:not(.right) .icc-bubble {
  background: var(--icc-bubble-a);
  color: var(--icc-text);
  border: 1px solid var(--icc-border);
  border-bottom-left-radius: 5px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}
/* 右侧（查岗角色，发起方） */
.icc-msg-row.right .icc-bubble {
  background: var(--icc-bubble-b);
  color: var(--icc-bubble-b-text);
  border-bottom-right-radius: 5px;
}
/* ── 情绪标签 ── */
.icc-emotion-tag {
  font-size: 9px; font-weight: 700; letter-spacing: 0.5px;
  color: var(--icc-sub); margin-top: 3px; padding: 0 4px;
  font-style: italic;
}
/* ── 打字中指示 ── */
.icc-typing {
  display: flex; align-items: center; gap: 6px;
  padding: 8px 14px;
  background: var(--icc-bubble-a);
  border: 1px solid var(--icc-border);
  border-radius: 18px; border-bottom-left-radius: 5px;
  width: fit-content;
}
.icc-typing span {
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--icc-sub);
  animation: iccDotBounce 1.1s ease-in-out infinite;
}
.icc-typing span:nth-child(2) { animation-delay: 0.18s; }
.icc-typing span:nth-child(3) { animation-delay: 0.36s; }
/* ── 底部操作栏 ── */
.icc-footer {
  background: var(--icc-surface);
  border-top: 1px solid var(--icc-border);
  padding: 14px 16px calc(14px + env(safe-area-inset-bottom, 0px));
  display: flex; flex-direction: column; gap: 10px; flex-shrink: 0;
}
.icc-footer-desc {
  font-size: 11px; color: var(--icc-sub); text-align: center; line-height: 1.55;
}
.icc-footer-btns {
  display: flex; gap: 10px;
}
.icc-btn {
  flex: 1; padding: 13px; border-radius: 13px;
  font-size: 12px; font-weight: 800; border: none;
  cursor: pointer; transition: all 0.2s; letter-spacing: 0.5px;
  text-transform: uppercase;
}
.icc-btn.primary {
  background: var(--icc-accent); color: #fff;
}
.icc-btn.primary:hover { background: var(--icc-accent2); }
.icc-btn.secondary {
  background: #f0f0f3; color: var(--icc-sub);
  border: 1px solid var(--icc-border);
}
.icc-btn.secondary:hover { background: #e5e5ea; }
.icc-btn:disabled { opacity: 0.5; cursor: not-allowed; }
/* ── 触发提示横幅（在聊天记录查看结束后短暂出现） ── */
.icc-trigger-banner {
  position: fixed; bottom: 80px; left: 50%; transform: translateX(-50%);
  background: #3a3a50; color: #fff;
  padding: 10px 18px; border-radius: 22px;
  font-size: 11px; font-weight: 700;
  box-shadow: 0 6px 24px rgba(0,0,0,0.22);
  display: flex; align-items: center; gap: 10px;
  z-index: 9100; white-space: nowrap;
  animation: iccBannerIn 0.3s ease;
  cursor: pointer;
}
.icc-trigger-banner.hide { display: none; }
@keyframes iccBannerIn {
  from { opacity: 0; transform: translateX(-50%) translateY(16px); }
  to   { opacity: 1; transform: translateX(-50%) translateY(0); }
}
.icc-trigger-banner-close {
  width: 18px; height: 18px; border-radius: 50%;
  background: rgba(255,255,255,0.2);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; cursor: pointer; flex-shrink: 0;
}



/* ===== style-31 ===== */

.couple-home-layout {
  min-height: 100%;
  position: relative;
  padding: 16px;
  box-sizing: border-box;
}
.couple-space-widget {
