    linear-gradient(150deg, rgba(250,250,251,0.98), rgba(227,227,230,0.96));
  border: 1px solid rgba(188,188,194,0.7);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.95),
    0 16px 30px rgba(84,84,92,0.16),
    0 2px 8px rgba(255,255,255,0.55);
