/* ===== style-33 ===== */

/* ── 分区小标题 ── */
.cast-id-section-title {
  font-size: 8.5px;
  font-weight: 800;
  color: rgba(255,255,255,0.25);
  letter-spacing: 2px;
  text-transform: uppercase;
  margin: 18px 22px 10px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.cast-id-section-title::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgba(255,255,255,0.06);
}

/* ── 情绪轨迹 ── */
.cast-id-mood-track {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin: 0 22px 14px;
}
.cast-id-mood-dot {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 4px;
  padding: 4px 10px;
  font-size: 10px;
  color: rgba(255,255,255,0.5);
  white-space: nowrap;
  letter-spacing: 0.3px;
  animation: castDotPop 0.25s both ease;
}
@keyframes castDotPop {
  from { opacity: 0; transform: scale(0.82); }
  to   { opacity: 1; transform: scale(1); }
}
.cast-id-mood-arrow { color: rgba(255,255,255,0.18); font-size: 9px; }

/* ── 竞争 / 配对卡 ── */
.cast-id-rival-card, .cast-id-match-card {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  padding: 13px 15px;
  margin: 0 22px 10px;
  font-size: 11px;
  color: rgba(255,255,255,0.45);
  line-height: 1.65;
}
.cast-id-rival-card   { border-left: 2px solid rgba(255,255,255,0.3); }
.cast-id-match-card   { border-left: 2px solid rgba(255,255,255,0.6); }
.cast-id-rival-name, .cast-id-match-name {
  font-weight: 900;
  font-size: 13px;
  margin-bottom: 4px;
  letter-spacing: -0.2px;
  color: #f0f0f0;
}

/* ── 感情线卡 ── */
.cast-id-rel-card {
  margin: 0 22px 8px !important;
  background: rgba(255,255,255,0.04) !important;
  border-radius: 10px !important;
  padding: 12px 14px !important;
  border: 1px solid rgba(255,255,255,0.07) !important;
}
.cast-id-rel-direction {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;
  color: #e8e8e8;
  margin-bottom: 4px;
}
.cast-id-rel-arrow { font-size: 10px; color: rgba(255,255,255,0.25) !important; }
.cast-id-rel-status { font-size: 10px !important; color: rgba(255,255,255,0.3) !important; margin-bottom: 5px !important; }
.cast-id-rel-summary { font-size: 11px !important; color: rgba(255,255,255,0.38) !important; line-height: 1.55 !important; margin-top: 5px !important; }
.cast-id-rel-heat-bar {
  height: 2px;
  background: rgba(255,255,255,0.08);
  border-radius: 2px;
  margin: 7px 0 2px;
  overflow: hidden;
}
.cast-id-rel-heat-fill {
  height: 100%;
  border-radius: 2px;
  background: rgba(255,255,255,0.55);
  transition: width 0.9s cubic-bezier(0.22,1,0.36,1);
}

/* ── 近期动向 ── */
.cast-id-recent-item {
  background: rgba(255,255,255,0.03);
  border-radius: 8px;
  padding: 9px 12px;
  margin: 0 22px 7px;
  font-size: 11px;
  color: rgba(255,255,255,0.45);
  line-height: 1.55;
  border-left: 2px solid rgba(255,255,255,0.1);
}
.cast-id-recent-item.type-host      { border-left-color: rgba(255,255,255,0.45); }
.cast-id-recent-item.type-character { border-left-color: rgba(255,255,255,0.65); }
.cast-id-recent-item.type-director  { border-left-color: rgba(255,255,255,0.2); }
.cast-id-recent-meta {
  font-size: 8.5px;
  color: rgba(255,255,255,0.22);
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* ── AI 按钮组（2列网格）── */
.cast-id-ai-btn-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin: 0 22px 12px;
}
.cast-id-ai-btn {
  width: 100%;
  padding: 13px 13px 11px;
  background: rgba(255,255,255,0.05);
  color: rgba(255,255,255,0.65);
  border: 1px solid rgba(255,255,255,0.09);
  border-top: 1px solid rgba(255,255,255,0.14);
  border-radius: 10px;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.4px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0;
  transition: background 0.16s, border-color 0.16s, transform 0.12s;
  font-family: inherit;
  text-align: left;
  line-height: 1.5;
  position: relative;
  overflow: hidden;
}
.cast-id-ai-btn:hover {
  background: rgba(255,255,255,0.09);
  border-color: rgba(255,255,255,0.18);
  color: rgba(255,255,255,0.85);
}
.cast-id-ai-btn:active { transform: scale(0.97); opacity: 0.75; }
.cast-id-ai-btn:disabled { opacity: 0.22; cursor: not-allowed; }
.cast-id-ai-btn.active {
  background: rgba(255,255,255,0.14);
  border-color: rgba(255,255,255,0.24);
  color: rgba(255,255,255,0.94);
}
.cast-id-ai-btn-icon { display: none; }

/* ── AI 结果区 ── */
.cast-id-ai-result {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.09);
  border-top: 1px solid rgba(255,255,255,0.15);
  border-radius: 12px;
  padding: 16px 16px;
  margin: 0 22px 12px;
  font-size: 12px;
  color: rgba(255,255,255,0.6);
  line-height: 1.85;
  display: none;
  animation: castFadeUp 0.3s both ease;
}
.cast-id-ai-result.visible { display: block; }
.cast-id-ai-result-title {
  font-size: 8.5px;
  font-weight: 800;
  color: rgba(255,255,255,0.28);
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}



