  gap: 8px;
}
.ent-weibo-quick-grid .ent-btn {
  width: 100%;
}
.ent-fan-channel-wrap {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  gap: 12px;
}
.ent-fan-channel-card,
.ent-dm-card {
  border-radius: 24px;
  border: 1px solid rgba(180,184,192,0.35);
  background: linear-gradient(180deg, rgba(255,255,255,0.96), rgba(247,247,249,0.93));
  box-shadow: 0 16px 32px rgba(25,29,37,0.06);
  overflow: hidden;
}
.ent-fan-channel-head,
.ent-dm-head {
  padding: 14px 16px 12px;
  border-bottom: 1px solid rgba(222,225,230,0.82);
}
.ent-fan-banner {
  margin-top: 10px;
  padding: 11px 12px;
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(245,246,249,0.98), rgba(234,236,241,0.96));
  font-size: calc(10px * var(--fs,1));
  line-height: 1.65;
  color: #373d45;
}
.ent-fan-channel-list,
.ent-dm-thread-list {
  display: flex;
  flex-direction: column;
}
.ent-fan-channel-item,
.ent-dm-thread {
  padding: 14px 16px;
  border-top: 1px solid rgba(222,225,230,0.82);
}
.ent-fan-channel-item:first-child,
.ent-dm-thread:first-child {
  border-top: none;
}
.ent-fan-channel-title {
  font-size: calc(12px * var(--fs,1));
  font-weight: 800;
  color: #232932;
}
.ent-fan-channel-meta,
.ent-dm-thread-meta {
  margin-top: 4px;
  font-size: calc(9px * var(--fs,1));
  color: rgba(92,98,108,0.74);
}
.ent-dm-thread {
  display: flex;
  align-items: center;
  gap: 10px;
}
.ent-dm-thread-avatar {
  width: 44px;
  height: 44px;
  border-radius: 16px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #d8dae0, #f7f7fa);
  color: #2a2f36;
  font-weight: 800;
  font-size: 16px;
  border: 1px solid rgba(190,193,199,0.56);
}
.ent-dm-thread-main {
  flex: 1;
  min-width: 0;
}
.ent-dm-thread-user {
  font-size: calc(11px * var(--fs,1));
  font-weight: 800;
  color: #232932;
}
.ent-dm-thread-preview {
  margin-top: 4px;
  font-size: calc(10px * var(--fs,1));
  color: rgba(86,92,102,0.82);
  line-height: 1.6;
}
.ent-dm-thread-time {
  flex-shrink: 0;
  font-size: calc(9px * var(--fs,1));
  color: rgba(100,106,116,0.72);
}
@media (max-width: 720px) {
  .ent-weibo-shell,
  .ent-weibo-super-grid,
  .ent-fan-channel-wrap { grid-template-columns: 1fr; }
  .ent-hero,
  .ent-form-grid,
  .ent-roster-grid,
  .ent-hot-list,
  .ent-doc-grid,
  .ent-summary-grid,
  .ent-relation-grid,
  .ent-work-grid { grid-template-columns: 1fr; }
  .ent-quick-grid { grid-template-columns: 1fr; }
  .ent-stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ent-stat-card { min-width: 0; }
}



