/* ===== mono-melody-studio-v40-vinyl-style ===== */

/* v40：把歌曲封面改成黑胶唱片，并在播放时转动 */
#aiMusicStudioPage .v38-cover{
  background:transparent !important;
  box-shadow:none !important;
  padding:8px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
}

#aiMusicStudioPage .v39-vinyl-disc{
  position:relative;
  width:100%;
  aspect-ratio:1 / 1;
  border-radius:50%;
  overflow:hidden;
  display:flex;
  align-items:center;
  justify-content:center;
  background:
    radial-gradient(circle at center, #101010 0 7%, #1a1a1a 7% 11%, #0d0d0d 11% 18%, #1a1a1a 18% 24%, #0d0d0d 24% 32%, #1a1a1a 32% 40%, #0d0d0d 40% 48%, #171717 48% 55%, #0d0d0d 55% 64%, #171717 64% 72%, #0b0b0b 72% 100%);
  box-shadow:
    0 18px 36px rgba(0,0,0,.12),
    inset 0 0 0 1px rgba(255,255,255,.04),
    inset 0 0 0 2px rgba(255,255,255,.02);
  transition:transform .25s ease;
}

#aiMusicStudioPage .v39-vinyl-disc::before{
  content:"";
  position:absolute;
  inset:6%;
  border-radius:50%;
  border:1px solid rgba(255,255,255,.06);
  box-shadow:
    0 0 0 1px rgba(255,255,255,.03) inset,
    0 0 0 10px rgba(255,255,255,.01) inset,
    0 0 0 20px rgba(255,255,255,.012) inset,
    0 0 0 30px rgba(255,255,255,.01) inset;
  pointer-events:none;
}

#aiMusicStudioPage .v39-vinyl-disc.spinning{
  animation:v39VinylSpin 5.4s linear infinite;
}

@keyframes v39VinylSpin{
  from{ transform:rotate(0deg); }
  to{ transform:rotate(360deg); }
}

#aiMusicStudioPage .v39-vinyl-art{
  position:absolute;
  inset:24%;
  border-radius:50%;
  overflow:hidden;
  background:linear-gradient(180deg,#ffffff,#f2f2ee);
  box-shadow:
    0 0 0 8px rgba(255,255,255,.045),
    0 0 0 1px rgba(255,255,255,.08) inset;
  display:flex;
  align-items:center;
  justify-content:center;
}

#aiMusicStudioPage .v39-vinyl-art img{
  width:100% !important;
  height:100% !important;
  object-fit:cover !important;
  border-radius:50% !important;
  display:block !important;
}

#aiMusicStudioPage .v39-vinyl-fallback{
  width:100%;
  height:100%;
  display:flex;
  align-items:center;
  justify-content:center;
  background:linear-gradient(180deg,#ffffff,#ecece7);
  color:#777;
  font-size:40px;
  font-weight:900;
  border-radius:50%;
}

#aiMusicStudioPage .v39-vinyl-cap{
  position:absolute;
