/* ===== mono-dressing-room-styles ===== */

/* ── 换装室 Home Icon ── */
#app-dressing-room {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  position: absolute;
  z-index: 31;
  pointer-events: auto;
}
#app-dressing-room .ig-music-icon-box {
  background: rgba(240,240,240,0.6) !important;
}
#dressingRoomHomeIconBox .custom-icon {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 16px;
  display: block;
}
.home-edit-active #app-dressing-room {
  animation: iconWiggle 0.4s ease-in-out infinite alternate;
}

/* ── 换装室 Page Shell ── */
#dressingRoomPage {
  background: #f5f5f0;
  font-family: -apple-system, 'Helvetica Neue', sans-serif;
}
.dr-shell {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: linear-gradient(160deg, #fafaf8 0%, #f0efea 100%);
  overflow: hidden;
}

/* ── Top Bar ── */
.dr-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 10px;
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(200,196,190,0.35);
  flex-shrink: 0;
  gap: 8px;
}
.dr-top-btn {
  background: none;
  border: none;
  font-size: 13px;
  color: #666;
  cursor: pointer;
  padding: 6px 10px;
  border-radius: 10px;
  transition: background 0.18s;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 5px;
}
.dr-top-btn:active { background: rgba(0,0,0,0.07); }
.dr-title-wrap { text-align: center; flex: 1; min-width: 0; }
.dr-title {
  font-size: 15px;
  font-weight: 700;
  color: #222;
  letter-spacing: 0.5px;
}
.dr-subtitle {
  font-size: 10px;
  color: #999;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin-top: 1px;
}

/* ── Tab Nav ── */
.dr-tabs {
  display: flex;
  align-items: center;
  gap: 0;
  background: rgba(255,255,255,0.7);
  border-bottom: 1px solid rgba(200,196,190,0.3);
  padding: 0 4px;
  overflow-x: auto;
  scrollbar-width: none;
  flex-shrink: 0;
}
.dr-tabs::-webkit-scrollbar { display: none; }
.dr-tab {
  flex-shrink: 0;
  padding: 10px 14px;
  font-size: 12px;
  font-weight: 600;
  color: #999;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
  white-space: nowrap;
}
.dr-tab.active {
  color: #2c2c2c;
  border-bottom-color: #2c2c2c;
}

/* ── Body ── */
.dr-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.dr-body::-webkit-scrollbar { width: 3px; }
.dr-body::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.12); border-radius: 999px; }

/* ── Persona Selector ── */
.dr-persona-strip {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: none;
}
.dr-persona-strip::-webkit-scrollbar { display: none; }
.dr-persona-chip {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  cursor: pointer;
  transition: transform 0.2s;
}
.dr-persona-chip:active { transform: scale(0.92); }
.dr-persona-avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  object-fit: cover;
  border: 2.5px solid transparent;
  transition: border-color 0.2s;
  background: #ddd;
}
.dr-persona-chip.selected .dr-persona-avatar {
  border-color: #2c2c2c;
}
.dr-persona-name {
  font-size: 10px;
  color: #666;
  font-weight: 600;
  white-space: nowrap;
}
.dr-persona-chip.selected .dr-persona-name { color: #222; }

/* ── Section Cards ── */
.dr-card {
  background: rgba(255,255,255,0.88);
  border-radius: 18px;
  padding: 16px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  border: 1px solid rgba(220,216,210,0.5);
  animation: drCardIn 0.35s cubic-bezier(0.22,1,0.36,1) both;
}
@keyframes drCardIn {
  from { opacity: 0; transform: translateY(12px) scale(0.98); }
  to   { opacity: 1; transform: none; }
}
.dr-card-title {
  font-size: 11px;
  font-weight: 700;
  color: #999;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.dr-card-title i { color: #bbb; }

/* ── Generate Button ── */
.dr-gen-btn {
  width: 100%;
  padding: 13px;
  background: #1a1a1a;
  color: #fff;
  border: none;
  border-radius: 14px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: opacity 0.2s, transform 0.15s;
  letter-spacing: 0.3px;
}
.dr-gen-btn:active { transform: scale(0.97); opacity: 0.85; }
.dr-gen-btn:disabled { opacity: 0.45; cursor: default; }
.dr-gen-btn-ghost {
  background: transparent;
  color: #444;
  border: 1.5px solid #ddd;
}
.dr-gen-btn-ghost:active { background: rgba(0,0,0,0.04); }

/* ── Today's Outfit Card ── */
.dr-outfit-display {
  min-height: 80px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.dr-outfit-item {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.dr-outfit-category {
  min-width: 52px;
  font-size: 10px;
  font-weight: 700;
  color: #aaa;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  padding-top: 2px;
}
.dr-outfit-value {
  font-size: 13px;
  color: #222;
  line-height: 1.5;
  flex: 1;
}
.dr-outfit-reason {
  margin-top: 8px;
  font-size: 12px;
  color: #777;
  line-height: 1.6;
  padding: 10px 12px;
  background: rgba(0,0,0,0.03);
  border-radius: 10px;
  border-left: 3px solid #ddd;
  font-style: italic;
}

/* ── Reaction Bubble ── */
.dr-reaction {
  margin-top: 10px;
  padding: 12px 14px;
  background: rgba(28,28,28,0.06);
  border-radius: 14px;
  font-size: 13px;
  color: #333;
  line-height: 1.7;
  animation: drCardIn 0.4s cubic-bezier(0.22,1,0.36,1) both;
  position: relative;
}
.dr-reaction::before {
  content: '';
  position: absolute;
  left: 16px;
  top: -7px;
  border: 7px solid transparent;
  border-bottom-color: rgba(28,28,28,0.06);
  border-top: none;
}
.dr-reaction-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  object-fit: cover;
  vertical-align: middle;
  margin-right: 7px;
  border: 1px solid rgba(0,0,0,0.08);
}

/* ── Score Card ── */
.dr-score-grid {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.dr-score-row {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(255,255,255,0.78);
  border: 1px solid rgba(190,185,178,.28);
}
.dr-score-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
  flex-wrap: wrap;
}
.dr-score-label {
  font-size: 11px;
  color: #888;
  font-weight: 700;
  min-width: 0;
  line-height: 1.45;
  flex: 1;
  white-space: normal;
  overflow-wrap: anywhere;
}
.dr-score-row.dr-score-row-text .dr-score-head {
  display: block;
}
.dr-score-bar-wrap {
  width: 100%;
  height: 5px;
  background: rgba(0,0,0,0.08);
  border-radius: 999px;
  overflow: hidden;
  min-width: 0;
}
.dr-score-bar {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #c0b8a8, #2c2c2c);
  transition: width 0.8s cubic-bezier(0.22,1,0.36,1);
}
.dr-score-bar-wrap.dr-score-bar-wrap-empty {
  display: none;
}
.dr-score-value {
  font-size: 12px;
  font-weight: 700;
  color: #2f2a24;
  text-align: left;
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  display: block;
  width: 100%;
  margin-top: 6px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(246,243,238,.9);
  border: 1px solid rgba(190,185,178,.22);
}
.dr-score-value.dr-score-value-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  text-align: center;
  line-height: 1.4;
  flex-shrink: 0;
  white-space: normal;
  width: auto;
  min-width: 48px;
  margin-top: 0;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(44,44,44,.07);
  border: 1px solid rgba(44,44,44,.08);
}
.dr-score-summary {
  margin-bottom: 10px;
  padding: 12px 13px;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(255,255,255,.88), rgba(246,243,238,.96));
  border: 1px solid rgba(190,185,178,.32);
}
.dr-score-summary-title {
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .8px;
  color: #8d847a;
  text-transform: uppercase;
}
.dr-score-summary-main {
  margin-top: 4px;
  font-size: 13px;
  font-weight: 800;
  color: #2e2923;
  line-height: 1.5;
  white-space: normal;
  overflow-wrap: anywhere;
}
.dr-score-summary-text {
  margin-top: 6px;
  font-size: 12px;
  line-height: 1.7;
  color: #5e554d;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* ── Wardrobe Grid ── */
.dr-wardrobe-tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}
.dr-wardrobe-cat-btn {
  padding: 6px 12px;
  border-radius: 20px;
  border: 1.5px solid #ddd;
  background: transparent;
  font-size: 11px;
  font-weight: 600;
  color: #666;
  cursor: pointer;
  transition: all 0.18s;
  white-space: nowrap;
}
.dr-wardrobe-cat-btn.active {
  background: #1a1a1a;
  border-color: #1a1a1a;
  color: #fff;
}
.dr-items-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 8px;
  margin-top: 8px;
}
.dr-item-chip {
  padding: 10px 12px;
  background: rgba(255,255,255,0.9);
  border-radius: 12px;
  border: 1.5px solid transparent;
  cursor: pointer;
  font-size: 12px;
  color: #333;
  line-height: 1.4;
  transition: border-color 0.18s, transform 0.15s, box-shadow 0.18s;
  position: relative;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
}
.dr-item-chip:active { transform: scale(0.96); }
.dr-item-chip.selected {
  border-color: #1a1a1a;
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
}
.dr-item-chip-label {
  font-weight: 600;
  font-size: 11px;
  color: #aaa;
  margin-bottom: 3px;
  letter-spacing: 0.5px;
}
.dr-item-add-btn {
  width: 100%;
  margin-top: 8px;
  padding: 10px;
  background: transparent;
  border: 1.5px dashed #ccc;
  border-radius: 12px;
  color: #bbb;
  font-size: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: border-color 0.18s, color 0.18s;
}
.dr-item-add-btn:active { border-color: #888; color: #888; }

/* ── Custom Input ── */
.dr-custom-input {
  width: 100%;
  padding: 11px 14px;
  border: 1.5px solid #e5e2db;
  border-radius: 12px;
  background: rgba(255,255,255,0.8);
  font-size: 13px;
  color: #222;
  outline: none;
  transition: border-color 0.18s;
  box-sizing: border-box;
  font-family: inherit;
  resize: none;
}
.dr-custom-input:focus { border-color: #999; }
.dr-custom-textarea {
  min-height: 70px;
}

/* ── Loading Shimmer ── */
.dr-loading {
  display: flex;
  flex-direction: column;
  gap: 8px;
  animation: drFadeIn 0.3s ease both;
}
@keyframes drFadeIn { from { opacity:0; } to { opacity:1; } }
.dr-shimmer {
  height: 16px;
  border-radius: 8px;
  background: linear-gradient(90deg, #f0eee9 25%, #e8e5df 50%, #f0eee9 75%);
  background-size: 200% 100%;
  animation: drShimmer 1.4s linear infinite;
}
@keyframes drShimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ── Plot/Story Card ── */
.dr-story {
  font-size: 13px;
  color: #333;
  line-height: 1.85;
  padding: 14px;
  background: rgba(0,0,0,0.025);
  border-radius: 12px;
  border-left: 3px solid #bfb9ad;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-wrap: anywhere;
}
.dr-story-box {
  font-size: 13px;
  color: #333;
  line-height: 1.85;
  padding: 14px;
  background: rgba(0,0,0,0.025);
  border-radius: 12px;
  border-left: 3px solid #bfb9ad;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-wrap: anywhere;
}

/* ── Image Preview ── */
.dr-img-preview {
  width: 100%;
  border-radius: 14px;
  overflow: hidden;
  background: #f0efea;
  min-height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.dr-img-preview img {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 14px;
}
.dr-img-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: #bbb;
  font-size: 12px;
}
.dr-img-placeholder i { font-size: 32px; }

/* ── Couple/Pairing section ── */
.dr-couple-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.dr-couple-side {
  background: rgba(0,0,0,0.03);
  border-radius: 12px;
  padding: 12px;
}
.dr-couple-side-label {
  font-size: 10px;
  font-weight: 700;
  color: #bbb;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.dr-couple-outfit-text {
  font-size: 12px;
  color: #333;
  line-height: 1.6;
}
.dr-couple-eval {
  margin-top: 10px;
  font-size: 12px;
  color: #666;
  font-style: italic;
  line-height: 1.6;
  padding: 10px;
  border-radius: 10px;
  background: rgba(0,0,0,0.04);
}

/* ── Memory Card ── */
.dr-memory-item {
  padding: 12px 14px;
  background: rgba(255,255,255,0.7);
  border-radius: 12px;
  border: 1px solid rgba(220,215,208,0.5);
  display: flex;
  flex-direction: column;
  gap: 4px;
  animation: drCardIn 0.3s both;
}
.dr-memory-outfit { font-size: 12px; color: #333; font-weight: 600; }
.dr-memory-context { font-size: 11px; color: #999; line-height: 1.5; }
.dr-memory-date { font-size: 10px; color: #ccc; }

/* ── Send-to-chat button ── */
.dr-send-chat-btn {
  padding: 8px 14px;
  background: transparent;
  border: 1.5px solid #ccc;
  border-radius: 10px;
  font-size: 11px;
  color: #666;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 5px;
  transition: all 0.18s;
  white-space: nowrap;
}
.dr-send-chat-btn:active { background: #f5f5f0; }

/* ── Occasion input row ── */
.dr-occasion-row {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}
.dr-occasion-chip {
