/* ── Tabs Content ── */
.dr-tab-content { display: none; }
.dr-tab-content.active { display: flex; flex-direction: column; gap: 14px; }

/* ── Empty state ── */
.dr-empty {
  text-align: center;
  padding: 30px 20px;
  color: #bbb;
  font-size: 13px;
  line-height: 1.7;
}
.dr-empty i { font-size: 36px; margin-bottom: 10px; display: block; }

/* ── Spinner ── */
.dr-spinner {
  display: inline-block;
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255,255,255,0.3);
  border-top-color: #fff;
  border-radius: 50%;
  animation: drSpin 0.7s linear infinite;
}
.dr-spinner-dark {
  border: 2px solid rgba(0,0,0,0.1);
  border-top-color: #333;
}
@keyframes drSpin { to { transform: rotate(360deg); } }

/* ── Toast ── */
.dr-toast {
  position: fixed;
  bottom: 80px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: rgba(30,30,30,0.9);
  color: #fff;
  padding: 9px 18px;
  border-radius: 20px;
  font-size: 13px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s, transform 0.3s;
  z-index: 9999;
  white-space: nowrap;
}
.dr-toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

