.tm-step{font-size:10px;color:rgba(255,255,255,.44);letter-spacing:.7px;font-weight:800;display:flex;align-items:center;gap:9px;position:relative;text-transform:uppercase;}
.tm-step b{width:19px;height:19px;border-radius:5px;background:rgba(255,255,255,.11);display:flex;align-items:center;justify-content:center;color:rgba(255,255,255,.45);font-size:10px;}
.tm-step.active{color:#fff;}
.tm-step.active b{background:#ff3b30;color:#fff;}
.tm-step.active:after{content:'';position:absolute;left:0;right:0;bottom:-1px;height:2px;background:#ff3b30;}
.tm-screen{height:48px;margin:0 auto 24px;max-width:440px;background:linear-gradient(180deg,#8d8d8d,#666);clip-path:polygon(0 0,100% 0,88% 100%,12% 100%);box-shadow:0 20px 25px rgba(255,255,255,.08);opacity:.68;}
.tm-seat-map{display:flex;flex-direction:column;align-items:center;gap:6px;perspective:900px;}
.tm-seat-row{display:flex;gap:5px;align-items:center;}
.tm-seat{width:15px;height:15px;border-radius:3px;background:#5f5f5f;cursor:pointer;box-shadow:0 1px 0 rgba(255,255,255,.08) inset;transition:.12s;}
.tm-seat:hover{background:#8a8a8a;transform:translateY(-1px);}
.tm-seat.selected{background:#ff1208;box-shadow:0 0 14px rgba(255,24,16,.72);transform:scale(1.08);}
.tm-seat.aisle{margin-left:12px;}
.tm-seat.future{opacity:.45;}
.tm-right-info{padding-top:102px;display:flex;flex-direction:column;gap:22px;}
.tm-info-block small{display:block;color:rgba(255,255,255,.35);font-size:10px;margin-bottom:7px;}
.tm-info-block b{display:block;color:#fff;font-size:16px;line-height:1.1;}
.tm-date-box{border:1px solid rgba(255,255,255,.14);width:72px;height:72px;display:flex;flex-direction:column;align-items:center;justify-content:center;}
.tm-date-box .day{font-size:30px;color:#fff;line-height:1;}
.tm-date-box .mon{font-size:11px;font-weight:900;color:#fff;margin-top:5px;}
.tm-seat-hint{font-size:10px;color:rgba(255,255,255,.38);line-height:1.6;max-width:142px;}

/* ── Payment / Typewriter ── */
.tm-pay-wrap{width:100%;display:grid;grid-template-columns:190px minmax(0,1fr);gap:18px;align-items:stretch;padding-top:18px;}
.tm-token-machine{min-height:452px;border-radius:22px;background:linear-gradient(145deg,#7b7878,#3b393a 58%,#77716b);box-shadow:inset 0 0 0 2px rgba(255,255,255,.16),inset 0 0 36px rgba(255,255,255,.08),0 24px 70px rgba(0,0,0,.48);position:relative;padding:24px 16px;overflow:hidden;}
.tm-token-machine:before{content:'';position:absolute;inset:8px;border:1px solid rgba(0,0,0,.45);border-radius:17px;box-shadow:inset 0 0 0 1px rgba(255,255,255,.16);pointer-events:none;}
.tm-screw{position:absolute;width:15px;height:15px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#fafafa,#5c5c5c);box-shadow:inset 0 0 0 2px rgba(0,0,0,.45);}
.tm-screw:after{content:'';position:absolute;left:3px;right:3px;top:7px;height:2px;background:#222;transform:rotate(-35deg);}
.tm-screw.s1{left:12px;top:12px}.tm-screw.s2{right:12px;top:12px}.tm-screw.s3{left:12px;bottom:12px}.tm-screw.s4{right:12px;bottom:12px}
.tm-slot-ring{width:118px;height:118px;margin:10px auto 28px;border-radius:50%;background:radial-gradient(circle at 35% 25%,#f9f9f9,#8e8a86 45%,#3a3838 72%,#b8b4ad);box-shadow:0 8px 20px rgba(0,0,0,.34),inset -10px -8px 18px rgba(0,0,0,.25);display:flex;align-items:center;justify-content:center;}
.tm-slot{width:17px;height:86px;border-radius:999px;background:#050505;box-shadow:inset 0 0 12px #000;}
.tm-token-label{margin:0 auto 34px;width:136px;padding:9px 6px;border-radius:8px;background:linear-gradient(180deg,#a59e99,#5c5654);border:3px solid #c9c0bb;box-shadow:inset 0 0 0 2px rgba(0,0,0,.28);text-align:center;font-size:20px;font-weight:1000;line-height:.88;color:#dcd5cf;text-shadow:0 2px 0 #222;letter-spacing:1px;}
.tm-paid-lamp{font-size:10px;text-align:center;color:#a6a6a6;margin-bottom:20px;letter-spacing:1px;font-weight:900;}
.tm-paid-lamp.on{color:#9cffb1;text-shadow:0 0 10px rgba(156,255,177,.8);}
.tm-coin{position:absolute;left:50%;top:78%;width:36px;height:36px;border-radius:50%;background:radial-gradient(circle at 32% 28%,#fff7b5,#d59722 45%,#7d4a0a);box-shadow:0 8px 18px rgba(0,0,0,.45);transform:translateX(-50%);z-index:5;display:flex;align-items:center;justify-content:center;font-size:13px;color:#70430a;font-weight:1000;}
.tm-coin.fly{animation:tmCoinFly 1s cubic-bezier(.3,.8,.25,1) both;}
@keyframes tmCoinFly{0%{left:50%;top:78%;transform:translateX(-50%) rotate(0) scale(1)}70%{left:50%;top:76px;transform:translateX(-50%) rotate(520deg) scale(.82)}100%{left:50%;top:72px;transform:translateX(-50%) rotate(640deg) scale(.15);opacity:0}}
.tm-typewriter-zone{position:relative;min-height:560px;border-radius:28px;background:linear-gradient(180deg,#f4f0e8,#e7e1d5);box-shadow:0 24px 80px rgba(0,0,0,.42);overflow:hidden;color:#141414;}
.tm-typewriter-zone:before{content:'boring office';position:absolute;top:22px;right:28px;font:12px 'Courier New',monospace;color:#161616;letter-spacing:.4px;z-index:3;}
.tm-typewriter-zone:after{content:'omont.2020';position:absolute;top:22px;left:28px;font:12px 'Courier New',monospace;color:#161616;text-decoration:line-through;z-index:3;}
.tm-paper-stage{position:absolute;left:5%;right:5%;bottom:136px;height:390px;overflow:hidden;z-index:2;}
.tm-paper{position:absolute;left:0;right:0;bottom:-390px;min-height:360px;background:#fbf5e9;border-radius:30px 6px 0 0;padding:40px 22px 28px;box-shadow:0 -8px 28px rgba(0,0,0,.10);font-family:'Courier New',monospace;transition:bottom 1.25s cubic-bezier(.22,1,.36,1);}
.tm-paper.printing,.tm-paper.done{bottom:0;}
.tm-paper:before{content:'';position:absolute;left:22px;right:22px;top:34px;border-top:1px solid #111;opacity:.7;}
.tm-ticket-art{background:#fff;color:#111;border:2px solid #111;position:relative;min-height:300px;padding:0 0 18px;overflow:hidden;box-shadow:6px 8px 0 #111;}
.tm-ticket-art:before,.tm-ticket-art:after{content:'';position:absolute;left:0;right:0;height:15px;background:radial-gradient(circle at 8px 8px,#fbf5e9 0 6px,transparent 6.5px) repeat-x;background-size:26px 15px;z-index:3;}
.tm-ticket-art:before{top:-2px}.tm-ticket-art:after{bottom:-2px;transform:rotate(180deg)}
.tm-ticket-cover{height:178px;background:#111;position:relative;overflow:hidden;border-bottom:2px solid #111;display:flex;align-items:center;justify-content:center;}
.tm-ticket-cover img{width:100%;height:100%;object-fit:cover;filter:grayscale(1) contrast(1.4);mix-blend-mode:multiply;opacity:.92;}
.tm-ticket-cover .placeholder{font-size:58px;font-weight:1000;color:#fff;letter-spacing:-2px;}
.tm-ticket-cover:after{content:'';position:absolute;inset:0;background:repeating-linear-gradient(135deg,rgba(255,255,255,.85) 0 2px,transparent 2px 6px);mix-blend-mode:screen;opacity:.22;pointer-events:none;}
.tm-ticket-info{padding:14px 16px 0;}
.tm-ticket-title{font-size:20px;line-height:1.12;font-weight:1000;letter-spacing:.2px;border-bottom:2px dotted #111;padding-bottom:9px;margin-bottom:8px;}
.tm-ticket-meta{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;border-bottom:2px dotted #111;padding-bottom:9px;margin-bottom:9px;font-size:11px;font-weight:800;}
.tm-ticket-meta span{display:block;font-size:9px;color:#666;font-weight:700;letter-spacing:.8px;text-transform:uppercase;margin-bottom:3px;}
.tm-ticket-choice{font-size:12px;line-height:1.6;font-weight:900;margin-bottom:8px;}
.tm-ticket-content{font-size:12px;line-height:1.72;white-space:pre-wrap;max-height:210px;overflow:auto;padding-right:3px;}
.tm-ticket-content::-webkit-scrollbar{width:3px}.tm-ticket-content::-webkit-scrollbar-thumb{background:#111;border-radius:99px}
.tm-ticket-note{font-size:10px;color:#666;border-top:1px solid #111;margin-top:10px;padding-top:7px;}
.tm-typewriter{position:absolute;left:0;right:0;bottom:0;height:154px;background:linear-gradient(180deg,#d9d0b6,#b9b086 62%,#8d835f);border-top:4px solid #222;z-index:4;box-shadow:0 -15px 28px rgba(0,0,0,.20);}
.tm-typewriter:before{content:'';position:absolute;left:7%;right:7%;top:24px;height:18px;background:#252525;border-radius:999px;box-shadow:0 12px 0 rgba(0,0,0,.22);}
.tm-typewriter:after{content:'OMONT';position:absolute;left:0;right:0;top:52px;text-align:center;font-weight:1000;font-size:18px;letter-spacing:1px;color:rgba(255,255,255,.36);text-shadow:0 1px 0 rgba(0,0,0,.35);}
.tm-keys{position:absolute;left:10%;right:10%;bottom:18px;display:grid;grid-template-columns:repeat(11,1fr);gap:6px;}
.tm-key{height:22px;border-radius:9px;background:linear-gradient(180deg,#eee8c7,#bdb686);box-shadow:inset 0 -2px 0 rgba(0,0,0,.2);}
.tm-print-toolbar{position:absolute;right:16px;bottom:166px;z-index:6;display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;}
.tm-mini-btn{border:1px solid rgba(0,0,0,.25);background:rgba(255,255,255,.72);color:#111;border-radius:999px;padding:8px 11px;font-size:11px;font-weight:900;cursor:pointer;backdrop-filter:blur(8px);}
.tm-empty-paper{text-align:center;padding-top:120px;color:#777;font:12px 'Courier New',monospace;}
.tm-loading-lines{display:flex;flex-direction:column;gap:8px;padding-top:90px;}
.tm-loading-lines i{height:10px;border-radius:99px;background:#cfc8bc;display:block;animation:tmPulse 1s ease-in-out infinite alternate;}
.tm-loading-lines i:nth-child(2){width:82%;animation-delay:.15s}.tm-loading-lines i:nth-child(3){width:64%;animation-delay:.28s}.tm-loading-lines i:nth-child(4){width:91%;animation-delay:.4s}
@keyframes tmPulse{from{opacity:.35;transform:scaleX(.9)}to{opacity:.95;transform:scaleX(1)}}

/* ── Records ── */
.tm-records{width:100%;display:flex;flex-direction:column;gap:14px;padding-top:16px;}
.tm-records-head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;}
.tm-records-title{font-size:22px;font-weight:1000;letter-spacing:.5px;}
.tm-records-sub{font-size:11px;color:rgba(255,255,255,.45);margin-top:3px;}
.tm-record-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px;}
.tm-record-card{border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.03));border-radius:18px;overflow:hidden;cursor:pointer;position:relative;box-shadow:0 12px 38px rgba(0,0,0,.28);transition:.18s;}
.tm-record-card:hover{transform:translateY(-3px);border-color:rgba(255,59,48,.45);}
.tm-record-cover{height:124px;background:#111;overflow:hidden;display:flex;align-items:center;justify-content:center;}
.tm-record-cover img{width:100%;height:100%;object-fit:cover;filter:grayscale(1) contrast(1.25);}
.tm-record-body{padding:12px;}
.tm-record-title{font-size:14px;font-weight:1000;line-height:1.25;margin-bottom:6px;color:#fff;}
.tm-record-meta{font-size:10px;color:rgba(255,255,255,.45);line-height:1.5;}
.tm-record-text{font-size:11px;color:rgba(255,255,255,.62);line-height:1.55;margin-top:8px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;}
.tm-record-del{position:absolute;right:9px;top:9px;width:26px;height:26px;border-radius:50%;border:0;background:rgba(0,0,0,.55);color:#fff;cursor:pointer;z-index:3;}
.tm-empty{border:1px dashed rgba(255,255,255,.16);border-radius:18px;padding:28px;text-align:center;color:rgba(255,255,255,.48);font-size:12px;line-height:1.7;}

/* ── Detail modal ── */
#tmTicketModal{position:fixed;inset:0;z-index:10050;background:rgba(0,0,0,.68);backdrop-filter:blur(10px);display:none;align-items:center;justify-content:center;padding:20px;}
#tmTicketModal.open{display:flex;}
.tm-modal-card{width:min(520px,100%);max-height:86vh;overflow:auto;background:#fbf5e9;color:#111;border-radius:22px;padding:16px;box-shadow:0 30px 80px rgba(0,0,0,.5);position:relative;}
.tm-modal-close{position:absolute;right:14px;top:14px;width:30px;height:30px;border-radius:50%;border:1px solid rgba(0,0,0,.15);background:#fff;cursor:pointer;font-size:18px;z-index:4;}
.tm-modal-card .tm-ticket-art{box-shadow:none;}

@media (max-width:760px){
  .tm-navlinks{gap:5px;font-size:10px}.tm-navlinks .tm-sign{padding:7px 9px}.tm-logo{font-size:18px}.tm-logo span{font-size:9px;letter-spacing:4px}
  .tm-cinema{grid-template-columns:120px minmax(0,1fr);gap:12px;padding-top:28px}.tm-right-info{grid-column:1/3;display:grid;grid-template-columns:repeat(3,1fr);padding-top:0;gap:10px}.tm-title-big{display:none}.tm-poster{height:186px}.tm-main-stage{padding-top:72px}.tm-step span{display:none}.tm-seat{width:12px;height:12px}.tm-seat-row{gap:4px}.tm-screen{height:34px}.tm-pay-wrap{grid-template-columns:1fr;}.tm-token-machine{min-height:270px}.tm-typewriter-zone{min-height:560px}.tm-paper-stage{left:3%;right:3%;}.tm-ticket-meta{grid-template-columns:1fr 1fr}.tm-panel{padding:0 12px 18px}
}

/* ── Portrait phone layout override (v2) ── */
#ticketMachinePage{padding:10px;box-sizing:border-box;justify-content:center;align-items:center;overflow:auto;background:radial-gradient(circle at 50% -10%,rgba(255,59,48,.12),transparent 35%),#050505;}
