.tm-shell{width:min(430px,100%);height:min(calc(100dvh - 20px),920px);min-height:720px;max-width:430px;margin:0 auto;border-radius:34px;border:1px solid rgba(255,255,255,.08);box-shadow:0 30px 90px rgba(0,0,0,.52), inset 0 0 0 1px rgba(255,255,255,.03);overflow:hidden;}
.tm-topnav{padding:14px 14px 8px;gap:8px;}
.tm-logo{font-size:18px;}
.tm-logo span{font-size:9px;letter-spacing:4px;}
.tm-navlinks{gap:4px;font-size:10px;flex-wrap:wrap;justify-content:flex-end;max-width:70%;}
