.tm-poster-col,.tm-right-info,.tm-main-stage{width:100%;}
.tm-poster-col{order:1;}
.tm-right-info{order:2;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding-top:0;align-items:start;}
