.tm-persona-list{max-height:220px;overflow:auto;}
.tm-stepbar{margin-bottom:16px;}
.tm-step span{display:none;}
.tm-screen{height:34px;max-width:280px;margin-bottom:18px;}
.tm-seat-map{overflow-x:auto;padding-bottom:6px;align-items:flex-start;}
.tm-seat-row{gap:4px;min-width:max-content;}
.tm-seat{width:12px;height:12px;flex:0 0 auto;}
