/* ===== mono-secondary-api-delete-hard-fix-style ===== */

  .mono-secapi-delete-overlay{
    position:fixed!important; inset:0!important; z-index:2147483647!important;
    display:flex!important; align-items:center!important; justify-content:center!important;
    padding:calc(env(safe-area-inset-top,0px) + 18px) 16px calc(env(safe-area-inset-bottom,0px) + 18px)!important;
    background:rgba(0,0,0,.36)!important; backdrop-filter:blur(12px)!important; -webkit-backdrop-filter:blur(12px)!important;
    box-sizing:border-box!important; pointer-events:auto!important;
  }
