    border:1px solid rgba(230,230,230,.95)!important; box-shadow:0 26px 80px rgba(0,0,0,.24)!important;
    padding:18px!important; box-sizing:border-box!important; font-family:inherit!important; pointer-events:auto!important;
  }
  .mono-secapi-delete-handle{width:42px;height:4px;border-radius:999px;background:rgba(160,160,160,.45);margin:0 auto 14px;}
  .mono-secapi-delete-title{font-size:15px;font-weight:900;text-align:center;letter-spacing:.5px;margin-bottom:9px;color:#1f1f1f;}
